window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0144", [{"word":"mural","ipa_uk":"/ˈmjʊərəl/","ipa_us":"/ˈmjʊrəl/","definition_zh":"壁画；墙画；（作定语）墙壁的；墙面大型显示画面","definition_en":"a painting made directly on a wall; also used attributively for things fixed to or forming a wall","core_image":"一整面高墙被画面完全覆盖，颜料直接吃进灰泥里，人站在墙前像站在画中","scene":"美术馆走廊的尽头有一整面高墙，工作人员正刷上最后一层保护漆，The restorer climbs a scaffold to clean the mural above the doorway.","sceneCN":"这里 mural 指「直接画在墙面上的整幅绘画」（第 1 个义项：墙面绘画）；句意为修复师爬上脚手架，清理门上方那幅壁画。图中可辨识物件：高墙、脚手架、修复刷与整幅画面。","pos":[{"tag":"n.","zh":"壁画；墙画"},{"tag":"adj.","zh":"墙壁的；墙上的"}],"collocations":[{"phrase":"mural painting","zh":"壁画；墙面绘画"},{"phrase":"a mural of","zh":"一幅描绘……的壁画"},{"phrase":"paint a mural","zh":"绘制壁画"},{"phrase":"street mural","zh":"街头壁画"},{"phrase":"mural artist","zh":"壁画艺术家"},{"phrase":"ceiling mural","zh":"天顶壁画"}],"forms":[{"label":"复数","form":"murals"}],"derivatives":[{"word":"muralist","pos":"n.","zh":"壁画家；壁画创作者"},{"word":"muralism","pos":"n.","zh":"壁画艺术；壁画运动"}],"senses":[{"no":"01","title":"A painting made on a wall","titleCN":"直接画在墙面上的绘画","definition":"a picture painted directly onto a wall surface","definitionCN":"直接绘制在墙面上的一幅画","example":"The mural covers the whole eastern wall of the library.","exampleCN":"这幅壁画覆盖了图书馆东侧的整面墙。","why":"The word comes from Latin muralis, 'of a wall', so the painting is named after the surface it belongs to rather than after a frame.","whyCN":"这个词来自拉丁语 muralis「墙的」，所以画是以它所属的墙面命名，而不是以画框命名。"},{"no":"02","title":"A public artwork on an outdoor wall","titleCN":"户外墙面上的公共艺术作品","definition":"a large painting on an exterior wall, often made for a neighbourhood or a cause","definitionCN":"画在外墙上的大型绘画，常为社区或某项议题而作","example":"A mural of migrating birds now runs along the school fence.","exampleCN":"一幅候鸟壁画如今沿学校围墙铺开。","why":"When the wall faces a street, the picture addresses everyone who passes, so the sense shifts from private decoration to public statement.","whyCN":"当墙面朝向街道，画就在向每个路过的人说话，词义便从私人装饰转向公共表达。"},{"no":"03","title":"A wall-sized picture inside a building","titleCN":"建筑内部占满墙面的画","definition":"a very large picture covering an interior wall, as in a lobby, hotel or restaurant","definitionCN":"覆盖室内墙面的大幅画作，常见于大堂、酒店或餐馆","example":"The hotel lobby mural depicts the city before the railway arrived.","exampleCN":"酒店大堂的壁画描绘了铁路通车前的城市。","why":"The same surface logic holds indoors: the picture is sized to the wall and becomes part of the room rather than an object standing in it.","whyCN":"同样的墙面逻辑也适用于室内：画按墙的尺寸展开，成为房间的一部分，而不是立在房间里的物件。"},{"no":"04","title":"Of or fixed to a wall (attributive)","titleCN":"墙壁的；固定于墙上的（定语用法）","definition":"used before a noun to mean belonging to, attached to or forming a wall","definitionCN":"置于名词前，表示属于墙壁、附着于墙或构成墙的","example":"The chapel is known for its mural decoration and painted ceiling.","exampleCN":"这座小教堂以墙面装饰和彩绘天顶闻名。","why":"This is the oldest layer of the word: the Latin adjective described anything that pertained to a wall, and English kept that use beside the noun.","whyCN":"这是这个词最古老的一层：拉丁形容词本指任何与墙有关之物，英语把这个用法与名词义保留在一起。"},{"no":"05","title":"Of the wall of a body cavity (anatomy)","titleCN":"体腔壁的（解剖学）","definition":"in medicine, relating to the wall of an organ or cavity rather than to its contents","definitionCN":"医学中，指器官或腔体的壁，而非其内部内容物","example":"The scan showed a mural thickening in the lower intestine.","exampleCN":"扫描显示下段肠道有肠壁增厚。","why":"Anatomy borrowed the Latin sense directly: whatever sits in or belongs to a wall is mural, so a clot attached to a heart wall is a mural thrombus.","whyCN":"解剖学直接借用了拉丁义：凡是位于壁上或属于壁的都叫 mural，因此附着在心脏壁上的血栓称为壁性血栓。"},{"no":"06","title":"A wall-mounted interactive image","titleCN":"装在墙上的互动画面","definition":"a digital image or interactive surface mounted flat on a wall, often in a gallery or control room","definitionCN":"平贴在墙上的数字图像或互动界面，常见于展馆或控制室","example":"Visitors can drag a timeline across the digital mural in the entrance hall.","exampleCN":"参观者可以在入口大厅的数字壁画上拖动时间轴。","why":"Digital displays inherit the two defining traits of a mural, being large and fixed to a wall, and the name follows the form rather than the pigment.","whyCN":"数字显示屏继承了壁画的两个核心特征——尺幅大、固定在墙上——名称便随形态延续，而不随颜料延续。"},{"no":"07","title":"A wall-sized array of screens","titleCN":"由多块屏幕拼成的墙面显示阵列","definition":"a large video wall built from many tiled displays and treated as one continuous image","definitionCN":"由多块拼接显示屏构成、当作一幅连续画面使用的大型屏幕墙","example":"The operations centre monitors the grid on a six-metre video mural.","exampleCN":"运营中心在一块六米长的屏幕墙上监控电网。","why":"Once many screens are aligned without visible seams, the result looks like one painted surface, which is why the older word is applied to the newer wall.","whyCN":"当许多屏幕无缝对齐，整体看起来就像一整块绘制的表面，旧词因此被用在这种新墙上。"},{"no":"08","title":"A surrounding field of images","titleCN":"环绕观看者的整片图像","definition":"a continuous visual field that surrounds viewers and replaces the ordinary walls of a space","definitionCN":"环绕观看者、替代空间普通墙面的连续视觉场","example":"The installation wraps the audience in a slow-moving mural of ocean light.","exampleCN":"这件装置用一片缓慢流动的海光壁画把观众包围起来。","why":"The figurative step is small: if a mural can cover a wall, enough murals can cover every wall, and the picture becomes the room itself.","whyCN":"这一步比喻跨度很小：既然一幅壁画能覆盖一面墙，足够多的壁画就能覆盖所有墙面，画便成了房间本身。"}],"etymology":{"intro":{"en":"Mural comes from Latin muralis 'of a wall', built on murus 'wall' with the adjective suffix -alis. Dates are approximate.","cn":"mural 来自拉丁语 muralis「墙的」，由 murus「墙」加形容词后缀 -alis 构成。年代均为约数。"},"items":[{"era":"LATIN MURUS","en":"Murus meant 'wall', especially the wall of a house or a city. Its deeper origin is not established, and the links sometimes proposed to other Indo-European wall words are hypotheses rather than demonstrated derivations.","cn":"murus 意为「墙」，尤指房屋或城墙。其更深来源未得到证明；有人把它与其他印欧语系的「墙」词联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN MURALIS","en":"The suffix -alis 'pertaining to' produced muralis, an adjective for anything that belonged to or stood on a wall.","cn":"后缀 -alis「属于……的」构成 muralis，指任何属于墙或立于墙上的事物。"},{"era":"ENGLISH ADJECTIVE","en":"English received mural in the fifteenth century as an adjective describing walled structures and wall decoration.","cn":"英语在 15 世纪接受了 mural，用作描述有墙结构及墙面装饰的形容词。"},{"era":"PAINTING NOUN","en":"By the nineteenth century the phrase mural painting was shortened to the noun mural, and the picture rather than the wall became the thing named.","cn":"到 19 世纪，「墙面绘画」这一短语缩略为名词，被命名的事物从墙面转到了画本身。"},{"era":"PUBLIC ART","en":"In the twentieth century, especially through Mexican and American mural movements, the noun came to name large public works painted on exterior walls.","cn":"在 20 世纪，尤其经由墨西哥与美国的壁画运动，这个名词开始指画在外墙上的大型公共作品。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of murus is unsettled, so any Indo-European root offered for it is a reconstruction rather than a witnessed form.","cn":"来源不确定（更深词源）：murus 在拉丁语之前的来源并无定论，凡为其提出的印欧词根均属重构形式，而非实际书证。"}]},"similar":{"note":{"en":"The first group contains words that sound close to mural but come from other roots; the second contains words for wall pictures that differ in technique, scale or intent.","cn":"第一组是读音接近但词根不同的词；第二组指墙面图画，但在技法、尺度或意图上有别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"moral","ipa":"/ˈmɒrəl/","tag":"different root","definition":"Concerned with right and wrong behaviour; it comes from Latin mos 'custom', not from murus 'wall'.","definitionCN":"关于行为是非的；来自拉丁 mos「习俗」，与 murus「墙」无关。"},{"word":"morale","ipa":"/məˈrɑːl/","tag":"different root","definition":"The spirit and confidence of a group; it shares the mos root and has nothing to do with walls.","definitionCN":"群体的士气与信心；同属 mos 词根，与墙无关。"},{"word":"murals","ipa":"/ˈmjʊərəlz/","tag":"same word, plural","definition":"Simply the plural of mural, not a separate term.","definitionCN":"只是 mural 的复数形式，并非另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fresco","ipa":"/ˈfreskəʊ/","tag":"technique","definition":"A wall painting made on fresh lime plaster, so the pigment sets into the wall itself; fresco names the method, mural names the surface.","definitionCN":"画在新鲜石灰灰泥上的墙画，颜料随灰泥固化进入墙体；fresco 指技法，mural 指墙面。"},{"word":"wall painting","ipa":"/wɔːl ˈpeɪntɪŋ/","tag":"general term","definition":"A neutral cover term for any picture on a wall, whether painted wet or dry.","definitionCN":"任何墙面绘画的中性统称，无论湿画还是干画。"},{"word":"graffiti","ipa":"/ɡrəˈfiːti/","tag":"different intent","definition":"Words or tags written or sprayed on walls; usually text-based and unauthorized rather than a composed picture.","definitionCN":"写在或喷在墙上的文字与标记；通常以文字为主、未经许可，不是完整构图的画。"},{"word":"street art","ipa":"/striːt ɑːt/","tag":"broader category","definition":"Art made in public spaces by any method; a mural is one form of street art, not its equivalent.","definitionCN":"以任何方式在公共空间创作的艺术；壁画只是街头艺术的一种形式，并不等同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Murus 'wall' + -alis 'pertaining to' = a picture that belongs to the wall.","cn":"murus「墙」+ -alis「属于……的」= 属于墙的画。"},{"en":"The same -al ending marks global, local and natural, all adjectives of belonging.","cn":"同一个 -al 结尾也见于表示「全球的」「本地的」「自然的」等形容词。"},{"en":"A mural is not hung on a wall; it is the wall's own skin.","cn":"壁画不是挂在墙上，而是墙自己的一层皮。"},{"en":"Museums label a large wall picture a mural rather than a canvas, because the wall is its support.","cn":"博物馆把大幅墙面画称作 mural 而非画布，因为墙才是它的载体。"},{"en":"Street murals often carry a community's signature, which is why the word travels with public art.","cn":"街头壁画常带着社区的署名，因此这个词常与公共艺术同行。"}],"abstract":[{"en":"Picture a staircase whose every riser has been painted by a different hand, so the climb reads as one long story.","cn":"想象一架楼梯，每一级竖面都由不同的人画过，整段攀登读起来像一个长故事。"},{"en":"Picture a wall that remembers the hands that painted it, layer over layer, until the plaster itself is memory.","cn":"想象一面墙记得画过它的每一双手，一层叠一层，直到灰泥本身成为记忆。"},{"en":"Picture a city speaking through its outer skin instead of through its voice.","cn":"想象一座城市不靠声音，而靠外皮说话。"}]},"examples":[{"en":"The museum commissioned a mural for the blank wall beside the main staircase.","cn":"博物馆委托艺术家在主楼梯旁的空白墙面上创作一幅壁画。"},{"en":"Years of rain had faded the outdoor mural to pale outlines.","cn":"多年雨水把户外壁画冲刷成淡淡的轮廓。"},{"en":"The new station uses a digital mural to show the river's changing level.","cn":"新车站用一幅数字壁画显示河水水位的变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「缪若」听成「描墙」——拿笔在墙上描，描满一整面，就是壁画。murus 是墙，-alis 是「属于……的」，墙所属的画自然叫 mural。","word":"mural"},"root":"拉丁 murus「墙」加形容词后缀 -alis「属于……的」构成 muralis「墙的」；英语先用其形容词义，后由「墙面绘画」这一短语缩略成名词「壁画」。murus 在拉丁语之前的来源无定论，相关印欧词根属重构形式。","sensesIntro":{"en":"Eight senses begin with the painted wall itself, then move outward to public street works, interior wall pictures, the wall-based adjective, anatomy, wall-mounted digital images, tiled screen walls and finally a field of images that surrounds the viewer.","cn":"八个义项从画在墙上的画本身出发，向外扩展到街头公共作品、室内墙面画、表示「墙的」形容词义、解剖学用法、墙面数字画面、拼接屏幕墙，最后是环绕观看者的整片图像。"},"semanticMap":{"core":{"en":"CORE IMAGE: a high wall whose whole surface has become a single picture, so the boundary of a room turns into a frame.","cn":"核心意象：一整面高墙的整个表面变成一幅画，房间的边界因此成了画框。"},"chain":["WALL SURFACE","PIGMENT ON PLASTER","PUBLIC FACE","INTERIOR SCALE","WALL-BOUND DISPLAY","SURROUNDING FIELD"],"branches":[{"senses":"01","en":"THE WALL ITSELF: the core sense is a picture that belongs to the wall rather than to a frame.","cn":"墙本身：核心义是一幅属于墙面而非属于画框的画。"},{"senses":"02 · 03","en":"INSIDE AND OUTSIDE: the same wall-sized picture serves a street audience or an interior room.","cn":"墙内与墙外：同样尺幅的墙面画，可以服务街头观众，也可以服务室内房间。"},{"senses":"04 · 05","en":"THE WALL AS QUALIFIER: the adjective sense keeps the plain meaning 'of a wall', even when medicine narrows it to an organ wall.","cn":"墙作限定语：形容词义保留「墙的」这一朴素含义，医学只是把它收窄到器官壁。"},{"senses":"06 · 07","en":"WALL-BOUND MEDIA: screens inherit the mural's fixed, wall-sized character, first as one interactive surface and then as a tiled array.","cn":"固定在墙上的媒介：屏幕继承了壁画固定、以墙为尺幅的特征，先是一整块互动面，再是拼接阵列。"},{"senses":"08","en":"A FIELD RATHER THAN AN OBJECT: the idea widens until the picture surrounds the viewer and the room itself becomes the work.","cn":"从物件到场：这一观念不断放宽，直到画面包围观看者，房间本身成为作品。"}]},"affixes":{"intro":{"en":"Mural is built from one Latin noun, one Latin suffix and a small English family, so it can be read piece by piece.","cn":"mural 由一个拉丁名词、一个拉丁后缀和一小族英语派生词构成，可以逐块读出。"},"latinIntro":{"en":"Latin murus 'wall' gives mural, muralis and the medical adjective; the suffix -alis marks belonging, and English added -ist and -ism for people and movements.","cn":"拉丁 murus「墙」衍生出 mural、muralis 及医学形容词；后缀 -alis 表示归属，英语再加表示从事者的后缀与表示做法或运动的后缀。"},"items":[{"word":"murus","structure":"murus, muri (Latin noun, second declension)","meaning":"wall, especially a house or city wall","meaningCN":"墙，尤指房屋或城墙","example":"The noun supplies the surface at the centre of the word.","exampleCN":"这个名词提供了这个词的核心表面。"},{"word":"-alis","structure":"-alis (Latin adjective suffix)","meaning":"pertaining to, belonging to","meaningCN":"属于……的；与……有关的","example":"The suffix turns a noun of place into an adjective of belonging.","exampleCN":"这个后缀把表示场所的名词变成表示归属的形容词。"},{"word":"muralis","structure":"murus + -alis (Latin adjective)","meaning":"of a wall","meaningCN":"墙的；与墙有关的","example":"Latin used the adjective for anything attached to a wall.","exampleCN":"拉丁语用这个形容词指任何附着于墙的事物。"},{"word":"mural","structure":"muralis, shortened in English","meaning":"a wall painting; of a wall","meaningCN":"壁画；墙的","example":"English kept both the noun and the adjective.","exampleCN":"英语同时保留了名词与形容词用法。"},{"word":"-ist","structure":"-ist (agent suffix, from Latin -ista)","meaning":"one who practices or follows","meaningCN":"从事者；追随者","example":"The suffix marks the person who does the work.","exampleCN":"这个后缀标记从事这项工作的人。"},{"word":"muralist","structure":"mural + -ist","meaning":"a painter of murals","meaningCN":"壁画家","example":"A muralist works on the wall itself, not on canvas.","exampleCN":"壁画家直接在墙上工作，而不是在画布上。"},{"word":"-ism","structure":"-ism (noun suffix, from Latin -ismus)","meaning":"practice, system or movement","meaningCN":"做法；体系；运动","example":"The suffix turns an activity into a movement or a style.","exampleCN":"这个后缀把一种活动变成运动或风格。"},{"word":"muralism","structure":"mural + -ism","meaning":"the practice or movement of painting murals","meaningCN":"壁画创作实践或壁画运动","example":"Muralism became a public art programme in the twentieth century.","exampleCN":"壁画主义在 20 世纪成为一项公共艺术计划。"}],"latinEntries":[{"word":"murus","structure":"murus, muri (m., second declension)","meaning":"wall","meaningCN":"墙"},{"word":"muralis","structure":"muralis, murale (adj., third declension)","meaning":"of a wall","meaningCN":"墙的；与墙有关的"}],"derivatives":[{"word":"muralist","structure":"mural + -ist (agent suffix, from Latin -ista)","meaning":"a person who paints murals","meaningCN":"绘制壁画的人"},{"word":"muralism","structure":"mural + -ism (practice or movement suffix, from Latin -ismus)","meaning":"the practice or movement of mural painting","meaningCN":"壁画创作实践或壁画运动"}]}},{"word":"fresco","ipa_uk":"/ˈfreskəʊ/","ipa_us":"/ˈfreskoʊ/","definition_zh":"湿壁画；湿壁画技法；（在湿灰泥上）作画；新鲜灰泥层","definition_en":"a painting done on fresh lime plaster, and the technique of painting that way","core_image":"画师赶在灰泥未干时落笔，颜料被墙体吸住，画面与墙一同变硬","scene":"修道院餐厅的整面高墙刚抹上新灰泥，画师趁湿落笔，颜色随墙面一起固化，The conservator explains that the fresco must be finished before the plaster dries.","sceneCN":"这里 fresco 指「在未干石灰灰泥上绘制的湿壁画」（第 1 个义项：湿壁画技法及作品）；句意为修复师说明这幅湿壁画必须在灰泥干透前完成。图中可辨识物件：新抹的灰泥墙、画师的笔与颜料碟、脚手架。","pos":[{"tag":"n.","zh":"湿壁画；湿壁画技法"},{"tag":"v.","zh":"在湿灰泥上作画"}],"collocations":[{"phrase":"in fresco","zh":"以湿壁画法"},{"phrase":"paint a fresco","zh":"绘制湿壁画"},{"phrase":"fresco cycle","zh":"湿壁画组画"},{"phrase":"fresco painter","zh":"湿壁画师"},{"phrase":"fresco secco","zh":"干壁技法"},{"phrase":"restore a fresco","zh":"修复湿壁画"}],"forms":[{"label":"复数","form":"frescos / frescoes"},{"label":"第三人称单数","form":"frescoes"},{"label":"过去式","form":"frescoed"},{"label":"过去分词","form":"frescoed"},{"label":"现在分词","form":"frescoing"}],"derivatives":[{"word":"frescoed","pos":"adj.","zh":"绘有湿壁画的；以湿壁画装饰的"},{"word":"frescoing","pos":"n.","zh":"湿壁画绘制；湿壁画装饰"}],"senses":[{"no":"01","title":"Painting on fresh lime plaster","titleCN":"在新鲜石灰灰泥上作画","definition":"the technique of applying pigment to damp lime plaster so that the colour sets into the wall","definitionCN":"把颜料涂在未干的石灰灰泥上，使颜色随灰泥固化进入墙体的技法","example":"The chapel was decorated in fresco over three summers.","exampleCN":"这座小教堂用了三个夏天以湿壁画法装饰完成。","why":"The Italian phrase in fresco means 'in fresh plaster'; the technique is named after the state of the wall at the moment of painting.","whyCN":"意大利语短语 in fresco 意为「在新鲜灰泥中」；技法是以作画那一刻墙面的状态命名的。"},{"no":"02","title":"A painting made by that technique","titleCN":"用湿壁画法完成的一幅画","definition":"a single picture executed on damp plaster","definitionCN":"在未干灰泥上完成的一幅画","example":"The fresco on the north wall shows the abbey's founding.","exampleCN":"北墙上的湿壁画描绘了修道院的创建。","why":"The product takes the name of the process, exactly as enamel names both a substance and a finished surface.","whyCN":"成品继承了工序之名，就像「珐琅」既指一种材料，也指完成后的表面。"},{"no":"03","title":"A wall painting in general","titleCN":"泛指的墙面壁画","definition":"a loose everyday use for any large painting on a wall, whether or not true fresco technique was used","definitionCN":"日常宽松用法，泛指任何大幅墙面绘画，不论是否真正使用湿壁画技法","example":"Tourists call every painted ceiling a fresco, whatever the method.","exampleCN":"游客把每一幅彩绘天顶都叫作 fresco，不管实际用了什么方法。","why":"Because true fresco is the most famous wall technique, its name spreads to the whole category, a common pattern of generic drift.","whyCN":"由于湿壁画是最著名的墙面技法，其名称扩散到整个类别，这是常见的泛化漂移。"},{"no":"04","title":"The fresh plaster ground","titleCN":"承接颜料的新鲜灰泥层","definition":"the layer of damp lime plaster prepared to receive pigment","definitionCN":"为承接颜料而备好的未干石灰灰泥层","example":"Only as much fresco is laid as the painter can finish in one day.","exampleCN":"每天只抹出画师能在一天内画完的那一小片灰泥层。","why":"In workshop speech the material and the picture share one name, so fresco can mean the prepared ground itself.","whyCN":"在工坊行话里，材料与画面共用一个名称，因此 fresco 也可指备好的底层。"},{"no":"05","title":"To paint in fresco (verb)","titleCN":"以湿壁画法作画（动词）","definition":"to paint a wall by the fresh-plaster method","definitionCN":"用新鲜灰泥法绘制墙面","example":"They frescoed the entire refectory in a single season.","exampleCN":"他们在一个季节内把整间食堂都画成了湿壁画。","why":"English freely converts the noun into a verb, so the technique becomes an action performed on a surface.","whyCN":"英语可自由地把名词转为动词，于是技法变成对某个表面执行的动作。"},{"no":"06","title":"Executed in fresco (attributive)","titleCN":"以湿壁画法完成的（定语用法）","definition":"used before a noun for works or surfaces made by the technique","definitionCN":"置于名词前，指用该技法完成的作品或表面","example":"The fresco cycle in the cloister is the abbey's greatest treasure.","exampleCN":"回廊里的湿壁画组画是修道院最珍贵的财产。","why":"The noun works attributively, as in fresco cycle or fresco painter, to mark a method rather than a single object.","whyCN":"名词可作定语，如「湿壁画组画」或「湿壁画师」，标记的是一种方法而非单件作品。"},{"no":"07","title":"A fresh, matte luminosity","titleCN":"清新而哑光的明亮感","definition":"a figurative quality of pale, dry, luminous colour associated with fresco","definitionCN":"比喻湿壁画所特有的淡雅、干爽、明亮的色彩质感","example":"The film's light has the fresco clarity of an early morning in the hills.","exampleCN":"影片的光线带着山间清晨那种湿壁画般的清透。","why":"Fresco pigment sits in the wall and reflects light softly; that visual memory supplies the figurative sense of fresh matte brightness.","whyCN":"湿壁画颜料留在墙体里，柔和地反光；这种视觉记忆提供了「清新哑光」的比喻义。"},{"no":"08","title":"Fresh, cool (bare Italian sense)","titleCN":"新鲜、清凉（意大利语本义）","definition":"the original Italian adjective meaning fresh or cool, rarely used alone in English","definitionCN":"意大利语原形容词义「新鲜、清凉」，在英语中很少单独使用","example":"In the old accounts the word appears in its bare sense of something newly made.","exampleCN":"在旧账册里，这个词以其「新做成的」本义出现。","why":"The English word kept a trace of the Italian adjective, so dictionaries still record the bare sense even though it is rare.","whyCN":"英语词保留了一点意大利语形容词的痕迹，因此词典仍收录这一本义，尽管它已罕用。"}],"etymology":{"intro":{"en":"Fresco is Italian for 'fresh', used in the painter's phrase in fresco 'in fresh plaster'. Italian fresco is generally traced to Late Latin frescus 'fresh', itself probably borrowed from a Germanic word. Dates are approximate.","cn":"fresco 是意大利语「新鲜的」，用于画师行话短语 in fresco「在新鲜灰泥中」。意大利语 fresco 一般认为源自晚期拉丁 frescus「新鲜的」，而后者很可能借自某个日耳曼词。年代均为约数。"},"items":[{"era":"GERMANIC FRISK","en":"The Germanic adjective seen in Old High German frisc meant 'fresh, lively'. Its own earlier origin is uncertain, and any deeper Indo-European form is a reconstruction.","cn":"古高地德语 frisc 中可见的日耳曼形容词意为「新鲜的、有生气的」。其更早来源不确定，任何更深的印欧语形式均属重构。"},{"era":"LATE LATIN FRESCUS","en":"Medieval Latin frescus 'fresh' is generally thought to be borrowed from that Germanic word rather than inherited from classical Latin.","cn":"中世纪拉丁 frescus「新鲜的」一般认为借自那个日耳曼词，而非从古典拉丁语继承。"},{"era":"ITALIAN FRESCO","en":"Italian fresco 'fresh, cool' developed from this form and was applied to newly laid, still damp plaster.","cn":"意大利语 fresco「新鲜的、清凉的」由此发展而来，并被用来指新抹上、仍未干的灰泥。"},{"era":"IN FRESCO","en":"Painters said they worked in fresco, 'in the fresh plaster', because pigment had to be laid while the lime was damp enough to hold it.","cn":"画师说自己在 in fresco「在新鲜灰泥中」工作，因为颜料必须在石灰仍湿、还能吸住它时涂上。"},{"era":"ENGLISH BORROWING","en":"English adopted fresco in the seventeenth century, first for the technique and soon after for the finished picture.","cn":"英语在 17 世纪借入 fresco，先指技法，很快也指完成的画。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first record and deeper origin): the exact date of the English borrowing and the pre-Germanic history of the adjective are not settled, so the proposed roots are reconstructions.","cn":"来源不确定（首见年代与更深词源）：英语借入的确切年代以及该形容词在日耳曼语之前的演变均无定论，所提词根属重构形式。"}]},"similar":{"note":{"en":"The first group holds words that look or sound like fresco but belong to other histories; the second holds real wall-painting terms that differ in method or scope.","cn":"第一组是形音相近但来历不同的词；第二组是真正的墙面绘画术语，但方法或范围有别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alfresco","ipa":"/ˌælˈfreskəʊ/","tag":"same Italian phrase, different sense","definition":"Outdoors, from Italian al fresco 'in the fresh air'; it shares the word for fresh but names open air, not painting.","definitionCN":"在户外，来自意大利语 al fresco「在新鲜空气中」；同用「新鲜」一词，但指露天，不指绘画。"},{"word":"frescos","ipa":"/ˈfreskəʊz/","tag":"same word, plural","definition":"One plural of fresco, alongside the Italian-shaped frescoes.","definitionCN":"fresco 的一种复数形式，与意大利语式的复数并存。"},{"word":"fresh","ipa":"/freʃ/","tag":"shared distant root","definition":"Newly made or cool; it descends from the same Germanic adjective that Italian borrowed, but it is not the source of the art term.","definitionCN":"新做的或清凉的；与意大利语借用的日耳曼形容词同源，但不是这个艺术术语的直接来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mural","ipa":"/ˈmjʊərəl/","tag":"surface term","definition":"Any picture on a wall, whatever the medium; fresco names a method, mural names the support.","definitionCN":"任何画在墙上的画，不限媒材；fresco 指方法，mural 指载体。"},{"word":"secco","ipa":"/ˈsekəʊ/","tag":"opposite technique","definition":"Painting on dry plaster with a binder; it is faster but far less permanent than true fresco.","definitionCN":"在干灰泥上用结合剂作画；比真正的湿壁画快，但耐久性差得多。"},{"word":"tempera","ipa":"/ˈtempərə/","tag":"different medium","definition":"Pigment mixed with an egg or gum binder, often on panel; it can resemble fresco in tone but is not absorbed by plaster.","definitionCN":"以蛋或胶为结合剂的颜料，常画在木板上；色调可能近似湿壁画，但颜料不被灰泥吸收。"},{"word":"wall painting","ipa":"/wɔːl ˈpeɪntɪŋ/","tag":"general term","definition":"A neutral cover term for pictures on walls, of which fresco is one technique.","definitionCN":"墙面绘画的中性统称，湿壁画只是其中一种技法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Italian phrase, the damp wall and the real word family.","cn":"正常联想：意大利语短语、未干的墙，以及真实的同族词。"},"normal":[{"en":"In fresco literally means 'in fresh plaster', so the picture is painted while the wall is still wet.","cn":"in fresco 字面就是「在新鲜灰泥中」，所以画是在墙还湿的时候画上去的。"},{"en":"The colour is not laid on top of the wall; it becomes part of the wall as the lime sets.","cn":"颜色不是铺在墙的表面，而是随石灰固化成为墙的一部分。"},{"en":"A day's work is called a giornata, because only as much plaster as can be finished in a day is laid.","cn":"一天的工作量有专门的意大利语说法，因为每天只抹出一天内能画完的那片灰泥。"},{"en":"Fresco secco is the dry cousin: quicker, cheaper and much more fragile.","cn":"干壁法是湿壁画的干性变体：更快、更便宜，也脆弱得多。"},{"en":"A fresco cycle is a sequence of wall panels telling one story across a room.","cn":"湿壁画组画是一组墙面画板，在一个房间里讲同一个故事。"}],"abstract":[{"en":"Picture a wall that swallows the brushstroke instead of carrying it on its skin.","cn":"想象一面墙把笔触吞进去，而不是把笔触驮在表皮上。"},{"en":"Picture a painting that cannot be moved, because moving it would mean demolishing the room.","cn":"想象一幅无法搬走的画，因为搬走它就等于拆掉这个房间。"},{"en":"Picture colour that survives by becoming stone rather than by staying paint.","cn":"想象颜色不是靠保持颜料状态，而是靠变成石头而存活。"}]},"examples":[{"en":"The fresco in the refectory survived because the plaster held the pigment for centuries.","cn":"食堂里的湿壁画得以留存，因为灰泥把颜料固定了几个世纪。"},{"en":"She studied the fresco cycle before beginning the restoration.","cn":"她在开始修复前先研究了这组湿壁画。"},{"en":"The modern lobby uses a fresco-like surface that keeps its colour matte and pale.","cn":"现代大堂采用一种类似湿壁画的表面，使颜色保持哑光而淡雅。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fresco」听成「费事壳」——在湿灰泥壳上画，颜料一干就咬进墙里，费事却牢。记住「新鲜灰泥」这一层，就能把技法和作品一起记住。","word":"fresco"},"root":"意大利语 fresco「新鲜的」来自晚期拉丁 frescus「新鲜的」，后者一般认为借自日耳曼语（参古高地德语 frisc）。画师说 in fresco「在新鲜灰泥中」，英语遂以之指湿壁画技法及作品。更早词源不确定，相关印欧形式属重构。","sensesIntro":{"en":"Eight senses move from the wet-plaster method to its product, to the loose everyday name, the prepared ground, the verb, the attributive use, a figurative matte brightness and finally the bare Italian adjective.","cn":"八个义项从湿灰泥技法出发，依次到成品、日常泛称、备好的灰泥层、动词用法、定语用法、比喻性的哑光亮度，最后回到意大利语本义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a brush moving across damp lime plaster, with the colour sinking in before the wall hardens.","cn":"核心意象：画笔扫过未干的石灰灰泥，颜色在墙面变硬之前沉进去。"},"chain":["DAMP LIME","PIGMENT ABSORBED","FINISHED PICTURE","WHOLE WALL SCHEME","FRESH MATTE LIGHT","ITALIAN ADJECTIVE"],"branches":[{"senses":"01","en":"THE METHOD: the core sense is an act of painting that must be completed while the plaster is still wet.","cn":"方法：核心义是一种必须在灰泥仍湿时完成的绘画动作。"},{"senses":"02 · 03","en":"FROM ONE PICTURE TO A CATEGORY: a single fresco becomes the everyday label for any painted wall.","cn":"从一幅画到一类画：单幅湿壁画变成任何墙面彩绘的日常标签。"},{"senses":"04 · 05","en":"MATERIAL AND ACTION: the prepared ground and the verb both keep the technique's dependence on fresh plaster.","cn":"材料与动作：备好的底层与动词用法都保留了对新鲜灰泥的依赖。"},{"senses":"06 · 07","en":"METHOD AS QUALITY: the attributive use names the technique, and its matte brightness becomes a metaphor for fresh clarity.","cn":"方法化为质感：定语用法指技法，其哑光亮度则成为清新通透的比喻。"},{"senses":"08","en":"THE ORIGINAL WORD: the Italian adjective survives as a rare reminder that fresco first meant simply fresh.","cn":"原词：意大利语形容词残留下来，罕用地提醒人们 fresco 本只表示「新鲜」。"}]},"affixes":{"intro":{"en":"Fresco has few English relatives, but its Italian and Latin pieces can still be separated and read.","cn":"fresco 的英语同族词不多，但其意大利语与拉丁语构件仍可拆开读出。"},"latinIntro":{"en":"Late Latin frescus 'fresh' stands behind Italian fresco; the plural suffix -es and the participle ending -ed are the main English additions.","cn":"晚期拉丁 frescus「新鲜的」在意大利语 fresco 之后；英语主要添加了复数词尾与分词词尾。"},"items":[{"word":"fresc-","structure":"fresc- (word base of Late Latin frescus)","meaning":"fresh, cool","meaningCN":"新鲜的；清凉的","example":"The base carries the idea of newness that the art term needs.","exampleCN":"这个词基带着艺术术语所需的「新」这一概念。"},{"word":"fresc","structure":"Old High German frisc (Germanic adjective)","meaning":"fresh, lively","meaningCN":"新鲜的；有生气的","example":"The Germanic word is the likely distant source of the Latin form.","exampleCN":"这个日耳曼词很可能是拉丁形式的远源。"},{"word":"-esco","structure":"-esco (Italian adjective ending, of Germanic origin)","meaning":"having the quality of","meaningCN":"具有……性质的","example":"The ending marks an adjective of quality in Italian.","exampleCN":"这个结尾在意大利语中标记性质形容词。"},{"word":"fresco","structure":"Italian fresco, noun and adjective","meaning":"fresh; painting on fresh plaster","meaningCN":"新鲜的；湿壁画","example":"English took the art sense before the bare adjective.","exampleCN":"英语先接受艺术义，后接受单纯形容词义。"},{"word":"in fresco","structure":"Italian prepositional phrase","meaning":"in fresh plaster","meaningCN":"在新鲜灰泥中","example":"The phrase explains why the technique dries so hard.","exampleCN":"这个短语解释了这种技法为何干得那么硬。"},{"word":"-es","structure":"-es (English plural suffix, Italian-shaped)","meaning":"more than one","meaningCN":"多于一个","example":"Frescoes keeps the Italian plural shape.","exampleCN":"复数形式保留了意大利语式的形态。"},{"word":"-ed","structure":"-ed (English past-participle suffix)","meaning":"provided with; done by the method","meaningCN":"带有……的；以该法完成的","example":"Frescoed walls are walls that have received the technique.","exampleCN":"「饰有湿壁画的墙」指已经施以此法的墙。"},{"word":"secco","structure":"Italian secco 'dry'","meaning":"dry; the dry-plaster variant","meaningCN":"干的；干灰泥变体","example":"Secco marks the contrasting dry method.","exampleCN":"「干法」标记形成对照的另一种方法。"}],"latinEntries":[{"word":"frescus","structure":"frescus, fresca, frescum (Late Latin adj.)","meaning":"fresh, cool","meaningCN":"新鲜的；清凉的"}],"derivatives":[{"word":"frescoed","structure":"fresco + -ed (past-participle adjective)","meaning":"decorated with fresco painting","meaningCN":"以湿壁画装饰的"},{"word":"frescoes","structure":"fresco + -es (plural suffix)","meaning":"more than one fresco","meaningCN":"多幅湿壁画"}]}},{"word":"watercolor","ipa_uk":"/ˈwɔːtəkʌlə(r)/","ipa_us":"/ˈwɔːtərkʌlər/","definition_zh":"水彩；水彩画；水彩颜料；水彩技法","definition_en":"a painting medium in which pigments are bound in a water-soluble gum, and a picture made with it","core_image":"清水在纸面洇开，颜料随水流动，一层淡色叠在另一层淡色上","scene":"清晨的窗边，画纸被水洇湿，颜色一层层晕开，The student mixes a pale wash of watercolor for the sky.","sceneCN":"这里 watercolor 指「以水溶性胶调和颜料的水彩媒材」（第 1 个义项：水彩颜料与媒材）；句意为学生调出一层淡薄的水彩来画天空。图中可辨识物件：窗边画纸、水盂、颜料盒与湿开的色层。","pos":[{"tag":"n.","zh":"水彩；水彩画；水彩颜料"},{"tag":"adj.","zh":"水彩的；用水彩画的"}],"collocations":[{"phrase":"watercolor painting","zh":"水彩画"},{"phrase":"watercolor paper","zh":"水彩纸"},{"phrase":"a watercolor of","zh":"一幅描绘……的水彩画"},{"phrase":"watercolor wash","zh":"水彩淡彩层"},{"phrase":"watercolor artist","zh":"水彩画家"},{"phrase":"in watercolor","zh":"用水彩"}],"forms":[{"label":"复数","form":"watercolors"},{"label":"英式拼写","form":"watercolour"}],"derivatives":[{"word":"watercolorist","pos":"n.","zh":"水彩画家"},{"word":"watercolourist","pos":"n.","zh":"水彩画家（英式拼写）"}],"senses":[{"no":"01","title":"Pigment bound in water-soluble gum","titleCN":"以水溶性胶调和的颜料","definition":"a painting medium made of pigment dispersed in a water-soluble binder such as gum arabic","definitionCN":"把颜料分散在水溶性结合剂（如阿拉伯胶）中的绘画媒材","example":"The box holds twelve pans of watercolor and a small brush.","exampleCN":"盒子里有十二块水彩颜料和一支小画笔。","why":"The compound names exactly what distinguishes the medium: colour that is carried and thinned by water.","whyCN":"这个复合词直接点出这种媒材的区别：由水来承载与稀释的颜色。"},{"no":"02","title":"A picture painted with it","titleCN":"用水彩画出的一幅画","definition":"a finished painting made with watercolor paint","definitionCN":"用水彩颜料完成的画作","example":"Her watercolor of the harbour hangs above the desk.","exampleCN":"她那幅港口水彩画挂在书桌上方。","why":"The medium and the product share one name, so the material word also names the finished object.","whyCN":"媒材与成品共用一个名称，因此材料词也指完成的作品。"},{"no":"03","title":"The art or genre of watercolor","titleCN":"水彩艺术或画种","definition":"the practice or category of painting in this medium","definitionCN":"使用这种媒材的绘画实践或画种","example":"Watercolor has been the society's main medium for a century.","exampleCN":"一个世纪以来，水彩一直是这个协会的主要画种。","why":"Once a medium has its own exhibitions and schools, its name stands for the whole artistic category.","whyCN":"当一种媒材有了自己的展览与流派，它的名称就代表整个艺术门类。"},{"no":"04","title":"Made in watercolor (attributive)","titleCN":"水彩的；用水彩画的（定语）","definition":"used before a noun for materials, works or techniques belonging to the medium","definitionCN":"置于名词前，指属于该媒材的材料、作品或技法","example":"She keeps a watercolor sketchbook in her bag.","exampleCN":"她包里总带着一本水彩速写本。","why":"The noun works as a classifier, as in watercolor paper or watercolor class, marking the medium of what follows.","whyCN":"名词可作分类定语，如「水彩纸」或「水彩课」，标记后续事物所属的媒材。"},{"no":"05","title":"A paint product sold in pans or tubes","titleCN":"成块或管装出售的水彩颜料","definition":"a commercial paint product formulated for watercolor painting","definitionCN":"为水彩绘画配制的商品颜料","example":"Student-grade watercolor costs far less than artist-grade.","exampleCN":"学生级水彩比艺术家级便宜得多。","why":"The medium becomes a commodity, so the same word names the item on a shop shelf rather than the art.","whyCN":"媒材成为商品，同一个词便指货架上的物品，而非艺术品。"},{"no":"06","title":"The transparent wash technique","titleCN":"透明淡彩的技法","definition":"the method of laying thin, transparent washes that let the paper show through","definitionCN":"薄而透明、让纸白透出的层层罩染方法","example":"The sky was built from three transparent watercolor washes.","exampleCN":"天空由三层透明水彩淡彩叠成。","why":"Watercolor's defining behaviour is transparency; the word comes to name the technique of layering thin colour.","whyCN":"水彩最典型的表现是透明；这个词因此也指层层薄涂的技法。"},{"no":"07","title":"A pale, translucent effect","titleCN":"淡雅透明的效果","definition":"a figurative look of thin, luminous colour resembling watercolor","definitionCN":"类似水彩的淡薄、透亮色彩效果","example":"The morning fog gave the streets a watercolor softness.","exampleCN":"晨雾给街道罩上一层水彩般的柔和。","why":"Because watercolor cannot hide the paper, its colours look airy; that visual memory supplies the figurative use.","whyCN":"由于水彩无法遮住纸白，颜色显得轻盈；这种视觉记忆提供了比喻用法。"},{"no":"08","title":"To paint in watercolor (verb, rare)","titleCN":"用水彩作画（罕用动词）","definition":"to paint a subject with watercolor, chiefly in older or technical writing","definitionCN":"用水彩绘制某物，主要用于较早或技术性文字","example":"The travel books were watercolored by hand before photography took over.","exampleCN":"在摄影取代之前，这些旅行书是手工上水彩的。","why":"English occasionally converts medium nouns into verbs, and this rare use treats watercolor as an action.","whyCN":"英语偶尔把媒材名词转为动词，这一罕用用法把水彩当作一种动作。"}],"etymology":{"intro":{"en":"Watercolor is an English compound of water, from Old English wæter, and color, from Latin color 'colour'. The compound itself is modern English, not a Latin word. Dates are approximate.","cn":"watercolor 是英语复合词，由表示「水」的英语本族词（源自古英语 wæter）与表示「颜色」的词（源自拉丁 color）合成。复合词本身属现代英语，并非拉丁词。年代均为约数。"},"items":[{"era":"OLD ENGLISH WÆTER","en":"Wæter is the native English word for water, inherited from the Germanic family; its further pre-Germanic history is a reconstruction.","cn":"wæter 是英语本族的水字，继承自日耳曼语族；其更早的日耳曼语之前历史属重构。"},{"era":"LATIN COLOR","en":"Latin color meant 'colour, hue, outward appearance'. Its deeper origin is uncertain, and the link sometimes suggested to a root meaning 'to cover' is a hypothesis.","cn":"拉丁 color 意为「颜色、色调、外观」。其更深来源不确定；有人把它与意为「覆盖」的词根联系起来，那只是假说。"},{"era":"ENGLISH COLOR","en":"English took color through Old French in the thirteenth century, and the spelling without u became standard in American use.","cn":"英语在 13 世纪经古法语接受 color，不带 u 的拼写在美式用法中成为标准。"},{"era":"COMPOUND WATERCOLOR","en":"The compound watercolor appears in the eighteenth century, when painters needed a short name for pigment thinned with water rather than oil.","cn":"复合词 watercolor 出现于 18 世纪，当时画师需要一个短名，来指用水而非油稀释的颜料。"},{"era":"GENRE AND PRODUCT","en":"In the nineteenth century the word also named the picture, the exhibition category and the packaged paint sold to amateurs.","cn":"到 19 世纪，这个词也指画作、展览类别，以及卖给业余者的成包颜料。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Germanic history of water and the ultimate source of Latin color are both unsettled, so any proposed Indo-European roots are reconstructions.","cn":"来源不确定（更深词源）：water 在日耳曼语之前的历史与拉丁 color 的最终来源均无定论，所提印欧词根均属重构形式。"}]},"similar":{"note":{"en":"The first group contains spellings and sound-alikes that are not the same term; the second contains media that behave differently on paper.","cn":"第一组是拼写变体与读音相近但并非同一术语的词；第二组是在纸上表现不同的媒材。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"watercolour","ipa":"/ˈwɔːtəkʌlə(r)/","tag":"British spelling","definition":"The same word in British spelling; it is not a different medium or a different meaning.","definitionCN":"同一个词的英式拼写，并非另一种媒材或另一个词义。"},{"word":"water cooler","ipa":"/ˈwɔːtə kuːlə(r)/","tag":"unrelated compound","definition":"A machine that cools drinking water; it shares two common words but belongs to offices, not art.","definitionCN":"冷却饮用水的机器；共用两个常见词，但属于办公室而非艺术。"},{"word":"watercolored","ipa":"/ˈwɔːtəkʌləd/","tag":"derived adjective","definition":"A descriptive form meaning painted or tinted with watercolor, rather than the name of the medium.","definitionCN":"描述性形式，意为用水彩画成或染成，而不是媒材名称。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gouache","ipa":"/ɡuˈɑːʃ/","tag":"opaque variant","definition":"Water-based paint made opaque with white; it shares watercolor's gum binder but hides the paper.","definitionCN":"加白而成的不透明水性颜料；与水彩共用胶质结合剂，却会遮住纸白。"},{"word":"wash","ipa":"/wɒʃ/","tag":"technique term","definition":"A thin, fluid layer of colour; it is one watercolor technique, not the medium itself.","definitionCN":"薄而流动的一层颜色；它是水彩的一种技法，而非媒材本身。"},{"word":"tempera","ipa":"/ˈtempərə/","tag":"different binder","definition":"Pigment bound with egg or gum on a panel; its colours are opaque and its surface does not rely on paper white.","definitionCN":"以蛋或胶调合、画在板上的颜料；颜色不透明，表面不依赖纸白。"},{"word":"acrylic","ipa":"/əˈkrɪlɪk/","tag":"modern medium","definition":"Pigment in a synthetic polymer emulsion; it can be thinned with water but dries into a plastic film.","definitionCN":"以合成聚合物乳液调和颜料；可用水稀释，但干后形成塑料膜。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real words in the compound, the behaviour of the medium and the phrases it keeps.","cn":"正常联想：复合词里的两个真实单词、媒材的实际表现，以及它常用的搭配。"},"normal":[{"en":"Water plus color is literally the recipe: pigment carried by water.","cn":"「水」加「颜色」就是字面配方：由水承载的颜料。"},{"en":"The paper stays visible through the paint, which is why watercolor has no true white of its own.","cn":"纸白会从颜料中透出来，所以水彩本身没有真正的白色。"},{"en":"A wash is colour diluted until it behaves like tinted water.","cn":"「淡彩」是稀释到像带色清水一样的颜料层。"},{"en":"Oil paint sits on the surface; watercolor sinks into the paper.","cn":"油画颜料停在表面，水彩则渗进纸里。"},{"en":"Travelers once carried a small watercolor box because it needed only water, not oil or solvent.","cn":"旧时旅行者带小水彩盒，只因它只需要水，不需要油或溶剂。"}],"abstract":[{"en":"Picture light passing through a stained window instead of bouncing off a wall.","cn":"想象光穿过彩色玻璃，而不是从墙面上反弹。"},{"en":"Picture a colour that gains strength each time it is allowed to dry and be layered again.","cn":"想象一种颜色，每次干透后再叠一层就更有力量。"},{"en":"Picture a painting that trusts the blank paper to do half the work.","cn":"想象一幅画放心把一半的活交给空白纸面。"}]},"examples":[{"en":"The artist loaded the brush with watercolor and let it run down the page.","cn":"画家把水彩蘸满画笔，任它顺着纸面流下。"},{"en":"Her early works are watercolors of the canals near her childhood home.","cn":"她早期作品是童年家附近运河的水彩画。"},{"en":"The instruction sheet explains how to keep watercolor from buckling the paper.","cn":"说明页讲解了如何防止水彩让纸面起皱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「watercolor」就是 water 加 color：用水带色。水一多就淡，水一少就浓，纸白透出来就是高光。记住「水带色」三个字，拼写和用法一起记住。","word":"watercolor"},"root":"watercolor 是英语复合词：前半表示「水」，源自古英语 wæter，属日耳曼语族；后半表示「颜色」，经古法语来自拉丁 color。复合词本身在 18 世纪出现，指以水调和而非以油调和的颜料。两部分的更早来源均无定论。","sensesIntro":{"en":"Eight senses begin with the medium itself, then move to the finished picture, the genre, attributive use, the packaged product, the transparent wash method, a pale figurative look and finally a rare verb.","cn":"八个义项从媒材本身开始，依次到完成的画、画种、定语用法、商品颜料、透明淡彩技法、淡雅的比喻效果，最后是罕用动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: clear water spreading through paper, carrying a little pigment and leaving the paper's white to shine through.","cn":"核心意象：清水在纸面铺开，带着少量颜料，把纸白留出来发光。"},"chain":["WATER AS VEHICLE","PIGMENT DISPERSED","TRANSPARENT LAYERS","PAPER WHITE","PORTABLE MEDIUM","PALE LUMINOSITY"],"branches":[{"senses":"01","en":"THE MEDIUM ITSELF: the core sense is pigment that water can carry and thin.","cn":"媒材本身：核心义是能被水承载与稀释的颜料。"},{"senses":"02 · 03","en":"FROM OBJECT TO GENRE: one finished sheet becomes the name of a whole painting category.","cn":"从物件到画种：一张完成的画成为整个绘画类别的名称。"},{"senses":"04 · 05","en":"CLASSIFIER AND COMMODITY: the word marks paper, classes and the pans or tubes sold in shops.","cn":"分类语与商品：这个词标记纸张、课程，以及商店出售的块装或管装颜料。"},{"senses":"06 · 07","en":"TRANSPARENCY AS METHOD AND LOOK: thin washes are both a technique and a visual softness borrowed by other media.","cn":"透明兼为方法与外观：薄层罩染既是技法，也是被其他媒介借用的柔和观感。"},{"senses":"08","en":"RARE ACTION: the medium briefly becomes a verb, as older travel plates were watercolored by hand.","cn":"罕用动作：媒材偶尔转为动词，如旧时旅行版画由人工上水彩。"}]},"affixes":{"intro":{"en":"The compound is transparent English, and its two halves plus two suffixes account for the useful family.","cn":"这个复合词是透明的英语构词，两个词根加两个后缀足以解释其常用词族。"},"latinIntro":{"en":"Latin color supplies the second half; the first half is native English, and -ist and -ed build the derived words.","cn":"拉丁 color 提供后半部分；前半部分是英语本族词，表示从事者的后缀与分词词尾构成派生词。"},"items":[{"word":"water","structure":"water (Old English wæter, Germanic noun)","meaning":"the liquid that carries and thins the pigment","meaningCN":"承载并稀释颜料的液体","example":"The first half names the vehicle of the paint.","exampleCN":"前半部分命名颜料的载体。"},{"word":"color","structure":"color, coloris (Latin noun, third declension)","meaning":"colour, hue","meaningCN":"颜色；色调","example":"The second half names what the water carries.","exampleCN":"后半部分命名水所承载的东西。"},{"word":"watercolor","structure":"water + color (English compound)","meaning":"pigment thinned with water","meaningCN":"用水稀释的颜料","example":"The compound is younger than either of its parts.","exampleCN":"这个复合词比它的任一部分都年轻。"},{"word":"-colour","structure":"-colour (British spelling of the second element)","meaning":"same meaning, different spelling convention","meaningCN":"同义，只是拼写习惯不同","example":"British usage keeps the u in the second element.","exampleCN":"英式用法在第二部分保留 u。"},{"word":"-ist","structure":"-ist (agent suffix, from Latin -ista)","meaning":"one who practices","meaningCN":"从事者","example":"The suffix marks a painter who works in the medium.","exampleCN":"这个后缀标记以此媒材作画的人。"},{"word":"watercolorist","structure":"watercolor + -ist","meaning":"a painter who works chiefly in watercolor","meaningCN":"主要画水彩的画家","example":"The society was founded by a group of watercolorists.","exampleCN":"这个协会由一群水彩画家创立。"},{"word":"-ed","structure":"-ed (past-participle adjective suffix)","meaning":"provided with; treated by","meaningCN":"带有……的；经……处理的","example":"A watercolored plate is one that has received the paint.","exampleCN":"「上过水彩的版画」指已经施以此法的版面。"},{"word":"wash","structure":"wash (English noun from the verb washan)","meaning":"a thin layer of diluted colour","meaningCN":"一层稀释的薄色","example":"The technique word sits beside the medium word.","exampleCN":"技法词与媒材词并列使用。"}],"latinEntries":[{"word":"color","structure":"color, coloris (m., third declension)","meaning":"colour, hue, outward appearance","meaningCN":"颜色；色调；外观"}],"derivatives":[{"word":"watercolorist","structure":"watercolor + -ist (agent suffix)","meaning":"a painter working in watercolor","meaningCN":"水彩画家"},{"word":"watercolored","structure":"watercolor + -ed (past-participle adjective)","meaning":"painted or tinted with watercolor","meaningCN":"用水彩画成或染色的"}]}},{"word":"palette","ipa_uk":"/ˈpælət/","ipa_us":"/ˈpælət/","definition_zh":"调色板；颜料盘；（艺术家或作品使用的）色彩范围；（可选的）手段与元素范围","definition_en":"a board on which a painter mixes colours; also the range of colours or options available","core_image":"一块椭圆形木板，拇指穿过小孔，边缘排着一圈挤好的颜料","scene":"画室桌面摆着一块椭圆形木板，边缘一圈颜料已经干结，The painter tests a new green on the palette before touching the canvas.","sceneCN":"这里 palette 指「画家用来调色的木板」（第 1 个义项：调色板）；句意为画家先在调色板上试了试新调的绿色，才去动画布。图中可辨识物件：椭圆木板、拇指孔、挤好的颜料与画笔。","pos":[{"tag":"n.","zh":"调色板；颜料盘；色彩范围"}],"collocations":[{"phrase":"artist's palette","zh":"画家调色板"},{"phrase":"color palette","zh":"色彩搭配；配色方案"},{"phrase":"palette knife","zh":"调色刀"},{"phrase":"a palette of","zh":"一组……的元素或色彩"},{"phrase":"limited palette","zh":"有限的用色范围"},{"phrase":"warm palette","zh":"暖色调"}],"forms":[{"label":"复数","form":"palettes"}],"derivatives":[{"word":"paletted","pos":"adj.","zh":"使用调色板的；（图像）索引色的"},{"word":"palette knife","pos":"n.","zh":"调色刀"}],"senses":[{"no":"01","title":"The painter's mixing board","titleCN":"画家调色的木板","definition":"a flat board, often with a thumb hole, on which an artist lays out and mixes paint","definitionCN":"画家用来摆放和调和颜料的平板，常带拇指孔","example":"He scraped the leftover paint off the palette at the end of the day.","exampleCN":"一天结束时，他把调色板上剩下的颜料刮掉。","why":"The Italian source meant a small shovel, and the flat board used to carry and mix pigment looked like one.","whyCN":"意大利语源词意为小铲子，而用来盛放和调和颜料的平板形状正像一把小铲。"},{"no":"02","title":"The colours an artist uses","titleCN":"一位画家惯用的色彩","definition":"the set of colours characteristic of a particular artist or period","definitionCN":"某位画家或某个时期特有的那组颜色","example":"Her palette is built from ochre, olive and dusty blue.","exampleCN":"她的用色由赭黄、橄榄绿和灰蓝构成。","why":"What lies on the board becomes a signature: the physical palette stands for the artist's chosen colour set.","whyCN":"板上所摆之物成了签名：实物的调色板转而代表画家选定的那组颜色。"},{"no":"03","title":"A tray or case holding paints","titleCN":"盛放颜料的托盘或盒子","definition":"a portable container that holds pans, tubes or cakes of paint","definitionCN":"盛放块状、管状或饼状颜料的便携容器","example":"The watercolor palette snaps shut and fits in a coat pocket.","exampleCN":"水彩颜料盒一扣就合上，能放进大衣口袋。","why":"As paint became portable, the board and its paints merged into one closed case, and the old name moved with it.","whyCN":"颜料变得便携后，板与颜料合并成一只闭合的盒子，旧名也随之转移。"},{"no":"04","title":"The range of available options","titleCN":"可选手段或元素的范围","definition":"the range of methods, elements or resources available to someone","definitionCN":"某人可用的方法、元素或资源范围","example":"The new funding widened the palette of treatments the clinic could offer.","exampleCN":"新的拨款拓宽了诊所可提供的治疗手段。","why":"The metaphor is direct: as a painter selects from the board, any planner selects from a set of available choices.","whyCN":"比喻很直接：画家从板上取色，任何规划者也从一组可选方案中取用。"},{"no":"05","title":"A software colour set","titleCN":"软件中的一组颜色","definition":"a stored set of colours or tools that a program offers to the user","definitionCN":"程序提供给用户的一组预设颜色或工具","example":"The editor's default palette includes eight accessible contrast pairs.","exampleCN":"编辑器的默认调色板包含八组符合无障碍对比要求的配色。","why":"Digital tools reproduce the board as a list of selectable colours, and the physical word survives the change of medium.","whyCN":"数字工具把调色板再现为可选颜色列表，实物的词在媒材更替后继续存活。"},{"no":"06","title":"The tonal range of a work","titleCN":"作品的色调或情感范围","definition":"the range of tones, moods or colours that a work or artist commands","definitionCN":"一件作品或一位艺术家所驾驭的色调、情绪或色彩范围","example":"The film moves from a warm palette in the opening to cold grey by the end.","exampleCN":"影片从开场的暖色调逐渐转向结尾的冷灰。","why":"Once palette means a chosen set of colours, it can describe the emotional temperature of a whole work.","whyCN":"一旦 palette 指一组选定的颜色，它就能描述整件作品的情绪温度。"},{"no":"07","title":"A flat blade or paddle (rare)","titleCN":"扁平铲板（罕用）","definition":"the original small shovel-like blade, now rare outside historical descriptions","definitionCN":"原指小铲状的扁平刀板，如今除历史描述外罕用","example":"The old workshop inventory lists a palette among the mixing tools.","exampleCN":"旧工坊的清单把一块铲板列在调色工具之中。","why":"The word began as a small shovel; the rare sense preserves that shape-based origin beside the art sense.","whyCN":"这个词本指小铲，罕用义保留了以形状命名的源头，与艺术义并列。"},{"no":"08","title":"A curated selection of sensations","titleCN":"精心搭配的一组感官元素","definition":"a deliberately chosen range of flavours, scents or sounds offered as a set","definitionCN":"有意挑选、成组呈现的风味、香气或声音范围","example":"The tasting menu offers a palette of smoked, sour and sweet courses.","exampleCN":"品鉴菜单提供一组烟熏、酸味与甜味的菜品。","why":"The colour-set metaphor extends to any domain where a maker chooses a limited, harmonious range of sensations.","whyCN":"「色彩组合」的比喻扩展到任何需要营造有限而和谐感官范围的领域。"}],"etymology":{"intro":{"en":"Palette comes through French palette from Italian paletta, a diminutive of pala 'shovel, blade', from Latin pala 'spade'. Dates are approximate.","cn":"palette 经法语 palette 来自意大利语 paletta，是 pala「铲、刀板」的指小形式，再上溯拉丁 pala「铲」。年代均为约数。"},"items":[{"era":"LATIN PALA","en":"Pala meant 'spade, shovel', a flat digging blade. Its deeper origin is uncertain; the link sometimes proposed to a root meaning 'to fix or drive in' is a hypothesis, not a demonstrated derivation.","cn":"pala 意为「铲、锹」，指扁平的挖土刀板。其更深来源不确定；有人把它与意为「固定、打入」的词根联系起来，那只是假说，并非已证实的派生。"},{"era":"ITALIAN PALETTA","en":"The diminutive suffix -etta made paletta, a 'little shovel', which named the flat board a painter used to hold and mix pigment.","cn":"指小后缀 -etta 构成 paletta，即「小铲」，用来命名画家盛放并调和颜料的平板。"},{"era":"FRENCH PALETTE","en":"French took the Italian word as palette and passed it into English, keeping the painter's sense.","cn":"法语把意大利词接为 palette，再传入英语，保留了画家用具的含义。"},{"era":"ARTISTIC RANGE","en":"By the nineteenth century critics spoke of an artist's palette in the abstract, meaning the colours that marked a personal style.","cn":"到 19 世纪，评论家开始抽象地说某位艺术家的 palette，指标记个人风格的那组颜色。"},{"era":"GENERAL OPTIONS","en":"In the twentieth century the word spread beyond paint to any offered range of choices, and later to software colour lists.","cn":"到 20 世纪，这个词从颜料扩展到任何可提供选择的范围，后来又指软件的颜色列表。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin history of pala is not established, so any proposed Indo-European root for it is a reconstruction.","cn":"来源不确定（更深词源）：pala 在拉丁语之前的历史并无定论，凡为其提出的印欧词根均属重构形式。"}]},"similar":{"note":{"en":"The first group holds three near-homophones with entirely different roots; the second holds terms for colour ranges that do not imply a physical board.","cn":"第一组是三个读音极近、词根完全不同的词；第二组指色彩范围，但不含实物调色板之意。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pallet","ipa":"/ˈpælət/","tag":"different root","definition":"A wooden platform for stacking and moving goods; it comes from a French word for a straw bed, not from pala.","definitionCN":"堆叠与搬运货物用的木托盘；来自法语指草铺的词，与 pala 无关。"},{"word":"palate","ipa":"/ˈpælət/","tag":"different root","definition":"The roof of the mouth, and by extension taste; it comes from Latin palatum, not from pala.","definitionCN":"口腔顶部，引申为品味；来自拉丁 palatum，与 pala 无关。"},{"word":"pallette","ipa":"/pəˈlet/","tag":"historical armor term","definition":"A small plate of armor protecting the armpit; it is a different word despite the near-identical spelling.","definitionCN":"护住腋下的小块甲片；尽管拼写几乎相同，却是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"color scheme","ipa":"/ˈkʌlə skiːm/","tag":"planning term","definition":"A planned combination of colours for a room, brand or interface; it names the plan, not the painter's board.","definitionCN":"为房间、品牌或界面规划的配色组合；指方案，不指画家用的板。"},{"word":"spectrum","ipa":"/ˈspektrəm/","tag":"continuous range","definition":"The full continuous range of colours or values; a palette is a selection from such a range.","definitionCN":"颜色或数值的完整连续范围；调色板是从中选出的一组。"},{"word":"range","ipa":"/reɪndʒ/","tag":"general term","definition":"The general extent of variation available; it is broader and carries no visual metaphor.","definitionCN":"可用变化的总体幅度；更宽泛，且不带视觉比喻。"},{"word":"swatch","ipa":"/swɒtʃ/","tag":"sample","definition":"A small sample of colour or material; it shows one choice, while a palette gathers many.","definitionCN":"颜色或材料的小样；展示单个选项，而调色板集合许多选项。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the small-shovel image, the real word family and the phrases the word keeps.","cn":"正常联想：小铲子的形象、真实的同族词，以及这个词常用的搭配。"},"normal":[{"en":"Italian paletta 'little shovel' explains both the flat board and the rare blade sense.","cn":"意大利语 paletta「小铲」同时解释了平板与罕用的刀板义。"},{"en":"The thumb hole is there so the board can be held steady while the other hand paints.","cn":"拇指孔的作用是让一只手稳住板，另一只手作画。"},{"en":"What is on the board becomes the artist's signature set of colours.","cn":"板上摆什么，就成了这位画家的标志性色组。"},{"en":"Palette knife is the tool that mixes and scrapes; the palette is what it works on.","cn":"调色刀是调和与刮抹的工具，调色板是它工作的表面。"},{"en":"A limited palette forces harmony, which is why teachers often restrict beginners to three colours.","cn":"有限的调色板会逼出和谐，所以老师常只让初学者用三种颜色。"}],"abstract":[{"en":"Picture a dinner plate on which each colour waits to be chosen.","cn":"想象一只餐盘，每种颜色都在上面等着被选中。"},{"en":"Picture a window with a few stained panes, through which a whole world must be described.","cn":"想象一扇只有几块彩色玻璃的窗，却要借它描述整个世界。"},{"en":"Picture a vocabulary of colour that is small on purpose, so that every word counts.","cn":"想象一套刻意很小的颜色词汇，好让每个词都有分量。"}]},"examples":[{"en":"The palette lay on the stool with a thumb-sized hole at one end.","cn":"调色板放在凳子上，一端有个拇指大小的孔。"},{"en":"The designer reduced the palette to four colours to keep the brand recognizable.","cn":"设计师把配色缩减到四种颜色，以保持品牌可辨识。"},{"en":"The chef's seasonal palette relies on smoke, citrus and root vegetables.","cn":"主厨的当季风味组合依靠烟熏、柑橘与根茎蔬菜。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「palette」听成「拍来特」——画家拍一拍木板，把颜色调得特别准。板上有孔可握，板边一排颜色，就是调色板。记住 pala 是小铲，形状像铲的板便得此名。","word":"palette"},"root":"拉丁 pala「铲」加意大利语指小后缀 -etta 构成 paletta「小铲」，经法语 palette 进入英语，指画家盛放、调和颜料的平板。平板形似小铲，故以铲命名。pala 在拉丁语之前的来源无定论，相关印欧词根属重构。","sensesIntro":{"en":"Eight senses begin with the physical mixing board, then the artist's colour set, the paint case, the range of options, the software colour list, the tonal range of a work, the rare blade sense and finally a curated set of sensations.","cn":"八个义项从实物调色板出发，依次到画家的色组、颜料盒、可选范围、软件颜色列表、作品的色调范围、罕用的刀板义，最后是一组精心搭配的感官元素。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flat board, shaped like a small shovel, holding a few colours that are about to be mixed into a picture.","cn":"核心意象：一块形似小铲的平板，盛着几种即将被调成画面的颜色。"},"chain":["FLAT BLADE","MIXING SURFACE","CHOSEN COLOURS","PORTABLE CASE","AVAILABLE RANGE","CURATED SENSATIONS"],"branches":[{"senses":"01","en":"THE BOARD: the core sense is the physical surface where pigment is laid out and mixed.","cn":"板本身：核心义是摆放并调和颜料的实物表面。"},{"senses":"02 · 03","en":"WHAT SITS ON IT: the colours placed there become a signature set, and the board plus paints becomes a portable case.","cn":"板上之物：摆上去的颜色成为标志性色组，板与颜料又合成便携盒子。"},{"senses":"04 · 05","en":"CHOOSING FROM A SET: physical selection turns into any available range, and then into a software list of colours.","cn":"从一组中挑选：实物的选取转为任何可选范围，再转为软件中的颜色列表。"},{"senses":"06 · 07","en":"ARTISTIC AND ORIGINAL SENSES: the tonal range extends the metaphor, while the rare blade sense keeps the shovel shape.","cn":"艺术义与原义：色调范围延伸了比喻，罕用的刀板义则保留铲形来源。"},{"senses":"08","en":"BEYOND COLOUR: the same structure serves flavours, scents and sounds when a maker chooses a small harmonious set.","cn":"超越颜色：当制作者选取一小套和谐元素时，同样的结构可用于风味、香气与声音。"}]},"affixes":{"intro":{"en":"Palette is a Latin root wrapped in two diminutive layers, one Italian and one French, with a small English family on top.","cn":"palette 是一个拉丁词根外裹两层指小形式（意大利语与法语各一层），英语再添一小族派生词。"},"latinIntro":{"en":"Latin pala supplies the shovel image; Italian -etta and French -ette shrink it, and English -ed forms a technical adjective.","cn":"拉丁 pala 提供铲子的形象；意大利语与法语的指小后缀把它缩小，英语的分词词尾构成技术形容词。"},"items":[{"word":"pala","structure":"pala, palae (Latin noun, first declension)","meaning":"spade, shovel, flat blade","meaningCN":"铲；锹；扁平刀板","example":"The root names an object by its flat shape.","exampleCN":"这个词根按扁平形状命名物件。"},{"word":"-etta","structure":"-etta (Italian diminutive suffix)","meaning":"little","meaningCN":"小的","example":"The suffix turns a shovel into a little shovel.","exampleCN":"这个后缀把铲变成小铲。"},{"word":"paletta","structure":"pala + -etta (Italian noun)","meaning":"a little shovel; a painter's board","meaningCN":"小铲；画家用的板","example":"The small blade became the painter's tool.","exampleCN":"小刀板变成了画家的工具。"},{"word":"-ette","structure":"-ette (French feminine diminutive suffix)","meaning":"little","meaningCN":"小的","example":"French reshaped the Italian ending while keeping its size.","exampleCN":"法语改写了意大利语结尾，却保留了「小」的意思。"},{"word":"palette","structure":"paletta, through French palette","meaning":"mixing board; colour range","meaningCN":"调色板；色彩范围","example":"English took both the object and its metaphorical range.","exampleCN":"英语同时接受了实物与其比喻范围。"},{"word":"-s","structure":"-s (English plural suffix)","meaning":"more than one","meaningCN":"多于一个","example":"The plural is regular and adds no new meaning.","exampleCN":"复数规则变化，不增添新义。"},{"word":"-ed","structure":"-ed (past-participle adjective suffix)","meaning":"provided with; using","meaningCN":"带有……的；使用……的","example":"A paletted image stores colours by index.","exampleCN":"「索引色图像」以索引方式存储颜色。"},{"word":"knife","structure":"knife (English noun in the compound palette knife)","meaning":"a blade used for mixing or scraping","meaningCN":"用于调和或刮抹的刀片","example":"The compound names the tool that works on the board.","exampleCN":"这个复合词命名在板上工作的工具。"}],"latinEntries":[{"word":"pala","structure":"pala, palae (f., first declension)","meaning":"spade, shovel","meaningCN":"铲；锹"}],"derivatives":[{"word":"paletted","structure":"palette + -ed (past-participle adjective)","meaning":"using an indexed colour palette","meaningCN":"使用索引调色板的"},{"word":"palettes","structure":"palette + -s (plural suffix)","meaning":"more than one palette","meaningCN":"多块调色板；多组配色"}]}},{"word":"symmetry","ipa_uk":"/ˈsɪmətri/","ipa_us":"/ˈsɪmətri/","definition_zh":"对称；对称性；匀称；数学与物理中的不变性；对应一致","definition_en":"the quality of having parts that correspond exactly on opposite sides of a line or plane, and the wider idea of balanced correspondence","core_image":"一张纸沿中线对折，两半严丝合缝地重合在一起","scene":"剪纸老师把一张纸对折，剪出的两侧完全重合，The students check the symmetry of the folded snowflake against a mirror.","sceneCN":"这里 symmetry 指「图形沿轴线两侧完全对应的性质」（第 1 个义项：镜像对称）；句意为学生把折好的雪花拿到镜子前，检查它是否对称。图中可辨识物件：对折的纸、剪刀、雪花形与镜子。","pos":[{"tag":"n.","zh":"对称；对称性；匀称；一致性"}],"collocations":[{"phrase":"perfect symmetry","zh":"完全对称"},{"phrase":"bilateral symmetry","zh":"两侧对称"},{"phrase":"line of symmetry","zh":"对称轴"},{"phrase":"break the symmetry","zh":"打破对称"},{"phrase":"symmetry between","zh":"……之间的对应一致"},{"phrase":"rotational symmetry","zh":"旋转对称"}],"forms":[{"label":"复数","form":"symmetries"}],"derivatives":[{"word":"symmetrical","pos":"adj.","zh":"对称的；匀称的"},{"word":"symmetric","pos":"adj.","zh":"对称的（技术用语）"}],"senses":[{"no":"01","title":"Mirror correspondence across an axis","titleCN":"沿轴线两侧的镜像对应","definition":"the property of a shape whose two halves match exactly when folded along a line","definitionCN":"图形沿一条线对折时两半完全重合的性质","example":"The butterfly's wings show near-perfect symmetry.","exampleCN":"蝴蝶的双翅呈现近乎完美的对称。","why":"Greek symmetria meant 'agreement in measure'; the most visible agreement is two halves matching across a line.","whyCN":"希腊语 symmetria 意为「度量上的一致」；最直观的一致，就是沿一条线的两半彼此吻合。"},{"no":"02","title":"Pleasing balance and proportion","titleCN":"悦目的匀称与比例","definition":"an arrangement whose parts are well proportioned and visually balanced","definitionCN":"各部分比例得当、视觉上均衡的布局","example":"The façade owes its calm to the symmetry of its windows.","exampleCN":"这面立面之所以显得沉静，靠的是窗户的匀称排布。","why":"Agreement in measure applies to whole compositions, not only to mirrored halves, so proportion becomes a sense of its own.","whyCN":"「度量上的一致」适用于整幅构图，而不只适用于镜像两半，比例感因此独立成义。"},{"no":"03","title":"Invariance under a transformation","titleCN":"在变换下的不变性","definition":"in mathematics, the property of an object that looks the same after a specified transformation","definitionCN":"数学中，物体经过某种指定变换后仍保持原样的性质","example":"A circle has rotational symmetry about its centre.","exampleCN":"圆相对于圆心具有旋转对称性。","why":"Mathematics generalises folding into transformation: the object is unchanged when a move is applied, which is symmetry in the precise sense.","whyCN":"数学把「对折」推广为「变换」：施以某种操作后对象不变，这就是精确意义上的对称。"},{"no":"04","title":"Ordered arrangement in a crystal","titleCN":"晶体中的有序排布","definition":"the regular repeating arrangement of atoms or faces in a crystal","definitionCN":"晶体中原子或晶面规则重复的排布","example":"The mineral's external symmetry reflects its internal lattice.","exampleCN":"这种矿物的外部对称反映了其内部晶格。","why":"Crystals repeat a unit in space, and that repetition is the three-dimensional version of a symmetric pattern.","whyCN":"晶体在空间中重复一个单元，这种重复正是对称图案的三维版本。"},{"no":"05","title":"Balanced body plan in biology","titleCN":"生物体的均衡体制","definition":"the correspondence of body parts in an organism, as bilateral or radial symmetry","definitionCN":"生物体各部位之间的对应，如两侧对称或辐射对称","example":"Radial symmetry lets a sea anemone meet the world from every side.","exampleCN":"辐射对称让海葵能从各个方向面对外界。","why":"A body plan distributes organs around an axis, so the same geometric agreement becomes a biological category.","whyCN":"体制把器官围绕一条轴分布，同样的几何一致性便成为生物分类范畴。"},{"no":"06","title":"Correspondence between two things","titleCN":"两事物之间的对应一致","definition":"a satisfying match or balance between two sets of things","definitionCN":"两组事物之间令人满意的匹配或平衡","example":"There is a neat symmetry between the two countries' histories.","exampleCN":"两国的历史之间存在一种整齐的对应。","why":"The figurative step compares two sides of any contrast, not just two halves of a shape.","whyCN":"这一步比喻把任何对照的两边相比较，而不只是图形的两半。"},{"no":"07","title":"A physical invariance and its conservation law","titleCN":"物理不变性及其守恒律","definition":"in physics, an invariance of a system that corresponds to a conserved quantity","definitionCN":"物理学中，系统的一种不变性，对应某个守恒量","example":"Time-translation symmetry underlies the conservation of energy.","exampleCN":"时间平移对称是能量守恒的基础。","why":"If a system behaves the same after a shift in time, physics shows that a quantity must stay fixed, linking symmetry to conservation.","whyCN":"若系统在时间平移后表现相同，物理学便证明某个量必须保持不变，从而把对称与守恒联系起来。"},{"no":"08","title":"Symmetry of a relation (logic)","titleCN":"关系的对称性（逻辑）","definition":"the property of a relation that holds in both directions whenever it holds in one","definitionCN":"一种关系只要单向成立、反向也必成立的性质","example":"The relation 'is a sibling of' is symmetric.","exampleCN":"「是……的兄弟姐妹」这一关系是对称的。","why":"Logic abstracts the mirror idea into a rule about ordered pairs: swapping the two items changes nothing.","whyCN":"逻辑把镜像观念抽象为关于有序对的规则：交换两项，关系不变。"}],"etymology":{"intro":{"en":"Symmetry comes from Greek symmetria 'agreement in dimensions, due proportion', built on syn- 'together' and metron 'measure', and passed into English through Latin. Dates are approximate.","cn":"symmetry 来自希腊语 symmetria「尺寸一致、比例得当」，由 syn-「共同」与 metron「度量」构成，经拉丁语进入英语。年代均为约数。"},"items":[{"era":"GREEK METRON","en":"Metron meant 'measure, rule, proportion'. It is generally connected with a root meaning 'to measure', but the exact pre-Greek form is a reconstruction.","cn":"metron 意为「度量、尺度、比例」。它一般认为与意为「测量」的词根相关，但其希腊语之前的确切形式属重构。"},{"era":"GREEK SYN-","en":"The prefix syn- meant 'together, with', and it still marks words that join two things into one arrangement.","cn":"前缀 syn- 意为「共同、一起」，至今仍标记把两件事合成一个安排的词。"},{"era":"GREEK SYMMETRIA","en":"Syn- plus metron produced symmetria, 'a measuring together', hence agreement in size and due proportion.","cn":"syn- 加 metron 构成 symmetria，即「一起度量」，引申为尺寸一致与比例得当。"},{"era":"LATIN AND ENGLISH","en":"Latin symmetria carried the word into sixteenth-century English, where it first described proportion in buildings and bodies.","cn":"拉丁 symmetria 把这个词带入 16 世纪的英语，最初描述建筑与人体中的比例。"},{"era":"MATHEMATICAL SENSE","en":"Nineteenth-century geometry and group theory gave symmetry its precise sense of invariance under a transformation.","cn":"19 世纪的几何学与群论赋予 symmetry「变换下不变」的精确含义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first record and deeper root): the date of the English borrowing is approximate, and the pre-Greek origin of metron is not established, so proposed roots are reconstructions.","cn":"来源不确定（首见年代与更深词根）：英语借入的年代只是约数，metron 在希腊语之前的来源亦无定论，所提词根属重构形式。"}]},"similar":{"note":{"en":"The first group holds forms of the same Greek word beside a look-alike from another root; the second holds ideas of balance that are not the same relation.","cn":"第一组是同根词形与一个异根形近词并列；第二组是相关的平衡概念，但并非同一种关系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symmetrical","ipa":"/sɪˈmetrɪkəl/","tag":"derived adjective","definition":"The adjective meaning having symmetry; it is the same root with an adjective ending.","definitionCN":"表示具有对称性的形容词；同根加形容词词尾。"},{"word":"symmetric","ipa":"/sɪˈmetrɪk/","tag":"variant adjective","definition":"The shorter technical adjective, common in mathematics and physics.","definitionCN":"较短的技术形容词，常用于数学与物理。"},{"word":"sympathetic","ipa":"/ˌsɪmpəˈθetɪk/","tag":"different root","definition":"Compassionate or showing agreement; it joins syn- to pathos 'feeling', not to metron 'measure'.","definitionCN":"有同情心的或表示赞同的；由 syn- 加 pathos「感受」构成，与 metron「度量」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"balance","ipa":"/ˈbæləns/","tag":"wider term","definition":"An even distribution of weight or parts; it can exist without exact mirror correspondence.","definitionCN":"重量或部分的均匀分布；不必有精确的镜像对应。"},{"word":"proportion","ipa":"/prəˈpɔːʃn/","tag":"relation of parts","definition":"The relation of parts to one another in size; symmetry is one way of achieving pleasing proportion.","definitionCN":"各部分在大小上的相互关系；对称是获得悦目比例的一种方式。"},{"word":"harmony","ipa":"/ˈhɑːməni/","tag":"aesthetic term","definition":"A pleasing combination of elements; it is broader and less geometric than symmetry.","definitionCN":"元素之间悦目的组合；比 symmetry 更宽泛，也更少几何意味。"},{"word":"asymmetry","ipa":"/eɪˈsɪmətri/","tag":"opposite","definition":"The absence of mirror correspondence, often deliberate in art and design.","definitionCN":"缺乏镜像对应，在艺术与设计中常是有意为之。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek pieces, the everyday image of folding, and the technical extensions.","cn":"正常联想：两个希腊构件、对折的日常形象，以及技术领域的延伸。"},"normal":[{"en":"Syn- 'together' plus metron 'measure' = the same measure on both sides.","cn":"syn-「共同」+ metron「度量」= 两侧度量相同。"},{"en":"Fold the paper and the two halves land on each other: that is symmetry you can feel.","cn":"把纸对折，两半彼此落在对方身上：这是能摸到的对称。"},{"en":"A circle turns and looks unchanged, which is rotational symmetry.","cn":"圆转一圈仍看不出变化，这就是旋转对称。"},{"en":"A snowflake repeats its arms around a centre, the crystal version of the same idea.","cn":"雪花六臂绕中心重复，是同一观念在晶体中的版本。"},{"en":"In physics, a symmetry that survives a shift forces some quantity to be conserved.","cn":"在物理学中，经某种平移仍保持的对称会迫使某个量守恒。"}],"abstract":[{"en":"Picture a conversation in which both speakers answer with exactly the same structure.","cn":"想象一场对话，双方用完全相同的结构回应。"},{"en":"Picture a doorway that looks the same whether you enter or leave.","cn":"想象一扇门，无论进出看起来都一样。"},{"en":"Picture a rule that treats the two sides of a relation as interchangeable.","cn":"想象一条把关系两侧视为可互换的规则。"}]},"examples":[{"en":"The architect used symmetry to make the entrance feel stable.","cn":"建筑师用对称让入口显得稳定。"},{"en":"The equation has a symmetry that predicts a conserved charge.","cn":"这个方程具有一种对称性，可预言某个守恒荷。"},{"en":"Critics noticed the symmetry between the novel's first and last chapters.","cn":"评论家注意到这部小说首章与末章之间的对应。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「symmetry」听成「四面吹里」——四面吹来的风都一个样，左右前后彼此对应，就是对称。syn 是一起，metron 是度量，两边量得一样便成对称。","word":"symmetry"},"root":"希腊语 syn-「共同」加 metron「度量」构成 symmetria「一起度量、尺寸一致、比例得当」，经拉丁 symmetria 进入英语，先指建筑与人体的比例，后由数学赋予「变换下不变」的精确义。metron 的更早来源属重构。","sensesIntro":{"en":"Eight senses start with mirror correspondence, then widen to proportion, mathematical invariance, crystals, body plans, correspondence between things, physical conservation and logical relations.","cn":"八个义项从镜像对应开始，依次扩展到比例匀称、数学不变性、晶体排布、生物体制、事物间对应、物理守恒与逻辑关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet folded along a line so that one half lands exactly on the other.","cn":"核心意象：一张纸沿一条线对折，一半恰好落在另一半上。"},"chain":["SAME MEASURE","MIRROR HALVES","VISUAL BALANCE","TRANSFORMATION","REPEATING ORDER","BALANCED CORRESPONDENCE"],"branches":[{"senses":"01","en":"THE MIRROR TEST: the core sense is exact correspondence across a line or plane.","cn":"镜像检验：核心义是沿一条线或一个面的精确对应。"},{"senses":"02 · 03","en":"MEASURE AND TRANSFORMATION: pleasing proportion and mathematical invariance both keep parts in a fixed relation.","cn":"度量与变换：悦目的比例与数学不变性都把各部分维持在固定关系中。"},{"senses":"04 · 05","en":"REPEAT IN SPACE: crystals repeat a unit in three dimensions, and organisms distribute parts around a body axis.","cn":"空间重复：晶体在三维中重复单元，生物则把各部位围绕体轴分布。"},{"senses":"06 · 07","en":"BALANCE ACROSS DOMAINS: two histories can mirror each other, and a physical shift can leave a law unchanged.","cn":"跨领域的平衡：两段历史可以互相映照，物理平移也可以让定律保持不变。"},{"senses":"08","en":"ABSTRACT RULE: logic reduces mirroring to a statement about swapping the two sides of a relation.","cn":"抽象规则：逻辑把镜像化为关于交换关系两侧的陈述。"}]},"affixes":{"intro":{"en":"Symmetry is a Greek compound with a productive English family, so its pieces and derived words can be read separately.","cn":"symmetry 是希腊语复合词，英语词族活跃，其构件与派生词可以分开读出。"},"latinIntro":{"en":"Greek syn- and metron build symmetria, which Latin borrowed unchanged in meaning; English added -ic, -ical and the negative prefix a-.","cn":"希腊 syn- 与 metron 构成 symmetria，拉丁借入时保留原义；英语再加两个形容词词尾与否定前缀 a-。"},"items":[{"word":"syn-","structure":"syn- (Greek prefix, 'together, with')","meaning":"together; jointly","meaningCN":"共同；一起","example":"The prefix joins two ideas into one arrangement.","exampleCN":"这个前缀把两个观念合成一个安排。"},{"word":"metron","structure":"metron (Greek noun, 'measure')","meaning":"measure, rule, proportion","meaningCN":"度量；尺度；比例","example":"The root supplies the measuring half of the word.","exampleCN":"这个词根提供词中「度量」那一半。"},{"word":"symmetria","structure":"syn- + metron (Greek noun)","meaning":"agreement in dimensions, due proportion","meaningCN":"尺寸一致；比例得当","example":"The Greek noun already contained both the mirror and the proportional ideas.","exampleCN":"这个希腊名词已同时含有镜像与比例两种观念。"},{"word":"-metry","structure":"-metry (suffix from Greek -metria)","meaning":"measuring, as in geometry","meaningCN":"测量，如「几何学」一词中","example":"The suffix appears in geometry and trigonometry.","exampleCN":"这个后缀见于「几何学」与「三角学」等词。"},{"word":"symmetry","structure":"symmetria, through Latin","meaning":"balanced correspondence; invariance","meaningCN":"均衡对应；不变性","example":"English widened the noun from proportion to transformation.","exampleCN":"英语把这个名词从比例扩展到变换。"},{"word":"-ic","structure":"-ic (adjective suffix, from Greek -ikos)","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The suffix gives the technical adjective symmetric.","exampleCN":"这个后缀构成技术形容词「对称的」。"},{"word":"symmetrical","structure":"symmetry + -ical (adjective suffix)","meaning":"having symmetry","meaningCN":"具有对称性的","example":"The everyday adjective is symmetrical.","exampleCN":"日常形容词是「对称的」。"},{"word":"a-","structure":"a- (Greek negative prefix, 'not')","meaning":"not, without","meaningCN":"不；无","example":"The negative prefix builds the opposite term asymmetry.","exampleCN":"这个否定前缀构成反义词「不对称」。"}],"latinEntries":[{"word":"symmetria","structure":"symmetria, symmetriae (f., first declension; from Greek)","meaning":"due proportion, symmetry","meaningCN":"比例得当；对称"}],"derivatives":[{"word":"symmetrical","structure":"symmetry + -ical (adjective suffix)","meaning":"having balanced correspondence","meaningCN":"具有均衡对应的；对称的"},{"word":"symmetric","structure":"symmetry + -ic (adjective suffix)","meaning":"invariant under a transformation","meaningCN":"在变换下不变的；对称的"}]}},{"word":"asymmetry","ipa_uk":"/eɪˈsɪmətri/","ipa_us":"/eɪˈsɪmətri/","definition_zh":"不对称；不对称性；失衡；不平等的分布","definition_en":"the absence of exact correspondence between two sides, or a deliberate imbalance between parts","core_image":"一只碗左右两侧厚薄不同，转起来明显偏向一边","scene":"陶艺工作台上，一只碗的左右两侧厚薄不同，转起来明显偏向一边，The potter deliberately preserves the asymmetry of the rim.","sceneCN":"这里 asymmetry 指「两侧缺乏镜像对应的性质」（第 1 个义项：不对称）；句意为陶艺师有意保留碗口的不对称。图中可辨识物件：拉坯工作台、偏厚的碗壁、转盘与刻刀。","pos":[{"tag":"n.","zh":"不对称；不对称性；失衡"}],"collocations":[{"phrase":"information asymmetry","zh":"信息不对称"},{"phrase":"marked asymmetry","zh":"明显的不对称"},{"phrase":"asymmetry between","zh":"……之间的不对称"},{"phrase":"facial asymmetry","zh":"面部不对称"},{"phrase":"deliberate asymmetry","zh":"刻意的不对称"},{"phrase":"power asymmetry","zh":"权力不对等"}],"forms":[{"label":"复数","form":"asymmetries"}],"derivatives":[{"word":"asymmetric","pos":"adj.","zh":"不对称的"},{"word":"asymmetrical","pos":"adj.","zh":"不对称的；不匀称的"}],"senses":[{"no":"01","title":"Absence of mirror correspondence","titleCN":"缺乏镜像对应","definition":"the state of two sides not matching when folded or compared","definitionCN":"两半在对折或比较时无法吻合的状态","example":"The asymmetry of the two wings kept the model from flying straight.","exampleCN":"两翅的不对称让模型无法直线飞行。","why":"The negative prefix a- simply denies symmetry, so the core sense is symmetry's mirror test failing.","whyCN":"否定前缀直接否定了「对称」，因此核心义就是镜像检验不成立。"},{"no":"02","title":"Deliberate imbalance in composition","titleCN":"构图中刻意安排的失衡","definition":"an intentional uneven arrangement used by artists and designers for energy or tension","definitionCN":"艺术家与设计师为制造动势或张力而故意采用的不均等布局","example":"The poster's asymmetry pulls the eye toward the lower corner.","exampleCN":"海报的不对称把视线拉向左下角。","why":"In art, breaking symmetry is a tool rather than a defect, so the word can name a chosen effect.","whyCN":"在艺术中，打破对称是工具而非缺陷，因此这个词可以指一种刻意营造的效果。"},{"no":"03","title":"Absence of invariance in mathematics","titleCN":"数学中缺乏不变性","definition":"the failure of an object or equation to remain unchanged under a given transformation","definitionCN":"对象或方程在某种变换下无法保持原样","example":"The asymmetry of the matrix means the two operations do not commute.","exampleCN":"矩阵的不对称意味着两种运算不可交换。","why":"If symmetry is invariance under transformation, asymmetry is the measurable failure of that invariance.","whyCN":"若对称是变换下的不变性，不对称就是这种不变性的可测失效。"},{"no":"04","title":"Unequal development in an organism","titleCN":"生物体两侧发育不均","definition":"a difference in size, shape or position between paired parts of a living body","definitionCN":"生物成对部位在大小、形状或位置上的差异","example":"The crab's one enlarged claw is a clear example of asymmetry.","exampleCN":"这只蟹一只钳子特别大，是不对称的明显例子。","why":"Body plans can depart from mirror balance, and biology uses the plain geometric word for that departure.","whyCN":"体制可以偏离镜像平衡，生物学便用这个朴素的几何词来指这种偏离。"},{"no":"05","title":"Information asymmetry","titleCN":"信息不对称","definition":"a situation in which one party knows more than another, affecting bargaining or fairness","definitionCN":"一方比另一方掌握更多信息、从而影响议价或公平的情形","example":"Used-car markets suffer from information asymmetry between seller and buyer.","exampleCN":"二手车市场受制于买卖双方之间的信息不对称。","why":"Economics borrows the shape metaphor: the two sides of a transaction do not see the same amount.","whyCN":"经济学借用形状比喻：交易两边看到的信息量并不相同。"},{"no":"06","title":"Matter-antimatter asymmetry","titleCN":"物质与反物质的不对称","definition":"the observed imbalance between matter and antimatter in the universe","definitionCN":"宇宙中物质与反物质之间被观测到的不平衡","example":"Physicists still explain the universe's matter asymmetry.","exampleCN":"物理学家仍在解释宇宙的物质不对称。","why":"Here asymmetry names a difference in quantity between two classes that should, by symmetry, have been equal.","whyCN":"这里的对称缺失指两类本应相等的物质在数量上出现了差异。"},{"no":"07","title":"Unequal size or shape in medicine","titleCN":"医学上的大小或形状不等","definition":"a clinical difference between paired structures, such as pupils or limbs","definitionCN":"成对结构（如瞳孔或肢体）在临床上的差异","example":"Sudden asymmetry of the pupils can signal a serious problem.","exampleCN":"瞳孔突然不对称可能提示严重问题。","why":"Medicine uses the word for any paired structures that no longer match, without judging cause.","whyCN":"医学用这个词指任何不再吻合的成对结构，并不判断成因。"},{"no":"08","title":"General irregularity or lack of harmony","titleCN":"泛指不规则或不协调","definition":"a figurative want of balance or harmony between things","definitionCN":"事物之间比喻意义上的失衡或不协调","example":"There is an asymmetry between the team's ambitions and its budget.","exampleCN":"团队的雄心与预算之间存在一种不对等。","why":"The geometric word extends to any pair whose two sides carry unequal weight.","whyCN":"这个几何词扩展到任何两边分量不相等的配对。"}],"etymology":{"intro":{"en":"Asymmetry joins Greek a- 'not' to symmetria 'agreement in measure'. The negative form asymmetria existed in Greek, and English adopted the pattern in the seventeenth century. Dates are approximate.","cn":"asymmetry 把希腊语否定前缀 a-「不」加到 symmetria「度量一致」上。希腊语已有否定形式 asymmetria，英语在 17 世纪沿用这一构词模式。年代均为约数。"},"items":[{"era":"GREEK A-","en":"The prefix a- (the alpha privative) negates the word it attaches to, as in atypical or anonymous.","cn":"前缀 a-（否定性的 alpha）否定所附之词，如 atypical 或 anonymous。"},{"era":"GREEK SYMMETRIA","en":"Symmetria meant 'agreement in dimensions, due proportion', from syn- 'together' and metron 'measure'.","cn":"symmetria 意为「尺寸一致、比例得当」，由 syn-「共同」与 metron「度量」构成。"},{"era":"GREEK ASYMMETRIA","en":"The Greeks used asymmetria for want of proportion, chiefly in describing bodies and buildings that did not balance.","cn":"希腊人用 asymmetria 指比例失调，主要用于描述不均衡的人体与建筑。"},{"era":"ENGLISH COINAGE","en":"English formed asymmetry in the seventeenth century, first in geometry and natural philosophy, then in general description.","cn":"英语在 17 世纪构成 asymmetry，先用于几何学与自然哲学，后进入一般描述。"},{"era":"MODERN FIELDS","en":"In the twentieth century economics, particle physics and medicine each gave the word a precise technical application.","cn":"到 20 世纪，经济学、粒子物理与医学各自赋予这个词精确的技术用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first record and deeper root): the earliest English citation is approximate, and the pre-Greek origin of metron remains unsettled, so proposed roots are reconstructions.","cn":"来源不确定（首见年代与更深词根）：英语最早书证只是约数，metron 在希腊语之前的来源仍无定论，所提词根属重构形式。"}]},"similar":{"note":{"en":"The first group holds forms built on the same root, plus the positive term they deny; the second holds words for imbalance that are less technical.","cn":"第一组是同根词形及其所否定的肯定词；第二组是表示失衡但技术性较弱的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"asymmetric","ipa":"/ˌeɪsɪˈmetrɪk/","tag":"derived adjective","definition":"The technical adjective meaning lacking symmetry, common in science and engineering.","definitionCN":"表示缺乏对称的技术形容词，常见于科学与工程。"},{"word":"asymmetrical","ipa":"/ˌeɪsɪˈmetrɪkəl/","tag":"derived adjective","definition":"The everyday adjective with the same meaning; the choice between the two is stylistic, not semantic.","definitionCN":"同义的日常形容词；二者之别在文体，不在词义。"},{"word":"symmetry","ipa":"/ˈsɪmətri/","tag":"positive counterpart","definition":"The positive noun that asymmetry negates; it is not a look-alike but the exact opposite.","definitionCN":"被 asymmetry 否定的肯定名词；不是形近词，而是精确的反义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imbalance","ipa":"/ɪmˈbæləns/","tag":"general term","definition":"A lack of even distribution, often of weight, power or resources; it carries no geometric image.","definitionCN":"分布不均，常指重量、权力或资源；不带几何形象。"},{"word":"disproportion","ipa":"/ˌdɪsprəˈpɔːʃn/","tag":"proportion term","definition":"A failure of parts to be rightly proportioned to one another.","definitionCN":"各部分之间未能恰当相称。"},{"word":"irregularity","ipa":"/ɪˌreɡjuˈlærəti/","tag":"pattern term","definition":"A departure from a regular pattern; it is broader and does not imply two comparable sides.","definitionCN":"对规则图案的偏离；更宽泛，且不暗示两个可比的面。"},{"word":"lopsidedness","ipa":"/ˌlɒpˈsaɪdɪdnəs/","tag":"informal","definition":"A plain everyday word for one side being heavier or larger than the other.","definitionCN":"日常口语词，指一边比另一边更重或更大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the negative prefix, the two Greek pieces and the technical uses that make the word precise.","cn":"正常联想：否定前缀、两个希腊构件，以及使词义精确的技术用法。"},"normal":[{"en":"A- 'not' plus symmetry gives the whole meaning before any example: no matching measure.","cn":"「不」这一否定前缀加「对称」，在任何例子之前就给出了全部含义：没有相同的度量。"},{"en":"Fold the paper and the halves miss each other; that miss is the asymmetry.","cn":"把纸对折，两半彼此错过；这一「错过」就是不对称。"},{"en":"Artists use asymmetry on purpose, so the word does not always mean a fault.","cn":"艺术家故意使用不对称，所以这个词并不总意味着缺陷。"},{"en":"In markets, asymmetry usually means one side knows more than the other.","cn":"在市场里，不对称通常指一方比另一方知道得更多。"},{"en":"In physics, the matter asymmetry is a surplus of matter over antimatter.","cn":"在物理学中，物质不对称指物质多于反物质。"}],"abstract":[{"en":"Picture a balance scale whose two pans were made to different sizes.","cn":"想象一架天平，两只托盘被做成不同大小。"},{"en":"Picture a conversation in which only one speaker can see the notes.","cn":"想象一场对话，只有一方能看到讲稿。"},{"en":"Picture a face that is almost familiar, with one feature slightly off.","cn":"想象一张几乎熟悉的脸，只有一个特征略有偏差。"}]},"examples":[{"en":"The design uses asymmetry to keep the eye moving across the page.","cn":"这个设计用不对称让视线不断扫过页面。"},{"en":"Regulators try to reduce information asymmetry between banks and borrowers.","cn":"监管者试图减少银行与借款人之间的信息不对称。"},{"en":"The doctor noted a slight asymmetry in the patient's gait.","cn":"医生注意到病人步态略有不对称。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「asymmetry」听成「呃，四面吹里」——四面吹来的风不一样，左右对不上，就是不对称。前面的 a 就是「不」，后面是「度量一致」，合起来就是「度量不一致」。","word":"asymmetry"},"root":"希腊语否定前缀 a-「不」加 symmetria「度量一致、比例得当」（syn-「共同」+ metron「度量」）构成否定形式 asymmetria；英语在 17 世纪沿用这一模式造出 asymmetry，先用于几何与自然哲学，后进入经济学、物理与医学。metron 的更早来源属重构。","sensesIntro":{"en":"Eight senses begin with the failure of mirror correspondence, then cover deliberate artistic imbalance, mathematical non-invariance, unequal bodies, information gaps, matter-antimatter imbalance, clinical differences and general disharmony.","cn":"八个义项从镜像对应失效开始，依次涵盖艺术中的刻意失衡、数学上的非不变性、生物发育不均、信息差、物质与反物质失衡、临床差异与泛指的不协调。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet folded along its centre, with the two halves failing to meet.","cn":"核心意象：一张纸沿中线对折，两半却对不上。"},"chain":["NO SAME MEASURE","MIRROR FAILS","CHOSEN TENSION","NON-INVARIANCE","UNEQUAL SIDES","UNEVEN WEIGHT"],"branches":[{"senses":"01","en":"THE FAILED TEST: the core sense is two sides that do not match when compared.","cn":"检验失败：核心义是比较时两侧无法吻合。"},{"senses":"02 · 03","en":"BREAKING AND FAILING: artists break balance on purpose, while mathematics measures a transformation that changes the object.","cn":"打破与失效：艺术家有意打破平衡，数学则衡量使对象改变的变换。"},{"senses":"04 · 05","en":"UNEQUAL SIDES IN LIFE: paired organs can differ, and two parties can hold unequal information.","cn":"现实中的不等两侧：成对器官可以不同，交易双方也可以掌握不等的信息。"},{"senses":"06 · 07","en":"QUANTITATIVE AND CLINICAL GAPS: matter outnumbers antimatter, and paired body structures stop matching.","cn":"数量与临床差异：物质多于反物质，成对身体结构也不再吻合。"},{"senses":"08","en":"GENERAL DISHARMONY: any pair whose two sides carry unequal weight falls under the widened word.","cn":"泛指不协调：任何两边分量不等的配对都落入这个放宽后的词义。"}]},"affixes":{"intro":{"en":"Asymmetry is symmetry with a Greek negative prefix attached, so its parts and derived words are easy to read.","cn":"「不对称」是在「对称」上附加希腊否定前缀而成，构件与派生词都容易读出。"},"latinIntro":{"en":"Greek a- and symmetria build the noun; Latin carried symmetria, and English added -ic and -ical for the adjectives.","cn":"希腊 a- 与 symmetria 构成该名词；拉丁承接 symmetria，英语再加两个形容词词尾构成形容词。"},"items":[{"word":"a-","structure":"a- (Greek negative prefix, alpha privative)","meaning":"not, without","meaningCN":"不；无","example":"The prefix reverses the meaning of the whole word.","exampleCN":"这个前缀反转整词含义。"},{"word":"syn-","structure":"syn- (Greek prefix, 'together')","meaning":"together; jointly","meaningCN":"共同；一起","example":"The prefix survives inside the positive noun.","exampleCN":"这个前缀保留在肯定名词内部。"},{"word":"metron","structure":"metron (Greek noun, 'measure')","meaning":"measure, proportion","meaningCN":"度量；比例","example":"The root supplies the measuring idea.","exampleCN":"这个词根提供「度量」观念。"},{"word":"symmetria","structure":"syn- + metron (Greek noun)","meaning":"due proportion","meaningCN":"比例得当","example":"The positive noun is the base of the negative one.","exampleCN":"肯定名词是否定名词的基础。"},{"word":"symmetry","structure":"symmetria, through Latin and English","meaning":"balanced correspondence","meaningCN":"均衡对应","example":"Removing symmetry is literally adding a negative prefix.","exampleCN":"去掉对称，字面上就是加上否定前缀。"},{"word":"asymmetry","structure":"a- + symmetry (English noun)","meaning":"absence of balanced correspondence","meaningCN":"缺乏均衡对应","example":"The word names the absence, not a new shape.","exampleCN":"这个词命名的是缺失，而非一种新形状。"},{"word":"-ic","structure":"-ic (adjective suffix, from Greek -ikos)","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The suffix forms asymmetric.","exampleCN":"这个后缀构成「不对称的」这一形容词。"},{"word":"-ical","structure":"-ical (adjective suffix, from Latin -icalis)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix forms asymmetrical.","exampleCN":"这个后缀构成「不对称的」这一形容词。"}],"latinEntries":[{"word":"symmetria","structure":"symmetria, symmetriae (f., first declension; from Greek)","meaning":"due proportion, symmetry","meaningCN":"比例得当；对称"}],"derivatives":[{"word":"asymmetric","structure":"asymmetry + -ic (adjective suffix)","meaning":"lacking symmetry; not invariant","meaningCN":"缺乏对称的；非不变的"},{"word":"asymmetrical","structure":"asymmetry + -ical (adjective suffix)","meaning":"lacking balance or even shape","meaningCN":"不匀称的；不对称的"}]}},{"word":"contrast","ipa_uk":"/ˈkɒntrɑːst/","ipa_us":"/ˈkɑːntræst/","definition_zh":"差异；对比；反差；（动词）使对照；形成对比","definition_en":"a difference that becomes visible when two things are set together; also a verb meaning to compare in order to show differences, or to differ noticeably","core_image":"两样东西各自站定、面对面，中间的空隙被光一照，落差就显了出来","scene":"展厅里两幅画并排挂着，一幅几乎全是亮色，另一幅沉在深影里，讲解员让观众先看它们之间的落差，The curator sets the two canvases side by side so that the contrast between them is impossible to miss.","sceneCN":"这里 contrast 指「两物并置时显出的明显差异」（第 2 个义项：可感知的显著反差）；句意为策展人把两幅画并排摆好，让它们之间的反差无法被忽略。图中可辨识物件：两幅并排的画、明暗色块、展墙与讲解员。","pos":[{"tag":"n.","zh":"差异；对比；反差"},{"tag":"v.","zh":"使对照；形成对比"}],"collocations":[{"phrase":"in contrast","zh":"相比之下；相反"},{"phrase":"by contrast","zh":"与之相比"},{"phrase":"contrast with","zh":"与……形成对比"},{"phrase":"stark contrast","zh":"鲜明的反差"},{"phrase":"contrast ratio","zh":"对比度；反差比"},{"phrase":"contrast agent","zh":"造影剂"}],"forms":[{"label":"复数","form":"contrasts"},{"label":"第三人称单数","form":"contrasts"},{"label":"过去式","form":"contrasted"},{"label":"现在分词","form":"contrasting"}],"derivatives":[{"word":"contrastive","pos":"adj.","zh":"对照的；对比的"},{"word":"contrastively","pos":"adv.","zh":"以对比的方式"}],"senses":[{"no":"01","title":"Difference seen when things are set together","titleCN":"并置时显现的差异","definition":"the state of being noticeably different from something else when the two are considered together","definitionCN":"两物放在一起考量时，彼此显出明显不同的状态","example":"There is a clear contrast between the two proposals.","exampleCN":"两份提案之间存在明显的差异。","why":"Latin contra 'against' plus stare 'to stand' produced contrastare, 'to stand against'; the noun keeps that picture of two things facing each other.","whyCN":"拉丁语 contra「相反」加 stare「站立」构成 contrastare「对立而站」；名词义保留了两物面对面的画面。"},{"no":"02","title":"A sharp difference of light and dark","titleCN":"明暗之间的强烈反差","definition":"the degree of difference in tone, colour or brightness that makes shapes stand out","definitionCN":"色调、色彩或明暗之间的差异程度，使形状得以凸显","example":"The photographer raised the contrast so the shadows would read as pure black.","exampleCN":"摄影师提高了对比度，让阴影呈现出纯黑。","why":"Once two tones stand against each other, the eye reads the gap itself as a quality of the image, so contrast becomes a measurable property of light.","whyCN":"当两种色调彼此对峙，眼睛就把这段落差本身读成画面的一种性质，对比度于是成为可测量的光的属性。"},{"no":"03","title":"A person or thing that differs sharply","titleCN":"形成鲜明对照的人或物","definition":"a person or thing that is strikingly different from another and therefore throws the other into relief","definitionCN":"与另一人或另一物差异极大、因而把对方衬托得更清楚的人或物","example":"Her quiet brother is a contrast to her loud, restless sister.","exampleCN":"她安静的弟弟与她喧闹好动的姐姐形成鲜明对照。","why":"The abstract gap turns into a concrete member of a pair: one term of the comparison stands for the whole relation.","whyCN":"抽象的落差转成了成对事物中的具体一方：比较中的一端代替了整段关系。"},{"no":"04","title":"A difference that distinguishes meaning","titleCN":"区分意义的对立","definition":"in linguistics, a relation between two units such that replacing one with the other changes the meaning of a word","definitionCN":"语言学中两个单位之间的关系，用其中一个替换另一个会改变词义","example":"The contrast between the two vowels keeps those words apart.","exampleCN":"两个元音之间的对立使那几个词保持区分。","why":"Linguistics borrows the general sense and makes it precise: the difference must be one that the language actually uses to separate meanings.","whyCN":"语言学借来一般义并使之精确：这种差异必须是语言实际用来区分意义的那一种。"},{"no":"05","title":"To set things side by side for comparison","titleCN":"并置比较以显出差异","definition":"to compare two things in order to show how they differ","definitionCN":"把两物放在一起比较，以显出它们的差别","example":"The essay contrasts rural life with the pace of the city.","exampleCN":"这篇文章把乡村生活与城市的节奏作对照。","why":"The verb keeps the original physical picture: two things are made to stand opposite each other so the gap becomes visible.","whyCN":"动词保留了最初的身体画面：两物被摆成面对面，落差便可见。"},{"no":"06","title":"To differ noticeably from something","titleCN":"与……明显不同","definition":"to be noticeably different from something else, especially in a way that stands out","definitionCN":"与别的事物明显不同，尤指突出到引人注意","example":"His calm voice contrasts with the noise of the street.","exampleCN":"他平静的声音与街上的喧闹形成对比。","why":"The same verb loses its object and becomes intransitive: the two things simply stand apart, and the observer notices.","whyCN":"同一个动词失去宾语而变为不及物：两物只是各自站开，由观察者注意到差别。"},{"no":"07","title":"The difference produced by a contrast medium","titleCN":"造影剂造成的影像差异","definition":"in medical imaging, the artificial difference in density produced by a contrast medium, or the medium itself","definitionCN":"医学影像中由造影剂造成的人工密度差异，或指造影剂本身","example":"The scan uses a contrast dye to make the blood vessels stand out.","exampleCN":"这次扫描用造影剂让血管凸显出来。","why":"Medicine makes the visible gap deliberate: a substance is introduced so that one part of the body will stand against another.","whyCN":"医学把可见的落差变成刻意安排：引入一种物质，使身体的某一部分与另一部分形成对峙。"},{"no":"08","title":"A device that sharpens meaning by opposition","titleCN":"以对立强化意义的修辞手法","definition":"the rhetorical placing of opposites close together so that each gains force from the other","definitionCN":"把对立面紧挨着放置，使双方各自从对方获得力量的修辞安排","example":"In contrast, the final line turns the whole poem quiet.","exampleCN":"与之相对，最后一行让整首诗安静下来。","why":"The physical stance becomes a mental one: ideas are set opposite each other, and meaning grows out of the gap between them.","whyCN":"身体的姿态转为心智的姿态：观念被摆在对立面，意义从它们之间的空隙中生长出来。"}],"etymology":{"intro":{"en":"Contrast comes from Latin contra 'against' and stare 'to stand', joined in the verb contrastare 'to oppose, to set against'. Dates are approximate.","cn":"contrast 来自拉丁语 contra「相反、对立」与 stare「站立」，在动词 contrastare「对抗、对照」中合成。年代均为约数。"},"items":[{"era":"LATIN CONTRA","en":"Contra was a preposition and prefix meaning 'against, opposite, facing'. Its own earlier origin is generally treated as a reconstruction, so no single ancestor form should be taken as proven.","cn":"contra 是表示「相反、对立、面对」的介词和前缀。它更早的来源一般被当作重构形式处理，因此不应把任何单一祖形视为已证。"},{"era":"LATIN STARE","en":"Stare meant 'to stand, to stand still', and it also lies behind several English words about standing and position.","cn":"stare 意为「站立、立住」，英语中若干表示站立与位置的词也出自它。"},{"era":"LATIN CONTRASTARE","en":"The compound contrastare meant 'to stand against, to oppose', literally of two sides holding their ground face to face.","cn":"复合词 contrastare 意为「对立而站、对抗」，字面上指双方各自站定、面对面。"},{"era":"FRENCH AND ENGLISH","en":"The verb reached English in the sixteenth century, generally by way of French; the noun followed and took over the abstract sense.","cn":"这个动词在 16 世纪进入英语，一般认为经由法语传入；名词随后出现，并承接了抽象含义。"},{"era":"STRESS SPLIT","en":"English later separated the noun and the verb by stress, with the first syllable for the noun and the second for the verb.","cn":"英语后来用重音区分名词与动词：名词重音落在第一音节，动词落在第二音节。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: whether English took the verb directly from Latin or through French is not settled; the French route is generally assumed.","cn":"来源不确定：英语是直接从拉丁语借入动词，还是经由法语传入，尚无定论；一般认为走的是法语路径。"}]},"similar":{"note":{"en":"The first group holds words that look and sound like contrast but come from other Latin material; the second holds words about difference and comparison that differ in scope, strength or grammar.","cn":"第一组是外形与读音接近、但拉丁语来源不同的词；第二组指差异与比较，在范围、强度或语法用法上有别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"contest","ipa":"/ˈkɒntest/","tag":"different root","definition":"A competition or a challenge; it comes from Latin contestari 'to call to witness', not from stare.","definitionCN":"竞赛或挑战；来自拉丁语 contestari「传唤作证」，并非出自 stare。"},{"word":"context","ipa":"/ˈkɒntekst/","tag":"different root","definition":"The circumstances around something; it comes from Latin contexere 'to weave together' and belongs to the weaving family rather than the standing family.","definitionCN":"某事物周围的背景情况；来自拉丁语 contexere「编织在一起」，属编织词族而非站立词族。"},{"word":"contract","ipa":"/ˈkɒntrækt/","tag":"different root","definition":"A binding agreement; from Latin contrahere 'to draw together'. It shares contra but not stare.","definitionCN":"有约束力的协议；来自拉丁语 contrahere「拉到一起」。它与 contra 同源，但与 stare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"difference","ipa":"/ˈdɪfrəns/","tag":"general term","definition":"The neutral word for any way in which things are unlike; contrast adds the idea of the two being set together and standing out.","definitionCN":"任何不同之处的中性说法；contrast 另含两物被并置并凸显出来的意思。"},{"word":"disparity","ipa":"/dɪˈspærəti/","tag":"unequal gap","definition":"A difference, usually an unfair or unequal one, especially in amounts or conditions.","definitionCN":"差异，通常指不公平或不均等的差距，尤用于数量或状况。"},{"word":"opposition","ipa":"/ˌɒpəˈzɪʃn/","tag":"stance","definition":"The state of being against something or of facing it; it stresses conflict rather than visible difference.","definitionCN":"反对某物或与之相对的状态；强调冲突，而非可见的差异。"},{"word":"comparison","ipa":"/kəmˈpærɪsn/","tag":"act","definition":"The act of examining two things together; comparison is the procedure, contrast is the difference that the procedure reveals.","definitionCN":"把两物放在一起考察的行为；comparison 是过程，contrast 是这个过程揭示出来的差异。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real stress pattern and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的重音规律，以及这个词实际常用的搭配。"},"normal":[{"en":"Contra 'against' + stare 'to stand' = to stand facing something.","cn":"contra「相反」+ stare「站立」= 站到对立面去。"},{"en":"The noun carries the stress on the first syllable, the verb on the second.","cn":"名词重音在前，动词重音在后。"},{"en":"A contrast is not merely a difference; it is a difference made visible by putting two things together.","cn":"contrast 不只是差异，而是把两物并置后才显出的差异。"},{"en":"In contrast and by contrast are fixed phrases that mark a turn in the argument.","cn":"「与……相比」这类固定短语标记论述的转折。"},{"en":"A contrast medium is literally a substance that makes one part stand out against another.","cn":"造影剂字面上就是一种让某一部分与另一部分形成对照的物质。"}],"abstract":[{"en":"Picture two people standing back to back, each lit from the other's side.","cn":"想象两个人背对背站着，各自被对方那一侧的光照亮。"},{"en":"Picture a single line where one half is pressed hard and the other barely touched.","cn":"想象一条线，一半用力压下去，另一半只是轻轻掠过。"},{"en":"Picture a room where the lamp is moved one step and every shadow changes.","cn":"想象房间里灯只挪了一步，所有影子都变了。"}]},"examples":[{"en":"The report draws a sharp contrast between the two years.","cn":"报告把这两年之间的反差勾勒得很鲜明。"},{"en":"Blue walls contrast pleasantly with the warm wooden floor.","cn":"蓝色墙面与温暖的木地板形成悦目的对比。"},{"en":"In contrast to her earlier work, the new series uses almost no colour.","cn":"与她早前的作品相比，新系列几乎不用色彩。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「看戳」听成「看穿」——把两张画摆在一起，一眼看穿的地方就是反差。contra 是「相反」，stare 是「站」，两样东西各站一边，反差自然显出来。","word":"contrast"},"root":"拉丁语 contra「相反、对立」+ stare「站立」构成 contrastare「对抗、对照」；英语先借入动词，再由动词派生出名词，并形成名词重音在前、动词重音在后的读法。更早的来源细节多属重构形式或假说。","sensesIntro":{"en":"Eight senses move from the bare state of difference, through visible and linguistic differences and the two verb uses, to the deliberate difference of medical imaging and finally to opposition used as a rhetorical device.","cn":"八个义项从单纯的差异状态出发，经过可见差异、语言中的对立与两种动词用法，到医学影像里刻意制造的差异，最后是以对立强化意义的修辞用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: two things stand face to face, and the gap between them becomes the thing we notice.","cn":"核心意象：两样东西面对面站定，它们之间的空隙成了我们注意到的东西。"},"chain":["STANDING OPPOSITE","STRIKING DIFFERENCE","LIGHT AGAINST SHADOW","SIDE BY SIDE","MARKED BY DYE","SHARPENED MEANING"],"branches":[{"senses":"01","en":"THE CORE STANCE: difference exists because two things are made to stand opposite each other, which is the literal picture of the Latin verb.","cn":"核心姿态：差异之所以存在，是因为两物被立在对立面，这正是拉丁动词的字面画面。"},{"senses":"02 · 03","en":"A DIFFERENCE YOU CAN SEE: the gap between tones, or between one person and another, becomes a quality in its own right.","cn":"看得见的差异：色调之间的落差，或一人与另一人之间的落差，本身成了一种性质。"},{"senses":"04 · 05","en":"A DIFFERENCE THAT DOES WORK: language uses oppositions to separate meanings, and the transitive verb deliberately sets two things side by side.","cn":"起作用的差异：语言用对立区分意义，及物动词则有意把两物并置。"},{"senses":"06 · 07","en":"A DIFFERENCE MADE VISIBLE: the intransitive verb simply records a gap, while medical imaging injects a medium to create one on purpose.","cn":"被显出的差异：不及物动词只记录落差，医学影像则注入造影剂，刻意制造落差。"},{"senses":"08","en":"A DIFFERENCE TURNED INTO MEANING: opposites are placed close together so that each idea gains force from the other.","cn":"差异转为意义：把对立面放在一起，让每个观念从对方那里获得力量。"}]},"affixes":{"intro":{"en":"Contrast can be read as two Latin pieces joined by a Latin verb ending, plus a small English adjective family.","cn":"contrast 可以读作两个拉丁构件加一个拉丁动词词尾，再加一小族英语形容词派生词。"},"latinIntro":{"en":"Latin contra 'against' and stare 'to stand' combine in contrastare; English then added -ive and -ly to build the adjective and the adverb.","cn":"拉丁语 contra「相反」与 stare「站立」在 contrastare 中结合；英语随后加两个词尾构成形容词和副词。"},"items":[{"word":"contra","structure":"contra (Latin preposition and prefix)","meaning":"against, opposite, facing","meaningCN":"相反；对立；面对","example":"The prefix sets one thing face to face with another.","exampleCN":"这个前缀让一物与另一物面对面。"},{"word":"stare","structure":"stare, steti, statum (Latin verb, first conjugation)","meaning":"to stand, to stand still","meaningCN":"站立；立住不动","example":"The verb supplies the image of two sides holding their ground.","exampleCN":"这个动词提供双方各自站定的意象。"},{"word":"-are","structure":"-are (Latin first-conjugation infinitive ending)","meaning":"marks a verb of the first conjugation","meaningCN":"标记第一变位法的动词不定式","example":"The ending makes the compound a verb of action.","exampleCN":"这个结尾使复合词成为表示动作的动词。"},{"word":"contrastare","structure":"contra + stare + -are (Latin verb)","meaning":"to stand against, to oppose","meaningCN":"对立而站；对抗","example":"The Latin verb already carries the idea of two things facing off.","exampleCN":"这个拉丁动词已含有两物对峙的意思。"},{"word":"contrast","structure":"contrast (English noun and verb)","meaning":"a difference; to set against","meaningCN":"差异；对照","example":"English keeps both the noun and the verb, separating them by stress.","exampleCN":"英语同时保留名词与动词，并用重音加以区分。"},{"word":"-ive","structure":"-ive (English adjective suffix, from Latin -ivus)","meaning":"tending to, having the nature of","meaningCN":"有……倾向的；具……性质的","example":"The suffix turns the noun of difference into an adjective.","exampleCN":"这个后缀把表示差异的名词变成形容词。"},{"word":"contrastive","structure":"contrast + -ive","meaning":"serving to contrast or distinguish","meaningCN":"用于对比或区分的","example":"Linguists speak of contrastive pairs of sounds.","exampleCN":"语言学家谈语音的对立组。"},{"word":"-ly","structure":"-ly (English adverb suffix, from Old English -lice)","meaning":"in the manner of","meaningCN":"以……方式","example":"The suffix turns the adjective into an adverb of manner.","exampleCN":"这个后缀把形容词变成方式副词。"}],"latinEntries":[{"word":"contra","structure":"contra (preposition and prefix)","meaning":"against, opposite","meaningCN":"相反；对立"},{"word":"stare","structure":"stare, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"},{"word":"contrastare","structure":"contrastare (verb, first conjugation)","meaning":"to stand against, to oppose","meaningCN":"对立而站；对抗"}],"derivatives":[{"word":"contrastive","structure":"contrast + -ive (adjective suffix, from Latin -ivus 'tending to')","meaning":"serving to distinguish; the noun of difference shifts to an adjective naming what sets things apart","meaningCN":"用于区分的；由表示差异的名词转为指明「何物使事物分开」的形容词"},{"word":"contrastively","structure":"contrastive + -ly (adverb suffix, from Old English -lice 'in the manner of')","meaning":"in a contrasting manner; the adjective shifts to an adverb describing how a distinction is drawn","meaningCN":"以对比的方式；由形容词转为描述「区分如何被画出」的副词"}]}},{"word":"texture","ipa_uk":"/ˈtekstʃə(r)/","ipa_us":"/ˈtekstʃə(r)/","definition_zh":"质地；纹理；口感；（音乐、文字的）肌理；织物结构","definition_en":"the feel or visible grain of a surface; the way a material or a piece of music or writing is woven together","core_image":"一块布被手指反复摩过，经纬线一高一低，光斜着照过来，表面因此有了起伏","scene":"陶艺工作台上摆着一只刚出窑的粗陶碗，指尖抚过釉面上一圈圈细密的起伏，She runs her thumb along the rim to feel the texture of the glaze.","sceneCN":"这里 texture 指「手触摸到的表面质地」（第 1 个义项：触摸所感的表面质感）；句意为她让拇指沿碗口滑过，去感受釉面的质地。图中可辨识物件：粗陶碗、带细密起伏的釉面、工作台与握着碗的手指。","pos":[{"tag":"n.","zh":"质地；纹理；口感；肌理"},{"tag":"v.","zh":"使具有某种质感；给……加纹理"}],"collocations":[{"phrase":"surface texture","zh":"表面质感"},{"phrase":"smooth texture","zh":"光滑的质地"},{"phrase":"the texture of","zh":"……的质地"},{"phrase":"add texture to","zh":"为……增添层次感"},{"phrase":"soil texture","zh":"土壤质地"},{"phrase":"texture mapping","zh":"纹理贴图"}],"forms":[{"label":"复数","form":"textures"},{"label":"第三人称单数","form":"textures"},{"label":"过去式","form":"textured"},{"label":"现在分词","form":"texturing"}],"derivatives":[{"word":"textural","pos":"adj.","zh":"质地上的；纹理的"},{"word":"textured","pos":"adj.","zh":"有纹理的；具质感的"}],"senses":[{"no":"01","title":"The feel of a surface under the hand","titleCN":"手触摸到的表面质地","definition":"the way a surface feels when touched, especially its roughness, smoothness or grain","definitionCN":"表面被触摸时的感觉，尤指其粗糙、光滑或颗粒感","example":"The texture of the stone wall is rough under her palm.","exampleCN":"石墙的质地在她掌心下显得粗糙。","why":"Latin textura meant 'weaving' and 'fabric'; the hand reading a surface repeats the action of fingers reading cloth.","whyCN":"拉丁语 textura 意为「编织、织物」；手去读一块表面，重复的正是手指读布的动作。"},{"no":"02","title":"The visible grain of a surface","titleCN":"肉眼可见的表面纹理","definition":"the visual quality of a surface as shown by small variations of light, colour or relief","definitionCN":"表面因光线、色彩或凹凸的细微变化而呈现的视觉性质","example":"The painter builds texture with short, thick strokes of paint.","exampleCN":"画家用短而厚的笔触堆出纹理。","why":"The sense moves from touch to sight: the eye learns to read the same small variations that the fingers feel.","whyCN":"词义从触觉转向视觉：眼睛学会读取手指所感到的同一批细微变化。"},{"no":"03","title":"The woven structure of cloth","titleCN":"织物由纱线交织而成的结构","definition":"the way threads are woven together in a fabric, producing its weight and drape","definitionCN":"织物中纱线交织的方式，决定其重量与垂感","example":"The coat's heavy texture comes from tightly woven wool.","exampleCN":"这件大衣厚重的质地来自织得紧密的羊毛。","why":"This is the oldest sense: textura named the act and result of weaving before it named the feel of anything else.","whyCN":"这是最古老的一层：textura 先指编织的动作与结果，后来才指其他事物的手感。"},{"no":"04","title":"The feel of food in the mouth","titleCN":"食物入口后的口感","definition":"the physical quality of food as felt in the mouth, such as creaminess, crunch or grain","definitionCN":"食物在口中被感受到的物理性质，如细腻、酥脆或颗粒感","example":"The soup has a silky texture that comes from slow cooking.","exampleCN":"这汤有丝滑的口感，来自长时间的慢煮。","why":"The mouth takes over from the hand: chewing and pressing give the same report about grain and resistance.","whyCN":"口取代了手：咀嚼与挤压给出的，是关于颗粒与阻力的同一份报告。"},{"no":"05","title":"The characteristic quality of a sound or a piece of writing","titleCN":"声音或文字特有的质感","definition":"the overall character of a sound, a voice or a piece of writing, considered as a fabric of detail","definitionCN":"声音、嗓音或文字整体的特质，被视为由细节织成的织物","example":"The cello's low notes give the passage a dark texture.","exampleCN":"大提琴的低音给这段音乐一种暗沉的质感。","why":"A voice or a page also has grain: details are woven together, and the ear or reader judges the weave rather than any single thread.","whyCN":"嗓音或书页也有颗粒：细节被织在一起，耳朵或读者评判的是织法，而非某一根线。"},{"no":"06","title":"The interweaving of parts in music","titleCN":"音乐中各声部的交织","definition":"in music, the way voices or instrumental parts are combined and layered across a piece","definitionCN":"音乐中各个嗓音或器乐声部在一首作品里结合与分层的方式","example":"The composer thins the texture in the second movement.","exampleCN":"作曲家在第二乐章把织体减薄。","why":"Music theory borrows the weaving image literally: separate lines cross and support each other like warp and weft.","whyCN":"音乐理论直接借用了编织的意象：各条线像经线与纬线那样交错、彼此支撑。"},{"no":"07","title":"The grain and structure of a material","titleCN":"材料的颗粒与内部结构","definition":"in geology and materials, the size, shape and arrangement of grains that make up a rock, soil or solid","definitionCN":"地质学与材料学中构成岩石、土壤或固体的颗粒大小、形状与排列方式","example":"The soil's sandy texture lets water drain quickly.","exampleCN":"这土壤的砂质结构让水很快排走。","why":"Science narrows the word to what can be measured: the grains and their arrangement replace the subjective feel.","whyCN":"科学把词义收窄到可测量的部分：颗粒及其排列取代了主观手感。"},{"no":"08","title":"A mapped surface image in computer graphics","titleCN":"计算机图形中贴到表面的图像","definition":"in computer graphics, an image wrapped over a three-dimensional surface to give it detail","definitionCN":"计算机图形学中包覆在三维表面上、为其增加细节的图像","example":"The game renders a wood texture on every table in the room.","exampleCN":"游戏给房间里的每张桌子渲染了木纹贴图。","why":"A digital surface needs the same information the hand once supplied, so an image is stretched over the model and called a texture.","whyCN":"数字表面需要的信息与手曾经提供的一样，于是把一张图铺展到模型上，并称之为纹理。"}],"etymology":{"intro":{"en":"Texture comes from Latin textura 'weaving, fabric', a noun built on texere 'to weave'. Dates are approximate.","cn":"texture 来自拉丁语 textura「编织、织物」，由动词 texere「编织」构成的名词。年代均为约数。"},"items":[{"era":"LATIN TEXERE","en":"Texere meant 'to weave, to plait, to construct'. Its deeper root is generally reconstructed as *teks- 'to weave, to make', which is a reconstruction rather than a recorded form.","cn":"texere 意为「编织、编结、构造」。其更深的词根一般认为可重构为 *teks-「编织、制作」，这属于重构形式，而非实际书证。"},{"era":"LATIN TEXTURA","en":"The suffix -ura named the result of an action, so textura was 'a weaving, a fabric, a woven thing'.","cn":"后缀 -ura 表示动作的结果，因此 textura 指「编织、织物、织成之物」。"},{"era":"LATIN TEXTUS","en":"The same verb produced textus, 'something woven', which later gave English text; cloth and text share one image.","cn":"同一个动词还产生 textus「织成之物」，后来进入英语成为「文本」；布与文本共享同一个意象。"},{"era":"OLD FRENCH AND ENGLISH","en":"English took texture in the fifteenth century, generally through Old French, where it still named woven cloth.","cn":"英语在 15 世纪接受 texture，一般认为经由古法语传入，当时仍指织成的布。"},{"era":"SENSE WIDENING","en":"By the seventeenth century the word had moved from cloth to any surface, and touch rather than the loom became the point of reference.","cn":"到 17 世纪，这个词已从布匹扩展到任何表面，参照点也从织机变成了触摸。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: whether the first English uses came straight from Latin or through French is not fully established; the French route is generally assumed.","cn":"来源不确定：英语最早的用法是直接取自拉丁语，还是经由法语，尚无定论；一般认为走的是法语路径。"}]},"similar":{"note":{"en":"The first group holds words that look close to texture and come from the same weaving verb but name different things; the second holds words about surface and material quality that differ in focus.","cn":"第一组是外形接近、同出编织动词但所指不同的词；第二组指表面与材料性质，在关注点上有别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"text","ipa":"/tekst/","tag":"same family","definition":"Written material; it comes from the same Latin verb texere 'to weave', since a text is a woven thing, but it names words rather than a surface.","definitionCN":"文字材料；出自同一拉丁动词 texere「编织」，因为文本本是被织成之物，但它指文字而非表面。"},{"word":"textile","ipa":"/ˈtekstaɪl/","tag":"same family","definition":"Cloth or fabric, the original product that textura named; it stays with woven material and does not extend to feel in general.","definitionCN":"布料或织物，正是 textura 最初所指的产物；它停留在编织材料，不扩展到一般手感。"},{"word":"textual","ipa":"/ˈtekstʃuəl/","tag":"different formation","definition":"Relating to written text; it belongs to text, not to the feel or grain of a surface.","definitionCN":"与书面文本有关的；它属于 text，而不属于表面的手感或纹理。"}]},{"heading":"NEAR MEANING","entries":[{"word":"grain","ipa":"/ɡreɪn/","tag":"material structure","definition":"The direction and size of fibres or particles in wood, stone or cloth; grain is one cause of texture, not the whole impression.","definitionCN":"木材、石料或布中纤维与颗粒的方向和大小；颗粒只是质地的成因之一，并不等于整体印象。"},{"word":"finish","ipa":"/ˈfɪnɪʃ/","tag":"surface treatment","definition":"The final treatment given to a surface, such as matte or gloss; finish names the treatment, texture names the result as felt.","definitionCN":"表面最后的处理方式，如哑光或高光；finish 指处理，texture 指被感受到的结果。"},{"word":"feel","ipa":"/fiːl/","tag":"informal","definition":"The general impression a surface gives to the hand; a plainer word than texture and often used in speech.","definitionCN":"表面对手给出的总体印象；比 texture 更朴素，多用于口语。"},{"word":"consistency","ipa":"/kənˈsɪstənsi/","tag":"substance","definition":"The firmness or thickness of a substance, especially food or paint; it describes body rather than surface detail.","definitionCN":"物质的浓稠或坚实程度，尤用于食物或颜料；它描述的是稠度而非表面细节。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Texere 'to weave' + -ura 'result' = the result of weaving, a fabric.","cn":"texere「编织」+ -ura「结果」= 编织的产物，也就是织物。"},{"en":"Texture and textile are close relatives, both coming from the loom.","cn":"「织体」与「纺织品」是近亲，都来自织机。"},{"en":"The hand reads texture; the eye reads the same small pattern.","cn":"手读质地，眼读的其实是同一小片纹样。"},{"en":"A coarse cloth shows its texture as roughness, a fine one as even grain.","cn":"粗布以粗糙显出其质地，细布则以匀净的颗粒显出质地。"},{"en":"In graphics a texture is an image laid over a surface, like cloth over a table.","cn":"在图形学里，纹理是铺在表面上的一张图，像把布盖在桌上。"}],"abstract":[{"en":"Picture a single thread pulled out of a weave and laid across the page.","cn":"想象从织物里抽出一根线，横放在纸页上。"},{"en":"Picture fingertips as small readers that report the height of every bump.","cn":"想象指尖是小小的读者，逐一报告每个凸起的高度。"},{"en":"Picture a voice with grain, like cloth that is not flat.","cn":"想象一副带有颗粒的声音，像一块并不平顺的布。"}]},"examples":[{"en":"The old wooden table has a warm texture worn smooth by years of use.","cn":"那张旧木桌有温润的质地，被多年使用磨得光滑。"},{"en":"Add crushed nuts to the dessert for extra texture.","cn":"在甜点里加入碎坚果，增添额外的口感。"},{"en":"The novel's texture comes from many short scenes woven together.","cn":"这部小说的肌理来自许多短场景交织在一起。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「贴死扯」——手指贴上去，用力扯一扯布面，粗糙还是顺滑立刻知道，这就是质地。texere 是「编织」，织出来的东西表面自有纹路。","word":"texture"},"root":"拉丁语 textura「编织、织物」来自动词 texere「编织」；textura 由 texere 加表示动作结果的后缀 -ura 构成。英语经古法语借入，词义由织物结构扩展到任何表面的手感与可见纹理，并进一步用于音乐织体、材料颗粒与数字贴图。texere 更早的词根属重构形式。","sensesIntro":{"en":"Eight senses start with the feel of a surface under the hand, then move to visible grain and the woven cloth that gave the word its name, to food and sound, to music and the grain of materials, and finally to the image mapped onto a digital surface.","cn":"八个义项从手触摸表面的感觉出发，转到可见纹理与给这个词命名的织物结构，再到食物与声音，再到音乐织体与材料颗粒，最后是贴到数字表面的图像。"},"semanticMap":{"core":{"en":"CORE IMAGE: threads cross and rise, so a surface carries a small repeated relief that the hand and the eye can both read.","cn":"核心意象：线交叉、起伏，表面因此带着细小的重复凹凸，手与眼都能读出来。"},"chain":["WOVEN CLOTH","THREADS CROSSING","HAND ON SURFACE","VISIBLE GRAIN","SHARED CHARACTER","MAPPED IMAGE"],"branches":[{"senses":"01","en":"THE CORE TOUCH: texture is first what the hand learns about a surface, its roughness or smoothness.","cn":"核心触感：质地首先是手从表面得知的东西，是粗糙还是光滑。"},{"senses":"02 · 03","en":"SIGHT AND WEAVE: the word keeps the woven structure of cloth and the visible grain of any surface, two readings of the same small pattern.","cn":"视觉与编织：这个词既保留布的编织结构，也指任何表面的可见纹理，两者是同一小片纹样的两种读法。"},{"senses":"04 · 05","en":"MOUTH AND EAR: food is judged by the same grain under the teeth, and a voice or a page is read as a fabric of details.","cn":"口与耳：食物靠牙齿下的同一份颗粒感被评判，嗓音或书页则被读成由细节织成的布。"},{"senses":"06 · 07","en":"THE WEAVE WIDENS: music combines lines like warp and weft, while geology measures the grains that make up a solid.","cn":"织法变宽：音乐像经纬那样把线条结合起来，地质学则测量构成固体的颗粒。"},{"senses":"08","en":"THE IMAGE ON THE SURFACE: a digital model receives a picture stretched over it, so the surface detail is supplied as an image.","cn":"表面上的图像：数字模型被铺上一张图，表面细节于是以图像的方式供给。"}]},"affixes":{"intro":{"en":"Texture can be read as a Latin verb, a Latin noun suffix and a Latin noun, with a small English adjective family built on top.","cn":"texture 可以读作一个拉丁动词、一个拉丁名词后缀和一个拉丁名词，再加上一小族英语形容词派生词。"},"latinIntro":{"en":"Latin texere 'to weave' with -ura 'result' produced textura 'fabric'; English borrowed it and later added -al and -ed for the adjectives.","cn":"拉丁语 texere「编织」加 -ura「结果」构成 textura「织物」；英语借入后，又加两个形容词词尾构成形容词。"},"items":[{"word":"texere","structure":"texere, texui, textum (Latin verb, third conjugation)","meaning":"to weave, to plait, to construct","meaningCN":"编织；编结；构造","example":"The verb supplies the action behind the whole family.","exampleCN":"这个动词提供整个词族的动作来源。"},{"word":"-ura","structure":"-ura (Latin noun suffix)","meaning":"the result or product of an action","meaningCN":"动作的结果或产物","example":"The suffix turns the act of weaving into the thing woven.","exampleCN":"这个后缀把编织的动作变成织成之物。"},{"word":"textura","structure":"texere + -ura (Latin noun)","meaning":"a weaving, a fabric","meaningCN":"编织；织物","example":"Latin used the noun for cloth and for the way it was woven.","exampleCN":"拉丁语用这个名词指布，也指它的织法。"},{"word":"texture","structure":"texture (English noun and verb)","meaning":"the feel or grain of a surface; to give a surface such a quality","meaningCN":"表面的手感或纹理；使表面具有这种性质","example":"English widened the noun from cloth to every surface.","exampleCN":"英语把这个名词从布匹扩展到一切表面。"},{"word":"-al","structure":"-al (English adjective suffix, from Latin -alis)","meaning":"pertaining to","meaningCN":"与……有关的","example":"The suffix turns the noun of texture into an adjective.","exampleCN":"这个后缀把表示质地的名词变成形容词。"},{"word":"textural","structure":"texture + -al","meaning":"relating to texture","meaningCN":"与质地或纹理有关的","example":"Critics praise the textural richness of the painting.","exampleCN":"评论家称赞这幅画丰富的肌理。"},{"word":"-ed","structure":"-ed (English past-participle suffix, from Old English -ed)","meaning":"having, provided with","meaningCN":"具有……的；带……的","example":"The suffix turns a noun into an adjective of possession.","exampleCN":"这个后缀把名词变成表示拥有的形容词。"},{"word":"textured","structure":"texture + -ed","meaning":"having a noticeable texture","meaningCN":"有明显质感的","example":"The walls are textured with coarse plaster.","exampleCN":"墙面用粗灰泥做出了纹理。"}],"latinEntries":[{"word":"texere","structure":"texere, texui, textum (verb, third conjugation)","meaning":"to weave","meaningCN":"编织"},{"word":"textura","structure":"textura, texturae (noun, first declension)","meaning":"weaving, fabric","meaningCN":"编织；织物"},{"word":"textus","structure":"textus, textus (noun, fourth declension)","meaning":"something woven; a text","meaningCN":"织成之物；文本"}],"derivatives":[{"word":"textural","structure":"texture + -al (adjective suffix, from Latin -alis 'pertaining to')","meaning":"the noun of surface quality shifts to an adjective describing what belongs to texture","meaningCN":"由表示表面性质的名词转为描述「属于质地」的形容词"},{"word":"textured","structure":"texture + -ed (past-participle suffix, from Old English -ed 'having')","meaning":"the noun shifts to an adjective meaning 'provided with a texture'","meaningCN":"由名词转为形容词，表示「带有某种质地」"}]}},{"word":"pattern","ipa_uk":"/ˈpætn/","ipa_us":"/ˈpætərn/","definition_zh":"图案；模式；规律；纸样；范例；（动词）仿照；以图案装饰","definition_en":"a repeated design or a regular arrangement; a model to copy; also a verb meaning to model something on another or to decorate with a design","core_image":"一个方块被刻成印版，压到布上，再压一次、又一次，同样的形状排成一片","scene":"裁缝铺的长桌上摊开一张纸样，粉笔线在布面上勾出重复的方格，The tailor pins the paper pattern onto the cloth before cutting.","sceneCN":"这里 pattern 指「裁剪用的纸样模板」（第 3 个义项：供复制用的样板）；句意为裁缝把纸质样板别到布上再下剪。图中可辨识物件：长桌、纸样、粉笔线、别针与格纹布面。","pos":[{"tag":"n.","zh":"图案；模式；纸样；范例"},{"tag":"v.","zh":"仿照；以图案装饰"}],"collocations":[{"phrase":"pattern of","zh":"……的规律或图案"},{"phrase":"weather pattern","zh":"天气模式"},{"phrase":"behaviour pattern","zh":"行为模式"},{"phrase":"pattern recognition","zh":"模式识别"},{"phrase":"sewing pattern","zh":"缝纫纸样"},{"phrase":"set a pattern","zh":"树立典范"}],"forms":[{"label":"复数","form":"patterns"},{"label":"第三人称单数","form":"patterns"},{"label":"过去式","form":"patterned"},{"label":"现在分词","form":"patterning"}],"derivatives":[{"word":"patterned","pos":"adj.","zh":"有图案的；按模式排列的"},{"word":"patterning","pos":"n.","zh":"图案形成；模式化"}],"senses":[{"no":"01","title":"A repeated decorative design","titleCN":"重复出现的装饰图案","definition":"a design of repeated shapes, lines or colours used to decorate a surface","definitionCN":"由重复的形状、线条或色彩构成、用于装饰表面的图样","example":"The curtains carry a small floral pattern.","exampleCN":"窗帘上带着细小的花卉图案。","why":"The word began as patron, 'a model to copy'; decoration repeats a copied unit across a surface.","whyCN":"这个词最初借自意为「可复制的范本」的外来词；装饰正是把一个被复制的单元铺满表面。"},{"no":"02","title":"A recurring sequence of events","titleCN":"事件反复出现的次序","definition":"a regular and repeated way in which events or actions occur","definitionCN":"事件或行为有规律地反复出现的方式","example":"The patient's sleep pattern changed after the journey.","exampleCN":"旅行之后，这位患者的睡眠规律变了。","why":"Once a model is repeated in time rather than on a surface, the repetition itself becomes the pattern.","whyCN":"当范本不是铺在表面、而是在时间中反复，重复本身就成了模式。"},{"no":"03","title":"A template or model for making copies","titleCN":"供复制使用的样板或模板","definition":"a shape or model used as a guide for cutting, sewing or casting","definitionCN":"裁剪、缝制或浇铸时用作依据的形状或模型","example":"She pinned the paper pattern to the fabric and cut along the chalk line.","exampleCN":"她把纸质样板别到布上，沿粉笔线剪开。","why":"This is the literal ancestor: a pattern is first an object you lay down and copy.","whyCN":"这是字面上的祖先义：pattern 最初就是一件可以铺下来照着复制的东西。"},{"no":"04","title":"The arrangement of parts that forms a whole","titleCN":"构成整体的部件排列","definition":"the way elements are arranged or organized in a whole","definitionCN":"各要素在整体中被排列或组织的方式","example":"The novel's pattern of images returns in the last chapter.","exampleCN":"小说中那组意象的排列在最后一章再次出现。","why":"From a copied outline the sense broadens to any arrangement whose parts answer one another.","whyCN":"从可复制的轮廓出发，词义扩展到任何部件彼此呼应的排列。"},{"no":"05","title":"A regularity detected in data or nature","titleCN":"在数据或自然中找出的规律","definition":"a recognizable regularity in measurements, behaviour or natural forms","definitionCN":"在测量、行为或自然形态中可辨认的规律性","example":"The software looks for patterns in the sales figures.","exampleCN":"软件在销售数据中寻找规律。","why":"Science makes the repetition an object of search: the pattern is the order found in what looked random.","whyCN":"科学把重复变成搜寻的对象：模式就是从看似随机之物里找出的秩序。"},{"no":"06","title":"A recurring arrangement in language","titleCN":"语言中反复出现的结构","definition":"a regular arrangement of sounds or words that speakers of a language follow","definitionCN":"说某种语言的人所遵循的、语音或词句的规律性排列","example":"The drill fixes the sentence pattern in memory.","exampleCN":"反复操练把句型固定在记忆里。","why":"Language is learned through repeated shapes, so the same word names the frames a speaker reuses.","whyCN":"语言通过反复的形状被学会，同一个词便用来命名说话者反复套用的框架。"},{"no":"07","title":"A model of conduct held up for imitation","titleCN":"供人效法的行为典范","definition":"an example or model of behaviour that others are expected to follow","definitionCN":"他人应当效仿的行为榜样或范例","example":"The older teachers were held up as a pattern of patience.","exampleCN":"那些年长的教师被举为耐心的典范。","why":"This restores the Latin model sense: patronus was a protector and an exemplar, and pattern kept that moral use into modern English.","whyCN":"这恢复了拉丁语的范本义：patronus 既是保护人也是榜样，pattern 把这一道德用法保留到现代英语。"},{"no":"08","title":"To model something on, or decorate with a design","titleCN":"仿照某物；以图案装饰","definition":"to make or shape something according to a model, or to decorate a surface with a regular design","definitionCN":"依照某个范本制作或塑造某物，或以规则图样装饰表面","example":"The garden was patterned on a larger estate in the north.","exampleCN":"这座花园是仿照北方一处更大的庄园建造的。","why":"The verb turns the noun into an action: whatever follows a model is patterned on it, and a surface given a repeated design is patterned too.","whyCN":"动词把名词变成动作：照着范本做的，就是依范本而制；被赋予重复图样的表面也可说带图样的。"}],"etymology":{"intro":{"en":"Pattern comes from Middle English patron, taken from Latin patronus 'protector, model', which was built on pater 'father'. Dates are approximate.","cn":"pattern 来自中古英语的借形，后者出自拉丁语 patronus「保护人、范本」，而 patronus 由 pater「父亲」构成。年代均为约数。"},"items":[{"era":"LATIN PATER","en":"Pater meant 'father'. It is the base of patronus and also of English words about fatherhood and protection.","cn":"pater 意为「父亲」。它既是 patronus 的词基，也是一批表示父系与保护的英语词的来源。"},{"era":"LATIN -ONUS","en":"The suffix -onus built nouns of role or function; added to pater it produced patronus, 'one who acts as a father to others'.","cn":"后缀 -onus 构成表示角色或职能的名词；加在 pater 上便产生 patronus，意为「替他人承担父职的人」。"},{"era":"LATIN PATRONUS","en":"Patronus meant 'protector, defender' and, in later Latin, 'a model or example to be followed'.","cn":"patronus 意为「保护人、辩护者」，在后期拉丁语中又指「可供效法的范本或榜样」。"},{"era":"OLD FRENCH PATRON","en":"English took patron through Old French, where it kept both the protector and the model senses.","cn":"英语经由古法语接受这个借形，古法语同时保留了保护人与范本两种含义。"},{"era":"MIDDLE ENGLISH PATTERN","en":"In Middle English the spelling shifted from patron to pattern, and the 'model' sense moved to the centre of the word.","cn":"在中古英语中，拼写最终定为 pattern，「范本」义逐渐成为这个词的核心。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: why the written form settled as pattern rather than patron is not fully explained; sixteenth-century spelling habits are generally assumed to be the cause.","cn":"来源不确定：书写形式为何最终定为 pattern 而非较早的借形，尚无完满解释；一般认为与 16 世纪的拼写习惯有关。"}]},"similar":{"note":{"en":"The first group holds words that look close to pattern, including its own ancestor; the second holds words for design and for models to copy, which differ in what they stress.","cn":"第一组是外形接近 pattern 的词，其中包含它自己的祖先形式；第二组指图案与可复制的范本，各自强调的方面不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"patron","ipa":"/ˈpeɪtrən/","tag":"historical source","definition":"A person who supports or protects someone; this is the form English borrowed first, before pattern took over the model sense.","definitionCN":"支持或保护他人的人；这是英语最先借入的形式，后来 pattern 才承担了范本义。"},{"word":"patent","ipa":"/ˈpætnt/","tag":"different root","definition":"An official right to an invention; from Latin patere 'to lie open', with no link to pater 'father'.","definitionCN":"对发明享有的官方专有权；来自拉丁语 patere「敞开」，与 pater「父亲」无关。"},{"word":"patten","ipa":"/ˈpætn/","tag":"different word","definition":"A wooden shoe or clog worn to raise the foot above mud; it only sounds like pattern and has no shared sense with it.","definitionCN":"垫高脚步以免陷入泥中的木鞋或木套鞋；只是读音像 pattern，意义并无交集。"}]},{"heading":"NEAR MEANING","entries":[{"word":"design","ipa":"/dɪˈzaɪn/","tag":"broader","definition":"The planned arrangement of lines, shapes or colours; design can be invented rather than repeated, while pattern stresses repetition.","definitionCN":"对线条、形状或色彩的规划性安排；设计可以原创而不必重复，pattern 则强调重复。"},{"word":"motif","ipa":"/məʊˈtiːf/","tag":"single unit","definition":"One repeated figure within a design; a motif is the unit that a pattern repeats.","definitionCN":"图案中反复出现的单个图形；母题正是被图案重复的那个单元。"},{"word":"template","ipa":"/ˈtempleɪt/","tag":"model","definition":"A shaped guide for cutting or drawing; it is the physical model sense of pattern, without the decorative senses.","definitionCN":"裁剪或描画用的成形样板；它就是 pattern 的实体范本义，不含装饰性的义项。"},{"word":"model","ipa":"/ˈmɒdl/","tag":"exemplar","definition":"A thing or person taken as an example to copy; model is wider and also covers scale models and abstract systems.","definitionCN":"被拿来照着做的物或人；model 范围更广，还包括缩比模型与抽象系统。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Pattern began as patron, a model to copy.","cn":"pattern 最初借自一个意为「可照抄的范本」的外来词。"},{"en":"A pattern repeats one unit across a surface, like a stamp pressed again and again.","cn":"图案是把一个单元铺满表面，像印章一次次压下去。"},{"en":"The paper pattern in a sewing shop is a model laid on cloth.","cn":"裁缝铺里的纸质样板，就是铺在布上的模型。"},{"en":"Weather patterns repeat in time, not on a wall.","cn":"天气模式在时间中重复，而不是在墙上重复。"},{"en":"Pattern recognition is the search for order in what first looks random.","cn":"模式识别就是在初看杂乱之处寻找秩序。"}],"abstract":[{"en":"Picture a single tile copied until the whole floor becomes a story.","cn":"想象一块瓷砖被不断复制，直到整个地面成为一个故事。"},{"en":"Picture a river that cuts the same bend every year.","cn":"想象一条河每年都切出同一个弯。"},{"en":"Picture a sentence frame that many different words can step into.","cn":"想象一个句子框架，许多不同的词都能走进去。"}]},"examples":[{"en":"The tiles form a geometric pattern across the floor.","cn":"瓷砖在地面上构成几何图案。"},{"en":"Doctors noticed a pattern in the patients' symptoms.","cn":"医生们注意到患者的症状中有一种规律。"},{"en":"The new school was patterned on a design from the coast.","cn":"这所新学校是仿照沿海地区的一个设计建造的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「派藤」——藤条编出的格子一遍遍重复，派上去铺满就成图案。patron 本是「范本」，照着范本一次次复制，就有了 pattern。","word":"pattern"},"root":"中古英语的借形来自拉丁语 patronus「保护人、范本」；patronus 由 pater「父亲」加名词后缀 -onus 构成。拼写后来变为 pattern，「范本、样板」义成为核心，再引申出图案、模式与规律等义。拼写变化的具体原因属假说。","sensesIntro":{"en":"Eight senses begin with a repeated decorative design, then move to a sequence in time and a model cut from paper, to arrangement and detected regularity, to language and moral example, and end with the verb.","cn":"八个义项从重复的装饰图案开始，转到时间中的次序与纸质样板，再到部件排列与被找出的规律，再到语言结构与道德典范，最后是动词用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: one unit is stamped, cut or copied again and again, so repetition itself becomes the visible order.","cn":"核心意象：一个单元被反复压印、裁剪或复制，重复本身成了可见的秩序。"},"chain":["MODEL TO COPY","REPEATED UNIT","SEQUENCE IN TIME","ARRANGED WHOLE","ORDER FOUND","GUIDING EXAMPLE"],"branches":[{"senses":"01","en":"THE REPEATED UNIT: the core sense is a copied shape repeated across a surface until the surface is covered.","cn":"重复的单元：核心义是一个被复制的形状在表面上反复出现，直到铺满。"},{"senses":"02 · 03","en":"REPETITION IN TIME OR ON PAPER: a habit repeats on a schedule, and a template is the model laid down before the copy is made.","cn":"在时间中或在纸上的重复：习惯按时间表反复，样板则是复制之前铺下的模型。"},{"senses":"04 · 05","en":"ARRANGEMENT AND ORDER: the word widens from a visible design to the way parts fit a whole, and then to a regularity found in data.","cn":"排列与秩序：词义从可见图样扩展到部件构成整体的方式，再扩展到数据中被找出的规律。"},{"senses":"06 · 07","en":"A SHAPE OTHERS COPY: a sentence frame is reused by speakers, and a moral example is held up for others to follow.","cn":"被别人复制的形状：句型被说话者反复套用，道德榜样则被举出来供人效法。"},{"senses":"08","en":"THE ACTION OF COPYING: the noun becomes a verb, so a thing can be patterned on a model or patterned with a design.","cn":"复制的动作：名词转为动词，于是可以说某物仿照某个范本，或表面被赋予图样。"}]},"affixes":{"intro":{"en":"Pattern can be read as a Latin noun base, a Latin role suffix and the English word that grew out of them, plus two adjective endings.","cn":"pattern 可以读作一个拉丁名词词基、一个拉丁角色后缀、由它们生长出来的英语词，再加两个形容词词尾。"},"latinIntro":{"en":"Latin pater 'father' with -onus produced patronus 'protector, model'; English shortened it to patron, respelled it pattern, and later added -ed and -less.","cn":"拉丁语 pater「父亲」加 -onus 构成 patronus「保护人、范本」；英语先缩略这个词形，再改写为 pattern，后来又加两个词尾构成形容词。"},"items":[{"word":"pater","structure":"pater, patris (Latin noun, third declension)","meaning":"father","meaningCN":"父亲","example":"The noun supplies the family image behind the Latin word.","exampleCN":"这个名词提供拉丁词背后的家族意象。"},{"word":"-onus","structure":"-onus (Latin noun-forming suffix)","meaning":"one who acts in a role or function","meaningCN":"承担某种角色或职能的人","example":"The suffix turns 'father' into a word for one who protects others.","exampleCN":"这个后缀把「父亲」变成表示保护他人者之词。"},{"word":"patronus","structure":"pater + -onus (Latin noun)","meaning":"protector, defender; a model","meaningCN":"保护人；辩护者；范本","example":"Latin used the noun for a protector and later for an example.","exampleCN":"拉丁语用这个名词指保护人，后来也指榜样。"},{"word":"patron","structure":"patron (English noun, from Old French)","meaning":"a supporter or protector","meaningCN":"赞助人；保护人","example":"English kept the older form beside its respelled doublet.","exampleCN":"英语把较旧的形式与改写后的同源词并存在一起。"},{"word":"pattern","structure":"pattern (English noun and verb, respelled from patron)","meaning":"a repeated design; a model to copy","meaningCN":"重复的图案；可复制的范本","example":"The respelled form took over the model and design senses.","exampleCN":"改写后的形式承接了范本与图案两种含义。"},{"word":"-ed","structure":"-ed (English past-participle suffix, from Old English -ed)","meaning":"having, provided with","meaningCN":"具有……的；带……的","example":"The suffix builds the adjective of possession.","exampleCN":"这个后缀构成表示拥有的形容词。"},{"word":"patterned","structure":"pattern + -ed","meaning":"having a pattern; modelled on something","meaningCN":"有图案的；仿照某物的","example":"The fabric is patterned with small squares.","exampleCN":"这块布上有小方格图案。"},{"word":"-less","structure":"-less (English privative suffix, from Old English -leas)","meaning":"without","meaningCN":"没有……的","example":"The suffix removes the quality the noun names.","exampleCN":"这个后缀去掉名词所指的性质。"}],"latinEntries":[{"word":"pater","structure":"pater, patris (noun, third declension)","meaning":"father","meaningCN":"父亲"},{"word":"patronus","structure":"patronus, patroni (noun, second declension)","meaning":"protector; model","meaningCN":"保护人；范本"}],"derivatives":[{"word":"patterned","structure":"pattern + -ed (past-participle suffix, from Old English -ed 'having')","meaning":"the noun of design shifts to an adjective meaning 'provided with a pattern' or 'modelled on something'","meaningCN":"由表示图案的名词转为形容词，表示「带有图案」或「仿照某物」"},{"word":"patternless","structure":"pattern + -less (privative suffix, from Old English -leas 'without')","meaning":"the noun shifts to an adjective meaning 'having no pattern'","meaningCN":"由名词转为形容词，表示「没有图案的」"}]}},{"word":"ornament","ipa_uk":"/ˈɔːnəmənt/ (noun), /ˈɔːnəment/ (verb)","ipa_us":"/ˈɔːrnəmənt/ (noun), /ˈɔːrnəment/ (verb)","definition_zh":"装饰品；装饰物；装饰纹样；为场所增光的人或物；装饰音；仪式礼器；装饰、点缀（动词）","definition_en":"a small object or added detail that decorates something; a person or thing that brings distinction; a musical flourish; a set of ceremonial vessels; also a verb meaning to adorn","core_image":"一只玻璃小球挂上圣诞树最低的枝条，整棵树因为这一点亮光就显出了节日的样子","scene":"圣诞树已经立好在客厅角落，彩球和细链正一层层挂上去，She lifts a glass ornament from the box and hooks it onto a low branch.","sceneCN":"这里 ornament 指「悬挂起来的小件装饰物」（第 1 个义项：单件装饰品）；句意为她从盒子里取出一只玻璃挂饰，挂到较低的枝条上。图中可辨识物件：立好的圣诞树、装挂饰的纸盒、玻璃球与细链。","pos":[{"tag":"n.","zh":"装饰品；装饰物；装饰音"},{"tag":"v.","zh":"装饰；点缀"}],"collocations":[{"phrase":"Christmas ornament","zh":"圣诞挂饰"},{"phrase":"architectural ornament","zh":"建筑装饰"},{"phrase":"an ornament to","zh":"为……增光的人或物"},{"phrase":"a mere ornament","zh":"纯粹的摆设"},{"phrase":"floral ornament","zh":"花卉纹饰"},{"phrase":"ornament a room with","zh":"用……装饰房间"}],"forms":[{"label":"复数","form":"ornaments"},{"label":"第三人称单数","form":"ornaments"},{"label":"过去式与过去分词","form":"ornamented"},{"label":"现在分词","form":"ornamenting"}],"derivatives":[{"word":"ornamental","pos":"adj.","zh":"装饰性的；作装饰用的"},{"word":"ornamentation","pos":"n.","zh":"装饰；装饰品；整体装饰体系"}],"senses":[{"no":"01","title":"A small object kept for display","titleCN":"为陈列而保留的小件装饰物","definition":"a small object, often hanging or standing, that is kept and shown because it makes a place look better","definitionCN":"常为悬挂或摆放的小件物品，因能让场所更好看而被保留、陈列","example":"A single silver ornament hung at the centre of the tree.","exampleCN":"树的中央挂着一件银质小饰品。","why":"This is the concrete end of the word: Latin ornamentum named the fittings of a house or a person, and English narrowed that set down to one pretty object.","whyCN":"这是这个词最具体的一端：拉丁 ornamentum 本指房屋或人的配备之物，英语把这一整组收窄成单独一件好看的物件。"},{"no":"02","title":"An added detail on a made object","titleCN":"制成品表面上的附加纹样","definition":"a pattern, carving or inlay added to an object to make it more beautiful rather than more useful","definitionCN":"为让物件更美而不是更有用而添加的图案、雕刻或镶嵌","example":"The brass clock is covered in engraved ornament.","exampleCN":"这座黄铜钟上布满雕刻纹饰。","why":"Once the object itself is no longer the unit, the word can name any added surface detail, and the emphasis moves from the thing to the marking.","whyCN":"当计量单位不再是物件本身，这个词就能指任何附加的表面细部，重心也从物件转到纹样。"},{"no":"03","title":"Decoration built into a building","titleCN":"砌入建筑的装饰细部","definition":"a decorative feature of a building, such as a moulding, capital or carved panel, that is part of the structure","definitionCN":"建筑上的装饰性构件，如线脚、柱头或雕刻板，本身属于结构的一部分","example":"The porch is enriched with stone ornament in a leaf pattern.","exampleCN":"门廊以叶片纹样的石雕装饰增色。","why":"Architecture needed a word for decoration that is fixed in place, and ornament supplied it because the Latin noun already meant the fittings of a structure.","whyCN":"建筑需要一个指固定不动的装饰的词，本词正好合用，因为拉丁名词本就是指建筑的配备件。"},{"no":"04","title":"A person who graces a group","titleCN":"为群体增光的人","definition":"a person whose presence or achievements bring credit to a place, profession or occasion","definitionCN":"其在场或成就为某地、某行业或某场合带来荣誉的人","example":"The retired judge was an ornament to the small committee.","exampleCN":"这位退休法官是那个小委员会的一大光彩。","why":"The figurative step treats social value as visible beauty: someone who makes a group look better is, in the old sense, a fitting.","whyCN":"这一步比喻把社会价值当作可见的美：让群体显得更体面的人，按旧义就是一件合宜的配备之物。"},{"no":"05","title":"Adornment itself, not the thing","titleCN":"装饰本身，而非装饰物","definition":"the quality or act of adorning, considered apart from any single object","definitionCN":"脱离任何单件物品来看的装饰性质或装饰行为","example":"The carving was added for ornament, not for strength.","exampleCN":"这道雕刻是为装饰而加，并非为了加固。","why":"English allows the noun to be a mass noun, so the word can name adornment in general and stand opposite to use or function.","whyCN":"英语允许这个名词作不可数用法，于是它能泛指装饰，并与用途、功能相对。"},{"no":"06","title":"An added note that beautifies a line","titleCN":"为旋律增色的附加音符","definition":"a grace note, trill or turn added to a melody to make it more elaborate","definitionCN":"为使旋律更繁复而加入的倚音、颤音或回音","example":"The pianist added a small ornament at the end of each phrase.","exampleCN":"钢琴家在每一乐句的结尾加了一个小装饰音。","why":"Music borrowed the idea directly: what is added for beauty rather than necessity is an ornament, and the term survived as a technical label.","whyCN":"音乐直接借用了这一想法：为美而非为必需添加的东西就是装饰，这个说法作为术语沿用下来。"},{"no":"07","title":"Vessels and fittings of a ceremony","titleCN":"仪式所用的器皿与陈设","definition":"the decorated vessels and furnishings used in a religious or state ceremony","definitionCN":"宗教或国家仪式上使用的装饰性器皿与陈设","example":"The cathedral keeps its silver ornament locked in the treasury.","exampleCN":"主教座堂把银质礼器锁在宝物室里。","why":"Here the older collective sense returns: ornament is not one pretty thing but the whole set of fittings proper to a solemn place.","whyCN":"这里回归较古老的集合义：本词不是一件好看的东西，而是一个庄严场所应有的整套陈设。"},{"no":"08","title":"To decorate something (verb)","titleCN":"装饰某物（动词）","definition":"to decorate or embellish something, especially in a careful or formal way","definitionCN":"装饰或点缀某物，尤指用心地、正式地加以修饰","example":"Fresh laurel ornamented the doorway for the ceremony.","exampleCN":"为这场典礼，新鲜的月桂装饰了门廊。","why":"The verb keeps the Latin verb's active sense of fitting something out, and its stress falls on the last syllable, which sets it apart from the noun.","whyCN":"动词保留了拉丁动词「为某物配齐装备」的主动义；重音落在末音节，与名词区分开来。"}],"etymology":{"intro":{"en":"Ornament comes from Latin ornamentum 'equipment, adornment', a noun built on the verb ornare 'to equip, fit out, adorn'. Dates are approximate.","cn":"ornament 来自拉丁语 ornamentum「装备、装饰物」，由动词 ornare「装饰、配备」加名词后缀 -mentum 构成。年代均为约数。"},"items":[{"era":"LATIN ORNARE","en":"Ornare meant 'to equip, fit out, adorn'. It was used of preparing a person, a house or a ship for use, so adornment and equipment were the same act.","cn":"ornare 意为「装备、配备、装饰」。它用于把人、房屋或船准备停当，所以装饰与配备在当时是同一个动作。"},{"era":"LATIN ORNAMENTUM","en":"The suffix -mentum formed nouns of means or result, so ornamentum was the equipment or furnishing of something, and by extension its adornment.","cn":"后缀 -mentum 构成表示手段或结果的名词，因此 ornamentum 指某物的装备与陈设，进而指它的装饰。"},{"era":"OLD FRENCH ORNEMENT","en":"Old French took the noun as ornement and kept both faces of it, the furnishing of a place and the beauty added to it.","cn":"古法语接受这个名词并把它变作自己的形式，两面都保留下来：场所的陈设，以及为之增添的美。"},{"era":"MIDDLE ENGLISH NOUN","en":"English borrowed the word in the thirteenth century; early uses covered church furnishing, military equipment and adornment generally.","cn":"英语在 13 世纪借入这个词；早期用法涵盖教堂陈设、军备以及一般意义上的装饰。"},{"era":"NOUN AND VERB","en":"Later the noun narrowed to a single decorative object, and a verb ornament 'to adorn' grew beside it, with the stress moved to the final syllable.","cn":"后来名词收窄为单件装饰物，旁边又长出动词 ornament「装饰」，重音移到末音节。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of ornare is not established, so any Indo-European root proposed for it is a reconstruction rather than a witnessed form.","cn":"来源不确定（更深词源）：ornare 在拉丁语之前的来源并无定论，凡为其提出的印欧词根均属重构形式，而非实际书证。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close to ornament, including one from another root; the second holds near synonyms that differ in whether they name an object, an act or a whole scheme.","cn":"第一组是与本词形近或音近的词，其中有一个来自别的词根；第二组是近义词，区别在于所指是一件物品、一个动作还是一整套方案。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ornate","ipa":"/ɔːˈneɪt/","tag":"same root, adjective","definition":"Elaborately decorated; it goes back to the same Latin verb ornare, but it describes a style rather than an object.","definitionCN":"装饰繁复的；同出拉丁动词 ornare，但描述的是风格而非物件。"},{"word":"ornamental","ipa":"/ˌɔːnəˈmentl/","tag":"same family, adjective","definition":"Serving as decoration; formed from this noun with an adjective suffix, so it answers the question of what a thing is for.","definitionCN":"作装饰用的；由本词加形容词后缀构成，回答的是「它作何用」。"},{"word":"ordnance","ipa":"/ˈɔːdnəns/","tag":"different root","definition":"Military supplies and guns; it comes from the same source as the word for a decree, not from ornare.","definitionCN":"军械与火炮；与表示「法令」的词同源，与 ornare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decoration","ipa":"/ˌdekəˈreɪʃn/","tag":"general term, other root","definition":"The act or result of decorating, and a neutral cover term for anything added for beauty; it belongs to the decorare family, not the ornare family.","definitionCN":"装饰的行为或结果，也是任何为美观而添加之物的中性统称；属 decorare 一族，与 ornare 一族不同源。"},{"word":"adornment","ipa":"/əˈdɔːnmənt/","tag":"same root, act or thing","definition":"The act of adorning or the thing added; it comes from adorn, which is Latin adornare, ornare with the prefix ad-.","definitionCN":"装饰的行为或添加之物；来自表示「装饰」的英语动词，其拉丁语形式由「装饰」词根加表示「向」的前缀构成。"},{"word":"embellishment","ipa":"/ɪmˈbelɪʃmənt/","tag":"added detail","definition":"A detail added to make something richer or more interesting, often in speech or writing as well as in design.","definitionCN":"为使事物更丰富或更有趣而添加的细节，既用于设计与写作，也用于言谈。"},{"word":"trinket","ipa":"/ˈtrɪŋkɪt/","tag":"small and cheap","definition":"A small ornament of little value; it names the object and implies cheapness, which this word does not.","definitionCN":"价值不高的小饰物；指物件并含廉价之意，而本词不含此意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Ornare 'to equip' plus -mentum 'means or result' gives the fittings of a thing, and later its finery.","cn":"ornare「配备」加 -mentum「手段或结果」= 一件东西的配备，后来成了它的华饰。"},{"en":"A ship's ornamenta were once its gear; the word still carries that old idea of fitting something out.","cn":"船的 ornamenta 原本指它的索具装备；这个词至今仍带着「为某物配齐」的旧意。"},{"en":"The noun puts the stress at the front and the verb puts it at the end; the shift marks the change of job.","cn":"名词把重音放在前面，动词把重音放在末尾；重音的移动标记了词性的转换。"},{"en":"Architects call a fixed decorative feature an ornament, never a decoration, because it is built into the fabric.","cn":"建筑师把砌进本体的固定饰件称作装饰细部，而不说「装饰」，因为它属于结构本身。"},{"en":"Christmas ornaments are small, many and hung, so the plural suits objects that arrive in sets.","cn":"圣诞挂饰小而多、逐件悬挂，复数形式正适合成批出现的物件。"}],"abstract":[{"en":"Picture one bright bead on a dark tree: the whole room changes because a small thing was added.","cn":"想象暗色圣诞树上的一颗亮珠：只因添了一件小东西，整个房间都变了。"},{"en":"Picture a plain doorway that becomes ceremonial the moment laurel is tied across it.","cn":"想象一道普通的门，在系上一条月桂的那一刻变得庄重。"},{"en":"Picture a person who is of no use in the room but makes the room worth entering.","cn":"想象一个人，在房间里并无用处，却让这房间值得走进去。"}]},"examples":[{"en":"She keeps a box of glass ornaments for the tree.","cn":"她留着一盒玻璃挂饰，专供圣诞树用。"},{"en":"The lintel carries a carved ornament of overlapping leaves.","cn":"门楣上有一道叠叶纹样的雕刻装饰。"},{"en":"Hosts ornament the table with branches and small candles.","cn":"主人用枝条和小蜡烛装饰餐桌。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「哦，那门」——门口挂的那串小饰物，就是装饰品。拉丁 ornare 是「配备、装饰」，配上去的多余之物，正是装饰。名词重音在前，动词重音在后，读音也跟着换了身份。","word":"ornament"},"root":"拉丁 ornare「装饰、配备」加名词后缀 -mentum「手段或结果」构成 ornamentum「装备、装饰物」，经古法语进入英语；名词指装饰物，动词指装饰。ornare 在拉丁语之前的来源不确定，相关印欧词根属重构形式。","sensesIntro":{"en":"Eight senses run from a single hanging object through surface detail, built ornament, a person who brings credit, adornment as such, a musical note and a set of ceremonial vessels, and end with the verb 'to adorn'.","cn":"八个义项从单件悬挂饰品出发，经过表面纹样、建筑饰件、为群体增光的人、装饰本身、音乐装饰音与仪式礼器，最后落在动词「装饰」。"},"semanticMap":{"core":{"en":"CORE IMAGE: one small bright thing added to a plain surface, so that the whole surface reads as cared for.","cn":"核心意象：在素净的表面上添一件小而亮的东西，整个表面因此显得被用心对待。"},"chain":["SMALL HANGING THING","SURFACE DETAIL","BUILT FEATURE","PERSON AS CREDIT","ADDED NOTE","ACT OF ADORNING"],"branches":[{"senses":"01","en":"THE OBJECT: the concrete end of the word, a piece kept because it makes a place look better.","cn":"物件：这个词最具体的一端，一件因能让场所更好看而被保留的东西。"},{"senses":"02 · 03","en":"SURFACE AND STRUCTURE: the same idea moves from a marking on an object to a feature built into a building.","cn":"表面与结构：同一想法从物件上的纹样移到砌进建筑的构件。"},{"senses":"04 · 05","en":"PERSON AND QUALITY: adornment can be a human presence that brings credit, or the abstract act of adorning itself.","cn":"人与性质：装饰可以是为群体增光的在场之人，也可以是抽象的装饰行为本身。"},{"senses":"06 · 07","en":"SPECIALISED SETS: music keeps the added-for-beauty idea in a single note, while ceremony keeps the older collective sense of fittings.","cn":"专门领域：音乐把「为美而添加」收在一个音符上，仪式则保留较早的「整套陈设」集合义。"},{"senses":"08","en":"THE VERB: the act of fitting something out with beauty, with the stress moved to the last syllable.","cn":"动词：为某物配齐美观之物的动作，重音移到末音节。"}]},"affixes":{"intro":{"en":"Ornament is built from one Latin verb, one Latin noun suffix and a small English family, so it can be read piece by piece.","cn":"ornament 由一个拉丁动词、一个拉丁名词后缀和一小族英语派生词构成，可以逐块读出。"},"latinIntro":{"en":"Latin ornare 'to equip, adorn' gives ornamentum and the English family; the suffix -mentum marks means or result, and English later added -al and -ation for quality and process.","cn":"拉丁 ornare「配备、装饰」衍生出 ornamentum 与英语这一族词；拉丁后缀 -mentum 表示手段或结果，英语后来又加表示性质与过程的后缀。"},"items":[{"word":"ornare","structure":"ornare, ornatus (Latin verb, first conjugation)","meaning":"to equip, fit out, adorn","meaningCN":"配备；装备；装饰","example":"The verb describes the act of fitting something out.","exampleCN":"这个动词描述为某物配齐装备的动作。"},{"word":"-mentum","structure":"-mentum (Latin noun suffix, neuter)","meaning":"means or result of an action","meaningCN":"动作的手段或结果","example":"The suffix turns the act of fitting out into the fittings themselves.","exampleCN":"这个后缀把「配齐」的动作变成所配之物。"},{"word":"ornamentum","structure":"ornare + -mentum (Latin noun)","meaning":"equipment, furnishing, adornment","meaningCN":"装备；陈设；装饰物","example":"Latin used the noun for the fittings of a house, a ship or a person.","exampleCN":"拉丁语用这个名词指房屋、船只或人的配备之物。"},{"word":"ornament","structure":"ornamentum, through Old French ornement","meaning":"a decorative object; to adorn","meaningCN":"装饰物；装饰","example":"English kept both the noun and the later verb.","exampleCN":"英语同时保留了名词和后来出现的动词。"},{"word":"-al","structure":"-al (adjective suffix, from Latin -alis)","meaning":"pertaining to, serving as","meaningCN":"与……有关的；用作……的","example":"The suffix turns the noun into an adjective of function.","exampleCN":"这个后缀把名词变成表示用途的形容词。"},{"word":"ornamental","structure":"ornament + -al","meaning":"serving as decoration","meaningCN":"装饰性的；作装饰用的","example":"An ornamental feature is there to be looked at.","exampleCN":"装饰性构件之所以存在，是为了被人观看。"},{"word":"-ation","structure":"-ation (noun suffix, from Latin -atio, -ationis)","meaning":"action, process or result","meaningCN":"动作、过程或结果","example":"The suffix turns a verb or noun into a name for a process.","exampleCN":"这个后缀把动词或名词变成表示过程的名词。"},{"word":"ornamentation","structure":"ornament + -ation","meaning":"the act or result of decorating, or the decoration as a whole","meaningCN":"装饰行为或结果；整体装饰","example":"The word treats many ornaments as one system.","exampleCN":"这个词把许多装饰件当作一个体系来看。"}],"latinEntries":[{"word":"ornare","structure":"ornare, ornatus (verb, first conjugation)","meaning":"to equip, fit out, adorn","meaningCN":"配备；装饰"},{"word":"ornamentum","structure":"ornamentum, ornamenti (n., second declension)","meaning":"equipment, adornment","meaningCN":"装备；装饰物"}],"derivatives":[{"word":"ornamental","structure":"ornament + -al (adjective suffix, from Latin -alis): the noun of a decorative thing shifts to an adjective of function","meaning":"serving as decoration rather than as structure","meaningCN":"作装饰之用而非结构之用的"},{"word":"ornamentation","structure":"ornament + -ation (noun suffix, from Latin -atio): the single object shifts to the process and the collected result","meaning":"the act or system of decorating","meaningCN":"装饰的行为或整体装饰体系"}]}},{"word":"decorative","ipa_uk":"/ˈdekərətɪv/","ipa_us":"/ˈdekərətɪv/","definition_zh":"装饰的；装饰性的；作装饰用的；属于装饰艺术的；（风格上）富装饰的；仅作点缀的","definition_en":"serving to decorate; relating to decoration or to the decorative arts; also used of things valued for looks rather than for use","core_image":"一只白瓷盘的沿口描了一圈蓝线，它并不盛东西，只为放在架上给人看","scene":"样板间的墙面刷成哑光米色，所有家具都只为好看而选，A decorative panel above the sofa repeats the same leaf pattern.","sceneCN":"这里 decorative 指「起装饰作用的」（第 1 个义项：装饰的功能）：构件没有承重任务，只负责好看；句意为沙发上方的装饰板重复着同一叶片纹样。图中可辨识物件：哑光墙面、素色沙发、重复纹样的装饰板。","pos":[{"tag":"adj.","zh":"装饰的；装饰性的"}],"collocations":[{"phrase":"decorative arts","zh":"装饰艺术"},{"phrase":"decorative element","zh":"装饰性元素"},{"phrase":"purely decorative","zh":"纯为装饰的"},{"phrase":"decorative pattern","zh":"装饰图案"},{"phrase":"decorative rather than functional","zh":"装饰性的而非功能性的"},{"phrase":"decorative finish","zh":"装饰性表层"}],"forms":[{"label":"比较级","form":"more decorative"},{"label":"最高级","form":"most decorative"},{"label":"副词","form":"decoratively"}],"derivatives":[{"word":"decoratively","pos":"adv.","zh":"以装饰的方式；就装饰而言"},{"word":"decorativeness","pos":"n.","zh":"装饰性；作装饰之用的性质"}],"senses":[{"no":"01","title":"Serving to decorate","titleCN":"起装饰作用的","definition":"having the purpose or effect of making something look better","definitionCN":"目的在于或实际效果上使某物更好看","example":"A decorative band runs along the edge of the plate.","exampleCN":"一道装饰带沿盘子的边缘展开。","why":"The adjective is built on the verb of adorning, so it names a function, 'that decorates', before it names any style.","whyCN":"这个形容词从表示「装饰」的动词而来，因此先指功能——「起装饰作用的」——再指某种风格。"},{"no":"02","title":"Belonging to the decorative arts","titleCN":"属于装饰艺术范畴的","definition":"relating to the arts that make useful objects beautiful, such as ceramics, furniture and textiles","definitionCN":"与把实用物件做得美观的技艺有关的，如陶瓷、家具与织物","example":"The museum separates its decorative arts from its paintings.","exampleCN":"博物馆把装饰艺术品与绘画分开陈列。","why":"Museums and scholars needed a label for work whose beauty is carried by a useful object, and the adjective supplied it.","whyCN":"博物馆与学者需要一个标签，来指美附着于实用物件之上的作品，这个形容词正好补上。"},{"no":"03","title":"Valued for appearance","titleCN":"因外观而被选用","definition":"chosen because it looks good, even if it adds nothing to performance","definitionCN":"因其好看而被选用，即使对性能毫无增益","example":"The extra buttons on the jacket are decorative and do nothing.","exampleCN":"外套上多出的扣子纯为观感，并无实际作用。","why":"The sense marks a contrast with function: what is decorative is there to be seen, not used.","whyCN":"这一义项标出与功能的对照：装饰性的东西是供人观看的，不是供人使用的。"},{"no":"04","title":"Richly ornamented in style","titleCN":"风格上富装饰的","definition":"having a rich, elaborate surface, as of a style, period or object","definitionCN":"表面繁复华丽的，用以形容风格、时期或物件","example":"The hall is decorative in a late nineteenth-century manner.","exampleCN":"这座大厅带有 19 世纪晚期的繁复装饰风格。","why":"When the adjective describes the object rather than its job, it turns from function into degree: how much ornament a surface carries.","whyCN":"当这个形容词描述物件本身而非其用途，它就从功能转成程度：一个表面承载了多少装饰。"},{"no":"05","title":"Merely for show","titleCN":"仅作门面的","definition":"used of changes or measures that improve appearance without touching the real problem","definitionCN":"指只改善外观、不触及真正问题的改动或措施","example":"The report calls the new rules decorative rather than effective.","exampleCN":"报告称这些新规只作门面，并未见效。","why":"The pejorative use grows from the same contrast: if decoration is what is added for looks, then a decorative fix is one that only looks like a fix.","whyCN":"贬义用法出自同一个对照：既然装饰是为好看而添加的东西，那么「装饰性的」改动就只是看起来像改动。"},{"no":"06","title":"Applied rather than structural","titleCN":"附加而非承重的","definition":"in building, describing ornament applied to a structure and carrying no load","definitionCN":"建筑中，指附加于结构之上、不承重的装饰","example":"The decorative cornice hides the joint between wall and roof.","exampleCN":"装饰性檐口遮住了墙与屋顶的接缝。","why":"Architecture keeps the sharpest form of the contrast, dividing what holds a building up from what is put on it for beauty.","whyCN":"建筑保留了这一对照最锋利的形式，把支撑建筑的部分与为美而加上去的部分区分开。"},{"no":"07","title":"Non-textual elements in printing","titleCN":"印刷中的非文字元素","definition":"describing rules, borders and letterforms used for ornament rather than for reading","definitionCN":"指用作装饰而非供阅读的线条、边框与字形","example":"The chapter opens with a decorative initial in red ink.","exampleCN":"这一章以一枚红墨装饰性首字母开篇。","why":"Print inherited the word when type founders needed to separate letters that carry meaning from marks that only please the eye.","whyCN":"印刷业沿用了这个词，因为铸字者需要把承载意义的字母与只取悦眼睛的记号分开。"},{"no":"08","title":"Charming but without a function","titleCN":"悦目而无所事事","definition":"said of a person who is attractive or entertaining in a setting but has no real role in it","definitionCN":"指在某个场合中好看或讨喜、却并无实际角色的人","example":"He was decorative at the dinner and said nothing of substance.","exampleCN":"他在晚宴上只是好看，没说任何有分量的话。","why":"The last step applies the same test to people: present for appearance, absent in function, and mildly disparaging.","whyCN":"最后一步把同一标准用到人身上：为外观而在场，在功能上缺席，并略带贬义。"}],"etymology":{"intro":{"en":"Decorative comes from the Latin verb decorare 'to decorate', built on the noun decus 'beauty, grace, honour'. It belongs to the dec- line and shares no root with ornare and ornamentum. Dates are approximate.","cn":"decorative 来自拉丁动词 decorare「装饰」，其基础是名词 decus「美、体面、荣誉」。它出自 decus 与 decorare 这一条词源线，与 ornare、ornamentum 不同源。年代均为约数。"},"items":[{"era":"LATIN DECUS","en":"Decus, decoris was a neuter noun for beauty, grace and honourable distinction; it could name a person's standing as well as a surface's loveliness.","cn":"decus, decoris 是中性名词，指美、优雅与体面的荣誉；它既能指一个人的地位，也能指表面的悦目。"},{"era":"LATIN DECORARE","en":"The verb decorare 'to adorn, honour, make beautiful' was formed on the same stem, so adorning was also a way of doing honour to something.","cn":"动词 decorare「装饰、使之美、致敬」由同一词干构成，所以装饰同时也是向某物致敬的方式。"},{"era":"ENGLISH DECORATE","en":"English took the verb in the sixteenth century through the Latin past participle decoratus; it meant to adorn and later to paint or paper a room.","cn":"英语在 16 世纪经由拉丁过去分词 decoratus 接受这个动词，意为装饰，后来又指为房间刷漆或贴墙纸。"},{"era":"LATIN -IVUS","en":"The adjective suffix -ivus marked a tendency or a function, and English -ive inherited that role: what is decorative tends to decorate.","cn":"拉丁形容词后缀 -ivus 表示倾向或功能，英语继承了这一作用：装饰性的东西倾向于起装饰之用。"},{"era":"ENGLISH ADJECTIVE","en":"Decorative appears in English in the seventeenth century, first describing ornament that serves an object rather than a style of it.","cn":"decorative 在 17 世纪出现于英语，最初描述为物件服务的装饰，而非物件的某种风格。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of decus is not established, so the Indo-European root sometimes cited for it is a reconstruction rather than a witnessed form.","cn":"来源不确定（更深词源）：decus 在拉丁语之前的来源并无定论，有时为其引用的印欧词根属重构形式，而非实际书证。"}]},"similar":{"note":{"en":"The first group holds words close in form to decorative, two from the same family and one from another root; the second holds near synonyms that differ in whether they name a style, an act, an object or a whole system.","cn":"第一组是形式上接近本词的词，两个同族，一个来自别的词根；第二组是近义词，区别在于它们指风格、行为、物件还是一整套体系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decoration","ipa":"/ˌdekəˈreɪʃn/","tag":"same family, noun","definition":"The act or result of decorating, and a cover term for anything added for beauty; it is the noun beside this adjective.","definitionCN":"装饰的行为或结果，也是任何为美观而添加之物的统称；它是这个形容词旁边的名词。"},{"word":"decorator","ipa":"/ˈdekəreɪtə/","tag":"same family, agent noun","definition":"A person whose trade is decorating interiors; the agent suffix marks the worker rather than the quality.","definitionCN":"以装饰室内为业的人；施事后缀标记的是从业者，而非性质。"},{"word":"dedication","ipa":"/ˌdedɪˈkeɪʃn/","tag":"different root","definition":"The act of committing oneself or a work to a purpose; it comes from dedicare 'to dedicate', not from decorare.","definitionCN":"把自己或作品献给某一目的的行为；来自 dedicare「献奉」，与 decorare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ornamental","ipa":"/ˌɔːnəˈmentl/","tag":"other root line","definition":"Serving as ornament; it comes from the ornare family and stresses the role of an added object rather than the quality of a surface.","definitionCN":"作装饰用的；来自 ornare 一族，强调附加物件的作用，而非表面的性质。"},{"word":"ornate","ipa":"/ɔːˈneɪt/","tag":"style word","definition":"Richly decorated in detail; it describes a surface's density of ornament, while this word can simply mean 'not functional'.","definitionCN":"细部装饰繁复的；描述表面装饰的密度，而本词可以只表示「无功能」。"},{"word":"cosmetic","ipa":"/kɒsˈmetɪk/","tag":"superficial sense","definition":"Done to improve appearance only; it matches the pejorative sense of this word but is more openly negative.","definitionCN":"仅为改善外观而做的；与本词的贬义义项相近，但否定意味更明显。"},{"word":"picturesque","ipa":"/ˌpɪktʃəˈresk/","tag":"different focus","definition":"Pleasing as a view or scene, especially in a quaint way; it judges how something looks from outside, not what it is for.","definitionCN":"作为景致悦目的，尤指古雅有味；判断的是外观如何，而不是用途。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Decorare 'to adorn' plus a suffix meaning 'tending to' gives the sense 'tending to adorn'.","cn":"decorare「装饰」加表示「倾向于……」的形容词后缀 = 倾向于起装饰作用的。"},{"en":"The same adjective ending also builds the words for active, creative and protective, all of them about what something does.","cn":"同样的形容词后缀还见于表示「主动的」「创造的」「保护的」一类词，都是说明某物起什么作用的词。"},{"en":"Decorative is not the same as decorated: one is a job, the other is a finished state.","cn":"装饰性的不等于「被装饰过的」：一个说的是用途，一个说的是已完成的状态。"},{"en":"Museum labels separate the decorative arts from the fine arts, and the word marks the useful object made beautiful.","cn":"博物馆把装饰艺术与纯艺术分开标注，这个词标记的是被做得美观的实用物件。"},{"en":"If a rule is called decorative, it is being accused of existing only for appearance.","cn":"若一条规定被称作装饰性的，它等于被指为只为外观而存在。"}],"abstract":[{"en":"Picture a plate rim painted blue: the line holds nothing, yet the plate now looks finished.","cn":"想象盘沿描上一道蓝线：这条线不承托任何东西，盘子却因此显得完整。"},{"en":"Picture a building where every third stone is carved and none of them carries weight.","cn":"想象一座建筑，每三块石头就有一块被雕过，而它们都不承重。"},{"en":"Picture a room that looks better the moment someone charming walks in and does nothing.","cn":"想象一个房间，在一位有魅力的闲人走进来的一刻显得更好。"}]},"examples":[{"en":"The bowl is decorative, so it sits on the shelf rather than in the kitchen.","cn":"这只碗是装饰性的，所以摆在架上，而不在厨房用。"},{"en":"A decorative arch frames the entrance without supporting anything.","cn":"一道装饰性拱券框住入口，却不承托任何东西。"},{"en":"Her role in the film is decorative rather than dramatic.","cn":"她在这部片子里的角色只是点缀，并无戏剧分量。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「得可装饰」——念起来像「拿来就可以装饰」：一圈蓝边、一排雕花，东西立刻显得讲究。拉丁 decorare 是「装饰」，再加表示倾向的形容词后缀，合起来就是「倾向于装饰的」。","word":"decorative"},"root":"拉丁 decus「美、体面」构成动词 decorare「装饰」，英语经过去分词 decoratus 接受为表示「装饰」的动词，再加表示倾向的形容词后缀构成 decorative。此线出自 decus 与 decorare，与 ornare、ornamentum 不同源；decus 在拉丁语之前的来源不确定，相关印欧词根属重构形式。","sensesIntro":{"en":"Eight senses begin with the plain function of decorating, then the decorative arts, appearance chosen over use, an ornate style, a cosmetic show, ornament applied to a building, printed ornament and finally a person valued only for appearance.","cn":"八个义项从「起装饰作用」这一功能开始，继而指装饰艺术、重外观而轻用途的选择、繁复风格、门面功夫、砌入建筑的附加装饰、印刷装饰元素，最后指只以外观取胜的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blue line painted on the rim of a plate that holds nothing, so the surface is improved without being made stronger.","cn":"核心意象：盘沿描的一道蓝线不承托任何东西，表面因此变美，却未因此变强。"},"chain":["SERVING TO DECORATE","ARTS OF ORNAMENT","APPEARANCE OVER USE","RICH SURFACE","MERE SHOW","APPLIED LAYER"],"branches":[{"senses":"01","en":"THE FUNCTION: the adjective answers what a thing is for, namely to make something else look better.","cn":"功能：这个形容词回答一件东西作何用，即让别的东西更好看。"},{"senses":"02 · 03","en":"A FIELD AND A CHOICE: whole categories of useful objects are judged by beauty, and single features are chosen for looks alone.","cn":"一个领域与一种取舍：整类实用物件按美来评判，单个构件则纯因外观被选中。"},{"senses":"04","en":"THE DEGREE: used of a style, the word stops naming a job and starts measuring how much ornament a surface carries.","cn":"程度：用于风格时，这个词不再指用途，而开始衡量一个表面承载了多少装饰。"},{"senses":"05 · 08","en":"SHOW OVER SUBSTANCE: a decorative reform and a decorative guest share the same accusation, appearance without function.","cn":"重表轻实：装饰性的改革与装饰性的来宾共享同一条指控——只有外观，没有功能。"},{"senses":"06 · 07","en":"APPLIED SURFACE: in buildings and in print, the word separates what carries load or meaning from what is put on top to please the eye.","cn":"附加的表面：在建筑与印刷中，这个词把承重或载义的部分与为悦目而覆在上面的部分分开。"}]},"affixes":{"intro":{"en":"Decorative is built from a Latin noun, a Latin verb, one Latin suffix and a short English chain, so it can be read piece by piece.","cn":"decorative 由一个拉丁名词、一个拉丁动词、一个拉丁后缀和一段简短的英语派生链构成，可以逐块读出。"},"latinIntro":{"en":"Latin decus 'beauty, honour' gives decor, decorus and decorare; the verb passes into English as decorate, and the suffix -ive turns it into an adjective of function.","cn":"拉丁 decus「美、荣誉」衍生出 decor、decorus 与 decorare；动词进入英语后成为表示「装饰」的动词，表示功能的后缀再把它变成形容词。"},"items":[{"word":"decus","structure":"decus, decoris (Latin noun, third declension, neuter)","meaning":"beauty, grace, honour","meaningCN":"美；优雅；荣誉","example":"The noun is the source of the whole family and names beauty and standing at once.","exampleCN":"这个名词是整族词的源头，同时指美与体面。"},{"word":"decor","structure":"decor, decoris (Latin noun, third declension, masculine)","meaning":"beauty, comeliness","meaningCN":"美；秀美","example":"A related noun kept the plain idea of visible beauty.","exampleCN":"一个同族名词保留了「可见之美」的朴素含义。"},{"word":"decorus","structure":"decorus, decora, decorum (Latin adjective)","meaning":"beautiful, seemly, fitting","meaningCN":"美的；合宜的；得体的","example":"The adjective judged whether a thing looked right as well as whether it was well made.","exampleCN":"这个形容词既判断事物是否好看，也判断它是否得体。"},{"word":"decorare","structure":"decus stem + -are (Latin verb, first conjugation)","meaning":"to adorn, honour, make beautiful","meaningCN":"装饰；使之美；致敬","example":"The verb carries the act, and English took it through its past participle.","exampleCN":"动词承载动作本身，英语经由它的过去分词接受它。"},{"word":"decorate","structure":"decorare, through Latin decoratus","meaning":"to adorn; to paint or paper a room","meaningCN":"装饰；为房间刷漆或贴墙纸","example":"English uses the verb for both honouring and furnishing.","exampleCN":"英语用这个动词兼指致敬与陈设。"},{"word":"-ive","structure":"-ive (adjective suffix, from Latin -ivus)","meaning":"tending to, serving for","meaningCN":"倾向于……的；供……用的","example":"The suffix turns a verb of action into an adjective of tendency.","exampleCN":"这个后缀把表动作的动词变成表倾向的形容词。"},{"word":"decorative","structure":"decorate + -ive","meaning":"serving to decorate","meaningCN":"起装饰作用的","example":"The adjective names a function before it names a style.","exampleCN":"这个形容词先指功能，后指风格。"},{"word":"decoratively","structure":"decorative + -ly (adverb suffix, from Old English -lice)","meaning":"in a decorative manner","meaningCN":"以装饰的方式","example":"The adverb tells you how the thing was done.","exampleCN":"这个副词说明事情是以何种方式做的。"}],"latinEntries":[{"word":"decus","structure":"decus, decoris (n., third declension)","meaning":"beauty, honour","meaningCN":"美；荣誉"},{"word":"decor","structure":"decor, decoris (m., third declension)","meaning":"beauty, comeliness","meaningCN":"美；秀美"},{"word":"decorus","structure":"decorus, decora, decorum (adj., first and second declension)","meaning":"beautiful, seemly","meaningCN":"美的；合宜的"},{"word":"decorare","structure":"decorare, decoratus (verb, first conjugation)","meaning":"to adorn, honour","meaningCN":"装饰；致敬"}],"derivatives":[{"word":"decoratively","structure":"decorative + -ly (adverb suffix, from Old English -lice): the adjective of function shifts to an adverb of manner","meaning":"in a decorative manner","meaningCN":"以装饰的方式；就装饰而言"},{"word":"decorativeness","structure":"decorative + -ness (noun suffix, from Old English -nes): the adjective of function shifts to a noun naming the quality","meaning":"the quality of being decorative","meaningCN":"装饰性；作装饰之用的性质"}]}},{"word":"decoration","ipa_uk":"/ˌdekəˈreɪʃn/","ipa_us":"/ˌdekəˈreɪʃn/","definition_zh":"装饰；装饰品；装饰风格；装饰工艺；（建筑）装饰细部；勋章、奖章","definition_en":"the act of decorating; the result or state of being decorated; an ornament; a style or scheme of ornament; also a badge awarded as an honour","core_image":"一只木箱打开，里面一层层码着彩带、纸花和绸结，整个大厅正等着被这些零碎填满","scene":"婚礼前一天的大厅里堆满纸箱，桌上摊着彩带和剪好的纸花，The team finishes the decoration of the hall before the guests arrive.","sceneCN":"这里 decoration 指「装饰这一行为或工作」（第 1 个义项：装饰行为）；句意为团队在客人到达前完成大厅的装饰。图中可辨识物件：堆叠的纸箱、散开的彩带、剪好的纸花与尚未挂起的绸结。","pos":[{"tag":"n.","zh":"装饰；装饰品；勋章"}],"collocations":[{"phrase":"Christmas decoration","zh":"圣诞装饰"},{"phrase":"interior decoration","zh":"室内装饰"},{"phrase":"for decoration","zh":"供装饰之用"},{"phrase":"award a decoration","zh":"授予勋章"},{"phrase":"architectural decoration","zh":"建筑装饰"},{"phrase":"the decoration of a hall","zh":"大厅的装饰"}],"forms":[{"label":"复数","form":"decorations"}],"derivatives":[{"word":"decorative","pos":"adj.","zh":"装饰的；装饰性的"},{"word":"decorator","pos":"n.","zh":"装饰工；室内装饰师"}],"senses":[{"no":"01","title":"The act or process of decorating","titleCN":"装饰的行为或过程","definition":"the work of adding ornament to a place or object, considered as an activity","definitionCN":"作为一项活动来看的、为场所或物件添加装饰的工作","example":"The decoration of the hall took the whole afternoon.","exampleCN":"大厅的装饰工作花了整个下午。","why":"The noun of action comes first: Latin decoratio named the doing of the verb before it named anything produced.","whyCN":"先有动作名词：拉丁 decoratio 先指动词所表示的行为，之后才指所做出来的东西。"},{"no":"02","title":"The state of being decorated","titleCN":"被装饰后的状态或结果","definition":"the appearance or condition produced by ornament, considered as a whole","definitionCN":"由装饰造成的整体外观或状态","example":"The room is plain, and its only decoration is the light itself.","exampleCN":"房间很素净，唯一的装饰就是光本身。","why":"As a mass noun the word can name the total effect rather than a countable object, which is the bridge to its collective uses.","whyCN":"作不可数名词时，它指整体效果而非可数物件，这正是通向集合用法的桥梁。"},{"no":"03","title":"An ornament or decorative object","titleCN":"装饰品、装饰物件","definition":"a thing added to make a place or object look better, especially one of a set","definitionCN":"为使场所或物件更好看而添加的东西，尤指成套中的一件","example":"Paper chains and stars were the only decorations in the classroom.","exampleCN":"纸链和星星是教室里仅有的装饰品。","why":"Once the action is finished, its products become countable things, and the plural is the usual form for a set hung up for an occasion.","whyCN":"动作完成后，其产物变成可数的东西，复数形式常用于某一场合挂起的一整套。"},{"no":"04","title":"A style of ornament","titleCN":"装饰风格或装饰方案","definition":"the characteristic manner of ornament of a period, place or designer","definitionCN":"某一时期、地点或设计者特有的装饰方式","example":"The house is known for its restrained Victorian decoration.","exampleCN":"这座宅子以克制的维多利亚式装饰著称。","why":"A collection of choices made repeatedly becomes a style, so the word moves from things to a recognisable manner.","whyCN":"反复做出的整套选择会成为风格，于是这个词从物件转到可辨识的做法。"},{"no":"05","title":"The trade of decorating interiors","titleCN":"室内装饰行业","definition":"the profession of planning and furnishing the inside of buildings","definitionCN":"规划并陈设建筑内部的行业","example":"She trained in decoration before joining the furniture firm.","exampleCN":"她在加入家具公司之前受过室内装饰的训练。","why":"A repeatable activity with paid practitioners becomes a trade name, and the word is then used without an article.","whyCN":"可重复且有报酬从业者的活动会成为行业名称，此时这个词常不带冠词使用。"},{"no":"06","title":"Ornament built into a building","titleCN":"砌入建筑的装饰","definition":"ornamental work that forms part of a building's fabric, such as carving, moulding or tiling","definitionCN":"构成建筑本体一部分的装饰性做法，如雕刻、线脚或贴面砖","example":"The west front is covered in polychrome decoration.","exampleCN":"西立面满布彩色的装饰。","why":"Architecture uses the word for ornament that is part of the fabric, not applied afterwards, which is why it appears in technical descriptions.","whyCN":"建筑用这个词指属于本体的装饰，而非事后贴上去的，因此它常出现在技术描述中。"},{"no":"07","title":"An award worn as an honour","titleCN":"作为荣誉佩戴的勋章","definition":"a medal or badge given by a state or institution as a mark of honour","definitionCN":"由国家或机构授予、作为荣誉标志的奖章或徽章","example":"He was granted a decoration for service in the rescue.","exampleCN":"他因救援中的表现被授予一枚勋章。","why":"The sense comes from the older idea of honouring: an ornament on a uniform marks distinction, so the mark and the honour share one name.","whyCN":"这一义项出自较早的「致敬」之义：制服上的饰物标记身份，于是记号与荣誉共用一个名称。"},{"no":"08","title":"The ornamental layer of a design","titleCN":"设计中的装饰层面","definition":"in design, the visual elements of an interface that carry no information and serve only to please","definitionCN":"设计中界面里不承载信息、只为悦目的视觉元素","example":"The team removed every decoration from the screen and kept only the data.","exampleCN":"团队去掉了屏幕上所有装饰，只留下数据。","why":"Digital design repeats the oldest contrast, separating what informs from what merely pleases, and reuses the noun for the second.","whyCN":"数字设计重复了最古老的对照，把传达信息的与只取悦眼睛的分开，并把名词用于后者。"}],"etymology":{"intro":{"en":"Decoration comes from Latin decoratio, whose accusative decorationem reached English through French; it is the noun of action from decorare 'to decorate', built on decus 'beauty, honour'. It belongs to the dec- line and shares no root with ornare. Dates are approximate.","cn":"decoration 来自拉丁语 decoratio 的宾格 decorationem，经法语进入英语；它是动词 decorare「装饰」的动作名词，其基础为 decus「美、荣誉」。它出自 decus 与 decorare 这一条词源线，与 ornare 不同源。年代均为约数。"},"items":[{"era":"LATIN DECUS","en":"Decus named beauty, grace and honourable standing; a beautiful thing and an honoured person could share the word.","cn":"decus 指美、优雅与体面的地位；美的事物与受尊敬的人可以共用这个词。"},{"era":"LATIN DECORARE","en":"Decorare 'to adorn, honour' supplied the verb of action behind the noun.","cn":"decorare「装饰、致敬」提供了名词背后的动作动词。"},{"era":"LATIN DECORATIO","en":"The suffix -tio formed action nouns, so decoratio was the act of adorning and, by extension, what adorning produced.","cn":"拉丁动作后缀 -tio 构成动作名词，于是 decoratio 指装饰这一行为，进而指装饰所产生的东西。"},{"era":"OLD FRENCH DECORATION","en":"Old French passed the noun to English in the form decoration, keeping both the act and the result.","cn":"古法语以 decoration 的形式把这个名词传给英语，行为与结果两面都保留下来。"},{"era":"ENGLISH NOUN","en":"In English the word spread outward from the act to its products, to the manner of a period, and to the honorary badge worn on a uniform.","cn":"在英语里，这个词从行为向外扩展到产物、某一时期的手法，以及制服上佩戴的荣誉徽章。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of decus is not established, so any Indo-European root proposed for it is a reconstruction rather than a witnessed form.","cn":"来源不确定（更深词源）：decus 在拉丁语之前的来源并无定论，凡为其提出的印欧词根均属重构形式，而非实际书证。"}]},"similar":{"note":{"en":"The first group holds words close in form to decoration, two from the same family and one from another root; the second holds near synonyms that differ in whether they name a thing, an act, a detail or a whole system.","cn":"第一组是形式上接近本词的词，两个同族，一个来自别的词根；第二组是近义词，区别在于它们指物件、行为、细节还是一整套体系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decorative","ipa":"/ˈdekərətɪv/","tag":"same family, adjective","definition":"The adjective of function beside this noun; it describes what serves to decorate rather than the decoration itself.","definitionCN":"本词旁边的功能形容词；描述起装饰作用的事物，而非装饰本身。"},{"word":"decorator","ipa":"/ˈdekəreɪtə/","tag":"same family, worker","definition":"A person who decorates interiors; the agent suffix shifts the word from the work to the worker.","definitionCN":"装饰室内的人；施事后缀把词从工作转到从业者。"},{"word":"dedication","ipa":"/ˌdedɪˈkeɪʃn/","tag":"different root","definition":"The act of devoting oneself or a work to a purpose; from dedicare, not from decorare, though the endings match.","definitionCN":"把自己或作品献给某一目的的行为；来自 dedicare 而非 decorare，尽管词尾相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ornament","ipa":"/ˈɔːnəmənt/","tag":"other root line","definition":"An object added for beauty; the closest synonym in meaning but from the ornare family, which has no shared root with decorare.","definitionCN":"为美观而添加的物件；意义最近的同义词，但来自 ornare 一族，与 decorare 没有共同词根。"},{"word":"adornment","ipa":"/əˈdɔːnmənt/","tag":"act or thing","definition":"Adorning, or the thing added; it stresses the act of honouring and beautifying more than the finished scheme.","definitionCN":"装饰的行为或添加之物；比已成形的方案更强调使之美、致敬的动作。"},{"word":"embellishment","ipa":"/ɪmˈbelɪʃmənt/","tag":"added detail","definition":"A detail that enriches a whole, used of writing, music and design alike.","definitionCN":"使整体更丰富的细节，写作、音乐与设计都可用。"},{"word":"ornamentation","ipa":"/ˌɔːnəmenˈteɪʃn/","tag":"system, other root","definition":"Decoration treated as a system or a total effect; it comes from the ornare family and usually stays uncountable.","definitionCN":"被当作体系或整体效果来看的装饰；来自 ornare 一族，通常不可数。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"Decorare 'to adorn' plus a suffix for action or result gives the act of adorning and what it leaves behind.","cn":"decorare「装饰」加表示动作或结果的名词后缀 = 装饰的行为及其留下的东西。"},{"en":"The same noun ending also builds creation, formation and preparation, all of them names of processes.","cn":"同样的名词后缀还见于表示「创造」「形成」「准备」一类词，都是过程之名。"},{"en":"Decoration names the work and decorations name the things; one plural ending decides between mass and count.","cn":"装饰工作不可数，装饰物件可数；只差一个复数词尾，就分出整体与单件。"},{"en":"Museums put painting and decoration in different rooms, because one hangs on a wall and the other sits on it.","cn":"博物馆把绘画与装饰品分室陈列，因为一个挂在墙上，一个摆在其上。"},{"en":"A medal is called a decoration because it decorates a uniform with honour.","cn":"勋章被称作装饰，因为它以荣誉装点制服。"}],"abstract":[{"en":"Picture a room where every surface has been prepared before anyone arrives, so the preparation itself is what guests see.","cn":"想象一个房间，在客人到达之前每个表面都已被布置好，于是布置本身成了客人看到的东西。"},{"en":"Picture a stranger reading a street by its balconies and window frames and guessing the century.","cn":"想象一个外来者凭阳台与窗框读一条街，猜出它的年代。"},{"en":"Picture a uniform where one small ribbon says more than the whole cloth.","cn":"想象一套制服，小小一条绶带比整块布料说得更多。"}]},"examples":[{"en":"The decoration of the church took three winters of careful work.","cn":"这座教堂的装饰工作花了三个冬天的心力。"},{"en":"She keeps the paper decorations in a flat box under the bed.","cn":"她把纸装饰品收在床底一只扁箱里。"},{"en":"The general wore a single decoration on his collar.","cn":"将军领口上只戴了一枚勋章。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「得可装饰」——念起来像「拿来就可以装饰」：一堆彩带纸花，正好把大厅布置起来。拉丁 decorare 是「装饰」，加表示动作或结果的名词后缀，就成了「装饰」这件事与它的成果。","word":"decoration"},"root":"拉丁 decus「美、荣誉」构成动词 decorare「装饰」，其动作名词 decoratio 的宾格 decorationem 经古法语进入英语，指装饰的行为、结果、装饰品、装饰风格与勋章。此线出自 decus 与 decorare，与 ornare、ornamentum 不同源；decus 在拉丁语之前的来源不确定，相关印欧词根属重构形式。","sensesIntro":{"en":"Eight senses begin with the act of decorating, then the state it produces, the countable objects, a style, the trade of interiors, ornament built into a building, an honorary badge and finally the ornamental layer of an interface.","cn":"八个义项从装饰的行为开始，继而指它造成的状态、可数的装饰品、某种风格、室内装饰行业、砌入建筑的装饰、荣誉勋章，最后是界面上的装饰层面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a room filling with paper flowers and ribbon until every surface reads as prepared for an occasion.","cn":"核心意象：纸花与彩带不断填进房间，直到每个表面都显出「为某个场合做好了准备」的样子。"},"chain":["ACT OF ADORNING","ADORNED RESULT","ORNAMENT AS OBJECT","STYLE AND TRADE","BUILT ORNAMENT","MARKS ON THE SURFACE"],"branches":[{"senses":"01","en":"THE ACT: the word starts as the work itself, the hours spent adding beauty to a place.","cn":"行为：这个词起初指工作本身，即为一个场所添加美观所花的时间。"},{"senses":"02 · 03","en":"RESULT AND OBJECT: the finished look is one sense, and the countable things that produce it are another.","cn":"结果与物件：完成后的观感是一个义项，产生这一观感的可数物件是另一个义项。"},{"senses":"04 · 05","en":"STYLE AND TRADE: repeated choices harden into a manner, and that manner becomes a paid profession.","cn":"风格与行业：反复的选择固化为一种手法，而这种手法又成为有报酬的职业。"},{"senses":"06","en":"BUILT FABRIC: in architecture the word names ornament that belongs to the building's own body.","cn":"建筑本体：在建筑中，这个词指属于建筑自身躯体的装饰。"},{"senses":"07 · 08","en":"MARKS ADDED ON TOP: the badge on a uniform and the pleasing layer on a screen both sit on the surface and carry no load.","cn":"覆在表面的记号：制服上的徽章与屏幕上的悦目图层，都覆在表面而不承重。"}]},"affixes":{"intro":{"en":"Decoration is built from a Latin noun, a Latin verb, one Latin suffix and a short English chain of derived words, so it can be read piece by piece.","cn":"decoration 由一个拉丁名词、一个拉丁动词、一个拉丁后缀和一段简短的英语派生链构成，可以逐块读出。"},"latinIntro":{"en":"Latin decus 'beauty, honour' gives decor and decorare; the action suffix -tio builds decoratio, and English added -or and -ive to name the worker and the function.","cn":"拉丁 decus「美、荣誉」衍生出 decor 与 decorare；拉丁动作后缀 -tio 构成 decoratio，英语又加表示施事与功能的后缀来指从业者与功能。"},"items":[{"word":"decus","structure":"decus, decoris (Latin noun, third declension, neuter)","meaning":"beauty, grace, honour","meaningCN":"美；优雅；荣誉","example":"The noun supplies both the beauty and the honour behind the word.","exampleCN":"这个名词同时提供这个词背后的美与荣誉。"},{"word":"decor","structure":"decor, decoris (Latin noun, third declension, masculine)","meaning":"beauty, comeliness","meaningCN":"美；秀美","example":"A related noun kept the plain idea of visible beauty.","exampleCN":"一个同族名词保留了「可见之美」的朴素含义。"},{"word":"decorare","structure":"decus stem + -are (Latin verb, first conjugation)","meaning":"to adorn, honour, make beautiful","meaningCN":"装饰；使之美；致敬","example":"The verb supplies the action that the noun will name.","exampleCN":"这个动词提供了名词将要命名的动作。"},{"word":"-tio","structure":"-tio, -tionis (Latin action-noun suffix)","meaning":"the act or result of an action","meaningCN":"动作或动作的结果","example":"The suffix turns a verb of adorning into a noun of adorning.","exampleCN":"这个后缀把表装饰的动词变成表装饰的名词。"},{"word":"decoratio","structure":"decorare + -tio (Latin noun)","meaning":"a decorating, adornment","meaningCN":"装饰；装饰物","example":"The Latin noun named the act first and its product second.","exampleCN":"这个拉丁名词先指行为，再指产物。"},{"word":"decoration","structure":"decorationem, through French","meaning":"the act of decorating; an ornament","meaningCN":"装饰行为；装饰品","example":"English took the noun with both senses intact.","exampleCN":"英语接受这个名词时，两个义项都完好保留。"},{"word":"-or","structure":"-or (agent suffix, from Latin -or)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix marks the person who carries out the work.","exampleCN":"这个后缀标记执行这项工作的人。"},{"word":"decorator","structure":"decorate + -or","meaning":"a person who decorates","meaningCN":"装饰者；室内装饰师","example":"The worker is named after the act, not after the result.","exampleCN":"这一从业者按动作命名，而非按结果命名。"}],"latinEntries":[{"word":"decus","structure":"decus, decoris (n., third declension)","meaning":"beauty, honour","meaningCN":"美；荣誉"},{"word":"decor","structure":"decor, decoris (m., third declension)","meaning":"beauty, comeliness","meaningCN":"美；秀美"},{"word":"decorare","structure":"decorare, decoratus (verb, first conjugation)","meaning":"to adorn, honour","meaningCN":"装饰；致敬"},{"word":"decoratio","structure":"decoratio, decorationis (n., third declension)","meaning":"a decorating, adornment","meaningCN":"装饰；装饰物"}],"derivatives":[{"word":"decorative","structure":"decoration, reshaped on the verb decorate + -ive (adjective suffix, from Latin -ivus): the noun of an act shifts to an adjective of function","meaning":"serving to decorate","meaningCN":"起装饰作用的"},{"word":"decorator","structure":"decorate + -or (agent suffix, from Latin -or): the noun of an act shifts to the person who performs it","meaning":"a person who decorates interiors","meaningCN":"装饰室内的人"}]}},{"word":"ornamentation","ipa_uk":"/ˌɔːnəmenˈteɪʃn/","ipa_us":"/ˌɔːrnəmenˈteɪʃn/","definition_zh":"装饰；装饰品；装饰纹样；（音乐）装饰音","definition_en":"the act or result of decorating something, or the decoration so added, including added notes in music","core_image":"一整面穹顶被金箔与刻纹铺满，抬头看时，屋顶不再是结构，而是一件穿戴整齐的华服","scene":"教堂穹顶下的工匠停下手中的刻刀，抬头端详刚完成的纹样，The ornamentation on the ceiling took three winters to finish.","sceneCN":"这里 ornamentation 指「被添加在建筑上的整片装饰」（第 2 个义项：装饰物整体）；句意为穹顶上的装饰纹样花了三个冬天才完成。图中可辨识物件：穹顶、刻刀、脚手架与金箔纹样。","pos":[{"tag":"n.","zh":"装饰；装饰品；（音乐）装饰音"}],"collocations":[{"phrase":"ornamentation of a building","zh":"建筑的装饰"},{"phrase":"rich ornamentation","zh":"繁复的装饰"},{"phrase":"musical ornamentation","zh":"音乐装饰音"},{"phrase":"surface ornamentation","zh":"表面装饰纹样"},{"phrase":"architectural ornamentation","zh":"建筑装饰细部"},{"phrase":"excess of ornamentation","zh":"过度装饰"}],"forms":[{"label":"复数","form":"ornamentations"}],"derivatives":[{"word":"ornamental","pos":"adj.","zh":"装饰性的；装饰用的"},{"word":"ornate","pos":"adj.","zh":"装饰华美的；辞藻华丽的"}],"senses":[{"no":"01","title":"The act of decorating","titleCN":"装饰的行为；加以纹饰的过程","definition":"the act or process of adding decoration to an object, a building or a surface","definitionCN":"为物件、建筑或表面添加装饰的行为或过程","example":"The ornamentation of the chapel ceiling went on for twenty years.","exampleCN":"小教堂穹顶的装饰工程持续了二十年。","why":"The Latin suffix -atio formed nouns of action, so ornamentation first names the doing of the work rather than the things produced.","whyCN":"拉丁后缀 -atio 构成表示动作的名词，因此 ornamentation 首先指「做装饰这件事」，而不是做出来的东西。"},{"no":"02","title":"Decoration considered as a whole","titleCN":"装饰物的整体；成套装饰","definition":"the decorations that have been added, taken together as one body of work","definitionCN":"已经添加的装饰，作为一个整体来看","example":"The gate's iron ornamentation is picked out in gold leaf.","exampleCN":"大门的铁艺装饰用金箔勾出轮廓。","why":"Action nouns in English routinely shift to the result of the action, so the word can name the finished decoration rather than the labour.","whyCN":"英语中的动作名词常从动作转向结果，所以这个词可以指完成的装饰，而非付出的劳动。"},{"no":"03","title":"Applied detail on a building","titleCN":"建筑上的附加装饰细部","definition":"the carved, moulded or painted detail applied to a structure, as distinct from its supporting form","definitionCN":"附加在建筑上的雕刻、线脚或彩绘细部，与承重结构相区别","example":"Dentils and rosettes make up the ornamentation of the cornice.","exampleCN":"齿饰与圆花饰构成了檐口的装饰。","why":"Architecture separates what holds a building up from what dresses it, and ornamentation names the second category.","whyCN":"建筑学把承重与装扮分开，ornamentation 指的正是后一类。"},{"no":"04","title":"Added notes in music","titleCN":"音乐中的装饰音","definition":"a note, trill or run added to a melody to decorate it without changing its main line","definitionCN":"为使旋律更华美而添加的音、颤音或走句，不改变旋律主线","example":"Her ornamentation never blurred the shape of the tune.","exampleCN":"她加的装饰音从未模糊旋律的轮廓。","why":"Music borrowed the visual logic of added decoration: the extra notes sit on the melody as carving sits on a wall.","whyCN":"音乐借用了附加装饰的视觉逻辑：多出来的音覆在旋律上，正如雕饰覆在墙上。"},{"no":"05","title":"Painted decoration in a manuscript","titleCN":"手抄本上的彩绘装饰","definition":"the painted or gilded decoration placed around the text of a handwritten book","definitionCN":"手抄本书籍文字周围绘上或贴金的装饰","example":"The psalter's margins carry dense ornamentation in blue and gold.","exampleCN":"这本诗篇的页边布满蓝金两色的繁密装饰。","why":"Gold leaf and colour were laid around the writing rather than in it, the same added-surface pattern as on a wall.","whyCN":"金箔与颜料铺在文字周围而非文字之内，与墙面装饰同属附加表面的模式。"},{"no":"06","title":"Density of decoration as a style","titleCN":"作为风格的装饰繁简程度","definition":"the amount or density of decoration in a design, judged as a matter of taste or period","definitionCN":"设计中装饰的数量或密度，作为品味或时代风格的判断依据","example":"The ornamentation of the later facade is far heavier than that of the nave.","exampleCN":"后期立面的装饰远比中殿繁重。","why":"Once the noun can mean the total decoration, it can be measured, and a measurement of decoration turns into a description of style.","whyCN":"当这个词能指装饰的总量，它就可以被计量，而装饰的计量便转化为对风格的描述。"},{"no":"07","title":"Display structures in animals","titleCN":"动物用于展示的装饰性结构","definition":"in biology, a structure such as plumage, a crest or antlers whose main function is display","definitionCN":"生物学中，以展示为主要功能的羽毛、冠饰或鹿角等结构","example":"The male's ornamentation includes a tail longer than its body.","exampleCN":"这只雄鸟的装饰性结构包括一条比身体更长的尾羽。","why":"Biology extends the word to parts that an animal wears for show, keeping the idea of decoration while dropping the idea of craft.","whyCN":"生物学把这个词扩展到动物为展示而穿戴的部位，保留了装饰观念，去掉了人工制作。"},{"no":"08","title":"Decorative language","titleCN":"语言上的修饰；辞藻","definition":"the adding of ornamental words, images or detail to speech or writing","definitionCN":"在言语或写作中添加华美词语、意象或细节","example":"Reviewers admired the essay's ornamentation but doubted its argument.","exampleCN":"评论者欣赏这篇文章的辞藻，却对其论证表示怀疑。","why":"The transfer is from a decorated surface to a decorated sentence: both carry something added for beauty rather than for structure.","whyCN":"转移发生在被装饰的表面与被装饰的句子之间：两者都带有为美感而非为结构添加的成分。"}],"etymology":{"intro":{"en":"Ornamentation is English ornament plus the Latin noun suffix -atio, which reached English through French -ation. Ornament itself goes back to Latin ornare 'to adorn'. Dates are approximate.","cn":"ornamentation 是英语 ornament 加上拉丁名词后缀 -atio，该后缀经法语 -ation 进入英语。ornament 本身可追溯到拉丁 ornare「装饰」。年代均为约数。"},"items":[{"era":"LATIN ORNARE","en":"Ornare meant 'to equip, fit out, adorn'. It covered both supplying gear and making something handsome, and English inherited the decorative side. Source uncertain: the deeper origin of ornare is not established, so any root proposed for it is a reconstruction rather than a witnessed form.","cn":"ornare 意为「配备、装备、装饰」，既指供给器物，也指使某物美观，英语继承的是装饰的一面。来源不确定：ornare 更深的来源并无定论，凡为其提出的词根均属重构形式，而非实际书证。"},{"era":"LATIN ORNAMENTUM","en":"Ornamentum, formed from ornare, named what was supplied: equipment, dress, and by extension decoration.","cn":"ornamentum 由 ornare 构成，指被配备的东西：装备、衣饰，进而指装饰。"},{"era":"LATIN -ATIO","en":"The suffix -atio, genitive -ationis, turned verbs into nouns of action and named a process rather than a thing.","cn":"后缀 -atio（属格 -ationis）把动词变为动作名词，命名的是过程而不是物件。"},{"era":"FRENCH -ATION","en":"French carried the same suffix in the form -ation, and it was this French-shaped ending that English later took over.","cn":"法语以 -ation 的形式承继了同一后缀，英语后来接收的正是这个法语形态的词尾。"},{"era":"ENGLISH ORNAMENT","en":"English borrowed ornament in the fifteenth century for an adornment and for the act of adorning.","cn":"英语在十五世纪借入 ornament，既指装饰物，也指装饰这一行为。"},{"era":"ENGLISH ORNAMENTATION","en":"Ornament plus -ation produced ornamentation, first for the process and then for the finished decoration; the musical sense joined the word in the nineteenth century.","cn":"ornament 加 -ation 构成 ornamentation，先指过程，再指完成的装饰；音乐义在十九世纪并入这个词。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close to ornamentation but come from other roots or other parts of the same family; the second holds words for decoration that differ in scope or medium.","cn":"第一组是与 ornamentation 形近或音近、但词根不同或同族不同词性的词；第二组是表示装饰的词，在范围或媒介上有别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ornament","ipa":"/ˈɔːnəmənt/","tag":"base word","definition":"The shorter noun and verb from which ornamentation is built; it names one piece of decoration rather than the whole scheme.","definitionCN":"构成 ornamentation 的较短名词与动词，指单件装饰而非整套装饰方案。"},{"word":"orientation","ipa":"/ˌɔːriənˈteɪʃn/","tag":"different root","definition":"The act of finding or setting a direction; it comes from Latin oriri 'to rise', not from ornare.","definitionCN":"确定或调整方向的行为；来自拉丁 oriri「升起」，与 ornare 无关。"},{"word":"ornate","ipa":"/ɔːˈneɪt/","tag":"same family, adjective","definition":"Richly decorated; it describes the style of an object, while ornamentation names the decoration itself.","definitionCN":"装饰华美的；描述物体的风格，而 ornamentation 指装饰本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decoration","ipa":"/ˌdekəˈreɪʃn/","tag":"broader, plainer","definition":"The general word for adorning anything, from a room to a cake; it carries no suggestion of a designed scheme.","definitionCN":"为任何事物增添美观的通用词，从房间到蛋糕皆可，不暗示成套设计。"},{"word":"embellishment","ipa":"/emˈbelɪʃmənt/","tag":"added detail","definition":"An added detail that improves a story, a design or a surface; it often implies something extra rather than structural.","definitionCN":"为故事、设计或表面增色的附加细节，常暗示额外而非结构性的成分。"},{"word":"adornment","ipa":"/əˈdɔːnmənt/","tag":"worn or applied","definition":"Decoration attached to a person or object, often jewellery or dress; it keeps the sense of something put on.","definitionCN":"附着于人或物的装饰，常指首饰或衣饰，保留「穿戴上去」的含义。"},{"word":"flourish","ipa":"/ˈflaʊrɪʃ/","tag":"music and writing","definition":"A showy added stroke, note or phrase; it is the single decorative gesture where ornamentation is the whole body of them.","definitionCN":"花哨的附加笔画、音符或语句；它是一个装饰动作，而 ornamentation 指全部装饰的总和。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the contexts in which the word actually appears.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际出现的语境。"},"normal":[{"en":"Ornare 'to equip' plus -ation 'process' gives the fitting out of a surface with beauty.","cn":"ornare「配备」加表示过程的名词词尾，就是给表面配上一套美观。"},{"en":"Explanation, decoration and celebration share the same -ation ending, all names of processes.","cn":"「解释」「装饰」「庆祝」等词共享同一个表示过程的名词词尾。"},{"en":"Ornamentation is what a building puts on, not what holds it up.","cn":"ornamentation 是建筑穿上的东西，不是撑起它的东西。"},{"en":"In music the added notes are ornaments, so the word crosses from stone to sound.","cn":"音乐里附加的音就是装饰，这个词因此从石头跨到声音。"},{"en":"A page of gold leaf around the text is ornamentation in the strict sense.","cn":"文字周围的一页金箔，正是严格意义上的装饰。"}],"abstract":[{"en":"Picture a ceiling so covered in gold that the structure below it can only be guessed.","cn":"想象一片被金箔盖满的穹顶，下面的结构只能靠猜。"},{"en":"Picture a melody wearing jewellery it did not need but could not lose.","cn":"想象一段旋律戴着并不需要、却又摘不掉的珠宝。"},{"en":"Picture a building dressed for a festival that never ended.","cn":"想象一座为永不完结的节日盛装打扮的建筑。"}]},"examples":[{"en":"The restoration removed four layers of later ornamentation from the doorway.","cn":"修复工作清除了门廊上后来添上的四层装饰。"},{"en":"Critics complained that the ornamentation of the new hall overwhelmed its proportions.","cn":"评论者抱怨新大厅的装饰压倒了它的比例。"},{"en":"The composer wrote his own ornamentation for the slow movement.","cn":"作曲家为慢乐章写了自己的装饰音。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"把 ornament 听成「哦，那门」——门前挂满花环彩带，一看就是装饰；再加 -ation，就成了「装饰这件事，或这一整套装饰」。ornare 本义是「配备」，装饰就是给表面配上一套行头。","word":"ornamentation"},"root":"拉丁 ornare「配备、装饰」衍生名词 ornamentum「装备、装饰」，英语借入为 ornament；再加拉丁动作名词后缀 -atio（经法语 -ation），构成 ornamentation，指装饰的过程与结果。ornare 的更深来源无定论，相关词根属重构形式。","sensesIntro":{"en":"Eight senses start from the act of decorating, move to the decoration as a body, then to architectural detail, added musical notes, manuscript painting, density of style, animal display structures and finally decorative language.","cn":"八个义项从装饰这一行为出发，转到作为整体的装饰物，再到建筑细部、音乐附加音、手抄本彩绘、装饰繁简程度、动物展示结构，最后是语言上的修饰。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surface already complete in function that is then covered with something added purely for beauty.","cn":"核心意象：一个功能上已经完整的表面，又被覆上一层纯粹为美观而添加的东西。"},"chain":["DECORATIVE ACT","ADDED SURFACE DETAIL","ARCHITECTURAL DETAIL","SOUND EMBELLISHMENT","EXCESS OF DETAIL","RHETORICAL EMBELLISHMENT"],"branches":[{"senses":"01","en":"THE ACT ITSELF: the suffix names a process, so the word begins as the work of decorating rather than as any object.","cn":"行为本身：后缀命名的是过程，所以这个词起初指装饰这项工作，而不是任何物件。"},{"senses":"02 · 03","en":"THE DECORATION AS A BODY: once finished, the added material can be seen as one scheme, first in general and then as the applied detail of a building.","cn":"作为整体的装饰：完成之后，添加的材料可以看作一套方案，先是一般装饰，再是建筑上的附加细部。"},{"senses":"04 · 05","en":"DECORATION IN OTHER MEDIA: the same added layer appears as extra notes on a melody and as paint and gold around the text of a book.","cn":"其他媒介中的装饰：同一层附加物出现在旋律上的额外音符，也出现在书页文字周围的颜料与金箔。"},{"senses":"06 · 07","en":"MEASURE AND DISPLAY: decoration can be counted as a style, and living things can wear structures whose only work is display.","cn":"计量与展示：装饰可以被计量为一种风格，生物也可以穿戴只用于展示的结构。"},{"senses":"08","en":"FROM SURFACE TO SENTENCE: the last step moves the idea from a decorated object to decorated speech, where words are added for beauty.","cn":"从表面到句子：最后一步把观念从被装饰的物件移到被装饰的言语，那里添加的是为美感而设的词。"}]},"affixes":{"intro":{"en":"Ornamentation can be read as a base noun, a Latin verb behind it, and a suffix that names a process.","cn":"ornamentation 可以读作一个基础名词、其背后的拉丁动词，以及一个命名过程的后缀。"},"latinIntro":{"en":"Latin ornare 'to adorn' gives the noun ornamentum; the action suffix -atio, reshaped in French as -ation, lets English build ornamentation on the borrowed noun.","cn":"拉丁 ornare「装饰」衍生名词 ornamentum；动作后缀 -atio 在法语中变形为 -ation，使英语能在借入的名词上构成 ornamentation。"},"items":[{"word":"ornare","structure":"ornare, orno, ornavi (Latin verb, first conjugation)","meaning":"to equip, fit out, adorn","meaningCN":"配备；装备；装饰","example":"The verb supplies the core meaning of making something handsomely furnished.","exampleCN":"这个动词提供了「使某物装点齐备」的核心含义。"},{"word":"-mentum","structure":"-mentum (Latin noun suffix)","meaning":"means or result of an action","meaningCN":"动作的手段或结果","example":"The suffix turns the act of adorning into the thing that is supplied.","exampleCN":"这个后缀把装饰的动作转为被配备出来的东西。"},{"word":"ornamentum","structure":"ornare + -mentum (Latin noun)","meaning":"equipment, dress, decoration","meaningCN":"装备；衣饰；装饰","example":"Latin used the noun for gear as well as for finery.","exampleCN":"拉丁语用这个名词既指装备，也指华饰。"},{"word":"-atio","structure":"-atio, -ationis (Latin noun-of-action suffix)","meaning":"the act or process of doing","meaningCN":"做某事的行为或过程","example":"The suffix names a process rather than a single object.","exampleCN":"这个后缀命名的是过程，而不是单个物件。"},{"word":"-ation","structure":"-ation (French form of Latin -atio)","meaning":"action, process, or its result","meaningCN":"动作、过程或其结果","example":"French reshaped the ending before English borrowed it.","exampleCN":"法语先改造了这个词尾，英语随后借入。"},{"word":"ornament","structure":"ornamentum, through French (English noun and verb)","meaning":"an adornment; to adorn","meaningCN":"装饰物；装饰","example":"English uses the short form for a single piece of decoration.","exampleCN":"英语用这个短形式指单件装饰。"},{"word":"ornamentation","structure":"ornament + -ation","meaning":"the act or body of decoration","meaningCN":"装饰的行为或装饰整体","example":"The long form names a whole scheme rather than one item.","exampleCN":"长形式指整套装饰，而非一件物品。"},{"word":"-al","structure":"-alis (Latin adjective suffix, through French -al)","meaning":"pertaining to","meaningCN":"与……有关的","example":"The suffix forms the adjective that describes decorated things.","exampleCN":"这个后缀构成描述装饰之物的形容词。"}],"latinEntries":[{"word":"ornare","structure":"ornare, orno, ornavi (v., first conjugation)","meaning":"to equip, adorn","meaningCN":"配备；装饰"},{"word":"ornamentum","structure":"ornamentum, ornamenti (n., second declension)","meaning":"equipment, decoration","meaningCN":"装备；装饰"},{"word":"ornatus","structure":"ornatus, ornata, ornatum (adj.)","meaning":"furnished, adorned","meaningCN":"装备好的；装饰过的"}],"derivatives":[{"word":"ornamental","structure":"ornament + -al (from Latin -alis, through French)","meaning":"serving as decoration rather than structure","meaningCN":"作装饰之用而非承重的"},{"word":"ornately","structure":"ornate + -ly (English adverb suffix from adjective ornate, Latin ornatus)","meaning":"in a richly decorated manner","meaningCN":"以装饰华丽的方式"}]}},{"word":"sculptor","ipa_uk":"/ˈskʌlptə(r)/","ipa_us":"/ˈskʌlptə(r)/","definition_zh":"雕塑家；雕刻家；塑造者","definition_en":"a person who makes sculpture, whether by carving, modelling or casting","core_image":"一块巨石立在工坊中央，人绕着它走，手上全是石粉，像在与石头对话","scene":"采石场的粉尘落在围裙上，一位工匠把凿子抵住石面，The sculptor worked the block from every side before shaping a face.","sceneCN":"这里 sculptor 指「以雕刻方式创作雕塑的人」（第 1 个义项：石雕者）；句意为那位雕塑家从各个方向处理石块，然后才雕出面孔。图中可辨识物件：石块、凿子、木槌、围裙上的石粉与转台。","pos":[{"tag":"n.","zh":"雕塑家；雕刻家"}],"collocations":[{"phrase":"marble sculptor","zh":"大理石雕塑家"},{"phrase":"bronze sculptor","zh":"青铜雕塑家"},{"phrase":"court sculptor","zh":"宫廷雕塑家"},{"phrase":"work as a sculptor","zh":"以雕塑为业"},{"phrase":"commission a sculptor","zh":"委托雕塑家创作"},{"phrase":"the sculptor of a monument","zh":"某座纪念碑的雕塑者"}],"forms":[{"label":"复数","form":"sculptors"}],"derivatives":[{"word":"sculpture","pos":"n.","zh":"雕塑；雕塑作品"},{"word":"sculptural","pos":"adj.","zh":"雕塑的；雕塑般的"}],"senses":[{"no":"01","title":"A carver of stone","titleCN":"以石材雕刻的人","definition":"a person who cuts or carves stone into a form","definitionCN":"把石材切凿成形体的人","example":"The sculptor spent a year removing surplus marble from the block.","exampleCN":"这位雕塑家花了一年时间，把多余的大理石从石块上凿去。","why":"Latin sculptor was an agent noun from sculpere 'to carve', so the word first points to cutting rather than to modelling.","whyCN":"拉丁 sculptor 是由 sculpere「雕刻」构成的施动名词，所以这个词最初指向切凿，而不是塑形。"},{"no":"02","title":"A modeller in clay or wax","titleCN":"以黏土或蜡塑形的人","definition":"a person who builds up forms in a soft material instead of cutting them away","definitionCN":"以软质材料层层堆加形体、而非削减材料的人","example":"Working as a sculptor in clay, she built the figure up in coils.","exampleCN":"她以黏土雕塑为业，用泥条把人物一圈圈堆起来。","why":"The craft widened from carving to adding material, and the agent noun followed the maker rather than the method.","whyCN":"这门手艺从削减材料扩展到堆加材料，施动名词跟随的是制作者，而不是方法。"},{"no":"03","title":"One who casts in bronze","titleCN":"以青铜铸造作品的人","definition":"a person who makes sculpture by casting molten metal in a mould","definitionCN":"把熔化的金属浇入模具以制作雕塑的人","example":"The sculptor prepared a wax model before the foundry cast it in bronze.","exampleCN":"雕塑家先做好蜡模，再由铸造工坊浇铸成青铜。","why":"Casting is a separate workshop stage, yet the finished figure is still credited to the sculptor who designed it.","whyCN":"浇铸是另一个工坊环节，但完成的雕像仍归功于设计它的雕塑家。"},{"no":"04","title":"A professional working on commission","titleCN":"接受委托的职业雕塑者","definition":"a sculptor who makes work to order for a public body, a church or a collector","definitionCN":"为公共机构、教堂或收藏者按订单创作的雕塑家","example":"The cathedral commissioned a sculptor from Florence for the tomb.","exampleCN":"主教座堂为这座陵墓委托了一位佛罗伦萨雕塑家。","why":"Once patrons paid for work in advance, the word named a recognised profession rather than any skilled carver.","whyCN":"当委托人预先付费，这个词便指一种被认可的职业，而不是任何熟练的凿石者。"},{"no":"05","title":"An artist ranked beside painters","titleCN":"与画家并列的造型艺术家","definition":"a maker of three-dimensional art recognised as one of the fine arts","definitionCN":"被承认属于美术门类的三维艺术创作者","example":"The exhibition pairs each painter with a sculptor of the same decade.","exampleCN":"展览为每位画家配一位同年代的雕塑家。","why":"In the academy system sculpture took its place beside painting, and the person practising it needed a title of equal standing.","whyCN":"在学院体系中，雕塑与绘画并列，从事雕塑的人也需要一个地位相当的头衔。"},{"no":"06","title":"A figure identified with a period or school","titleCN":"代表某一时期或流派的雕塑者","definition":"a sculptor whose manner defines a style, usually named with a period","definitionCN":"手法足以界定一种风格、常与时期连称的雕塑家","example":"Scholars describe the doorway as the work of a Romanesque sculptor.","exampleCN":"学者把这个门廊描述为一位罗曼式雕塑家的作品。","why":"Style history groups anonymous makers under schools, so the word attaches to periods as well as to named individuals.","whyCN":"风格史把佚名制作者归入流派，因此这个词既系于个人，也系于时期。"},{"no":"07","title":"The maker of one named work","titleCN":"某件具体作品的创作者","definition":"the particular person credited with a single monument or figure","definitionCN":"被记在某座纪念碑或某尊造像名下的具体个人","example":"The plaque names the sculptor of the fountain but not its engineer.","exampleCN":"铭牌写着喷泉的雕塑者，却没有写工程师。","why":"Attribution turns a general role into a credit line, so the word can point to one person behind one object.","whyCN":"归属把一般身份变成一行署名，因此这个词可以指一件作品背后的那个人。"},{"no":"08","title":"One who shapes something abstract","titleCN":"比喻义：塑造抽象之物的力量","definition":"figuratively, a person or force that gives form to something without carving it","definitionCN":"比喻用法：不靠雕刻而赋予某物形体的个人或力量","example":"Time is the sculptor of coastlines, wearing cliffs into arches.","exampleCN":"时间是海岸线的雕塑家，把悬崖磨成拱门。","why":"The metaphor keeps only the shaping and drops the chisel, so anything that gives form can be called its sculptor.","whyCN":"这个比喻只保留塑形，丢掉了凿子，因此凡是赋予形体者都可称为它的雕塑家。"}],"etymology":{"intro":{"en":"Sculptor comes directly from Latin sculptor, an agent noun built on sculpere 'to carve'. Dates are approximate.","cn":"sculptor 直接来自拉丁 sculptor，它是由 sculpere「雕刻」构成的施动名词。年代均为约数。"},"items":[{"era":"LATIN SCULPERE","en":"Sculpere meant 'to carve, cut, chisel'. Source uncertain: its deeper origin is not established, so any root proposed for it is a reconstruction rather than a witnessed form.","cn":"sculpere 意为「雕刻、切凿、镌刻」。来源不确定：其更深的来源并无定论，凡为其提出的词根均属重构形式，而非实际书证。"},{"era":"LATIN SCULPTOR","en":"The agent suffix -or, added to the stem sculpt-, produced sculptor, 'the one who carves'.","cn":"施动后缀 -or 加在词干 sculpt- 上，构成 sculptor，即「雕刻的人」。"},{"era":"LATIN SCULPTURA","en":"Sculptura named both the act of carving and the carved object, and it became the parent of English sculpture.","cn":"sculptura 既指雕刻的行为，也指雕成的物件，后来成为英语「雕塑」一词的来源。"},{"era":"ENGLISH BORROWING","en":"English took sculptor from Latin in the sixteenth century, at the same time as sculpture, as a learned term for the art.","cn":"英语在十六世纪从拉丁语借入 sculptor，与表示「雕塑」的名词同时进入，作为这门艺术的学术用语。"},{"era":"REPLACING CARVER","en":"Older English said carver for the worker; sculptor entered as the dignified word for the same trade and slowly displaced it in art contexts.","cn":"较早的英语用「雕刻匠」指这名工匠；sculptor 作为同一行当的正式称谓进入，并逐渐在艺术语境中取代了前者。"},{"era":"MODERN PROFESSION","en":"From the eighteenth century the word settled as the standard title for a maker of sculpture, and later art history extended it to anonymous makers of a period.","cn":"自十八世纪起，这个词固定为雕塑制作者的标准称谓，后来艺术史又把它扩展到某一时期的佚名制作者。"}]},"similar":{"note":{"en":"The first group holds forms of the same word family that are often confused with sculptor; the second holds words for people who make three-dimensional work by different methods.","cn":"第一组是常与 sculptor 混淆的同族词形；第二组是按不同方法制作三维作品的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sculpture","ipa":"/ˈskʌlptʃə(r)/","tag":"same family, noun","definition":"The art or the object produced; sculptor is the person, sculpture is the thing or the activity.","definitionCN":"指这门艺术或雕成的物件；sculptor 是人，sculpture 是物或活动。"},{"word":"sculptural","ipa":"/ˈskʌlptʃərəl/","tag":"same family, adjective","definition":"Having the qualities of sculpture, especially solid form and modelled surfaces.","definitionCN":"具有雕塑特质的，尤其指坚实的形体与塑出的表面。"},{"word":"sculpt","ipa":"/ˈskʌlpt/","tag":"same family, verb","definition":"To make by carving or shaping, a verb formed from sculpture in English.","definitionCN":"通过雕刻或塑形来制作，是英语中由 sculpture 逆构出的动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carver","ipa":"/ˈkɑːvə(r)/","tag":"cutting method","definition":"One who cuts wood, stone or ivory; the word stresses the knife or chisel rather than the finished art.","definitionCN":"切凿木材、石材或象牙的人；强调刀凿，而非完成的艺术品。"},{"word":"modeller","ipa":"/ˈmɒdələ(r)/","tag":"additive method","definition":"One who shapes soft material such as clay or wax into a form, building up rather than cutting away.","definitionCN":"把黏土或蜡等软质材料塑成形体的人，以堆加而非削减方式工作。"},{"word":"founder","ipa":"/ˈfaʊndə(r)/","tag":"casting method","definition":"One who melts and casts metal in a mould; the founder executes what the sculptor designed.","definitionCN":"熔化金属并浇入模具的人；铸造者实现雕塑家的设计。"},{"word":"artist","ipa":"/ˈɑːtɪst/","tag":"broader term","definition":"A maker of art in any medium; sculptor is the narrower title for one working in three dimensions.","definitionCN":"以任何媒介创作艺术的人；sculptor 是专指三维创作者的较窄称谓。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, the real suffix and the actual workshop stages behind the word.","cn":"正常联想：真实的拉丁词干、真实的后缀，以及这个词背后真实的工坊环节。"},"normal":[{"en":"Sculpere 'to carve' plus -or 'one who' gives the carver, the person behind the chisel.","cn":"sculpere「雕刻」加 -or「做……的人」，就是拿凿子的人。"},{"en":"Actor, doctor and sculptor all end in -or, each naming a person by what they do.","cn":"「演员」「医生」与「雕塑家」都以同一个表示施动者的词尾收尾，都按所做的事来指人。"},{"en":"A sculptor does not add paint; the material itself is the form.","cn":"雕塑家不靠颜料，材料本身就是形体。"},{"en":"The same person may carve stone, model clay and approve a bronze cast.","cn":"同一个人可能凿石、塑泥，还要审定青铜浇铸。"},{"en":"A plaque usually names the sculptor before it names the engineer.","cn":"铭牌上通常先出现雕塑家，再出现工程师。"}],"abstract":[{"en":"Picture a block with a figure already inside it, waiting to be let out.","cn":"想象一块石头里早已藏着一个人形，等着被放出来。"},{"en":"Picture hands that trust the stone more than they trust their own plan.","cn":"想象一双手信任石头，胜过信任自己的图稿。"},{"en":"Picture a face that exists in three dimensions and changes with every step you take.","cn":"想象一张存在于三维中的脸，随你每一步移动而改变。"}]},"examples":[{"en":"The city invited a sculptor to design the memorial for the harbour.","cn":"这座城市邀请一位雕塑家为港口设计纪念碑。"},{"en":"As a sculptor, he preferred wax models to drawings.","cn":"作为雕塑家，他更偏爱蜡模而非草图。"},{"en":"The sculptor signed the base of the figure with a small chisel mark.","cn":"雕塑家在小像底座留下一个小小的凿痕作为签名。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"把 sculptor 拆成 sculpt「雕刻」加 or「做……的人」——雕刻的人就是雕塑家；谐音近「石可破它」，凿子能破开石头，破石的人正是这行工匠。","word":"sculptor"},"root":"拉丁 sculpere「雕刻、切凿」加施动后缀 -or 构成 sculptor「雕刻的人」，英语于十六世纪直接借入；同源的 sculptura 演变为英语「雕塑」一词。sculpere 的更深来源无定论，相关词根属重构形式。","sensesIntro":{"en":"Eight senses begin with the stone carver, then move to the clay modeller, the bronze caster, the commissioned professional, the fine-arts artist, the period style, the credited maker of one work and finally a shaping force in metaphor.","cn":"八个义项从凿石者出发，依次扩展到塑泥者、铸铜者、受委托的职业者、与绘画并列的造型艺术家、时期风格、某件作品的署名者，最后是比喻中的塑形力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person who removes material until a form appears, standing between a raw block and a finished figure.","cn":"核心意象：一个人不断削去材料，直到形体出现，站在原石与成品之间。"},"chain":["CUTTING STONE","ADDING CLAY","CASTING METAL","PROFESSIONAL COMMISSION","NAMED ATTRIBUTION","SHAPING FORCE"],"branches":[{"senses":"01","en":"THE CARVER: the root meaning is the person who cuts stone, with the chisel as the defining tool.","cn":"凿刻者：核心含义是切凿石材的人，凿子是其标志性工具。"},{"senses":"02 · 03","en":"OTHER METHODS: the same maker can build up soft material or send a model to the foundry for casting.","cn":"其他方法：同一位制作者可以堆加软质材料，也可以把模子交给工坊浇铸。"},{"senses":"04 · 05","en":"SOCIAL STANDING: the word moves from a paid craftsman under contract to an artist ranked with painters.","cn":"社会地位：这个词从按合约取酬的工匠，上升到与画家并列的艺术家。"},{"senses":"06 · 07","en":"THE NAME ON THE WORK: style history ties the maker to a period, and attribution ties one person to one monument.","cn":"作品上的名字：风格史把制作者系于时期，归属则把某个人系于某座纪念碑。"},{"senses":"08","en":"WITHOUT A CHISEL: the final sense keeps only the act of giving form, so time or weather can be the sculptor.","cn":"没有凿子：最后一个义项只保留赋予形体的动作，于是时间或风雨也能成为雕塑家。"}]},"affixes":{"intro":{"en":"Sculptor is transparent: a Latin verb stem, an agent suffix, and a small English family built on it.","cn":"sculptor 结构透明：一个拉丁动词词干、一个施动后缀，以及在其上构成的一小族英语词。"},"latinIntro":{"en":"Latin sculpere 'to carve' yields sculptor 'carver' and sculptura 'carving'; English borrowed both and later added sculpt and sculptural.","cn":"拉丁 sculpere「雕刻」衍生 sculptor「雕刻者」与 sculptura「雕刻」；英语把两者借入，后来又添上表示雕刻的动词与形容词。"},"items":[{"word":"sculpere","structure":"sculpere, sculpo, sculpsi (Latin verb, third conjugation)","meaning":"to carve, cut, chisel","meaningCN":"雕刻；切凿；镌刻","example":"The verb names the physical act behind every sense of the word.","exampleCN":"这个动词命名了这个词所有义项背后的具体动作。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix marks the person rather than the activity.","exampleCN":"这个后缀标记的是人，而不是活动。"},{"word":"sculptor","structure":"sculpt- + -or (Latin agent noun)","meaning":"carver, maker of sculpture","meaningCN":"雕刻者；雕塑制作者","example":"Latin used the noun for the person who cut stone or wood.","exampleCN":"拉丁语用这个名词指切凿石头或木头的人。"},{"word":"-tura","structure":"-tura (Latin noun suffix)","meaning":"the act or product of an action","meaningCN":"动作或其产物","example":"The suffix turns a verb of making into a name for the made thing.","exampleCN":"这个后缀把制作动词转为制成之物的名称。"},{"word":"sculptura","structure":"sculpt- + -tura (Latin noun)","meaning":"carving, carved work","meaningCN":"雕刻；雕成的作品","example":"The noun covered both the process and its result.","exampleCN":"这个名词同时涵盖过程与结果。"},{"word":"sculpt","structure":"sculpt (English verb, formed from sculpture)","meaning":"to carve or shape","meaningCN":"雕刻；塑形","example":"English later shortened the noun into a working verb.","exampleCN":"英语后来把名词缩短成可用的动词。"},{"word":"sculpture","structure":"sculptura, through French (English noun)","meaning":"the art or an object made in three dimensions","meaningCN":"三维造型艺术或其作品","example":"The noun names both the practice and what it produces.","exampleCN":"这个名词既指这门实践，也指其产物。"},{"word":"sculptural","structure":"sculpture + -al (from Latin -alis)","meaning":"of or like sculpture","meaningCN":"雕塑的；似雕塑的","example":"The adjective describes solid, modelled qualities in any medium.","exampleCN":"这个形容词描述任何媒介中坚实、有塑造感的特质。"}],"latinEntries":[{"word":"sculpere","structure":"sculpere, sculpo, sculpsi (v., third conjugation)","meaning":"to carve, chisel","meaningCN":"雕刻；镌刻"},{"word":"sculptor","structure":"sculptor, sculptor is (m., third declension)","meaning":"carver","meaningCN":"雕刻者"},{"word":"sculptura","structure":"sculptura, sculpturae (f., first declension)","meaning":"carving, carved work","meaningCN":"雕刻；雕成的作品"}],"derivatives":[{"word":"sculptress","structure":"sculptor + -ess (feminine agent suffix, from Old French -esse, Latin -issa)","meaning":"a woman who makes sculpture, an older marked form now little used","meaningCN":"女性雕塑家，带性别标记的旧式说法，今已少用"},{"word":"sculptural","structure":"sculpture + -al (from Latin -alis 'pertaining to')","meaning":"having the three-dimensional quality of sculpture rather than of painting","meaningCN":"具有雕塑般三维质感而非绘画质感的"}]}},{"word":"relief","ipa_uk":"/rɪˈliːf/","ipa_us":"/rɪˈliːf/","definition_zh":"浮雕；减轻；缓解；救济；（地形的）起伏","definition_en":"a raised form carved on a flat background; the easing of pain, pressure or difficulty; aid given to people in need","core_image":"一块石板上浮出半截人身，光从侧面打来，凸起处亮、凹处暗，墙面忽然有了呼吸","scene":"雨夜的战场上，泥水没过靴口，远处终于传来换防的号声，A wave of relief swept through the trench at dawn.","sceneCN":"这里 relief 指「危险解除后涌上的宽慰感」（第 3 个义项：如释重负）；句意为天亮时，一阵宽慰掠过战壕。图中可辨识物件：战壕、没过靴口的泥水、远处的号声与天边初亮的光。","pos":[{"tag":"n.","zh":"浮雕；减轻；缓解；救济"}],"collocations":[{"phrase":"a sigh of relief","zh":"松了一口气"},{"phrase":"pain relief","zh":"疼痛缓解；止痛"},{"phrase":"disaster relief","zh":"灾后救援"},{"phrase":"in relief","zh":"以浮雕形式；鲜明地"},{"phrase":"bas-relief","zh":"浅浮雕"},{"phrase":"stand out in relief","zh":"因对比而突出"}],"forms":[{"label":"复数","form":"reliefs"}],"derivatives":[{"word":"relieve","pos":"v.","zh":"减轻；缓解；解除"},{"word":"relieved","pos":"adj.","zh":"感到宽慰的"}],"senses":[{"no":"01","title":"A raised form on a flat ground","titleCN":"平面上凸起的浮雕","definition":"a form carved or moulded so that it rises above the flat surface behind it","definitionCN":"雕刻或塑造得高于背后平面的形体","example":"The marble relief above the altar shows three figures.","exampleCN":"祭坛上方的大理石浮雕表现了三个人物。","why":"The Latin verb relevare meant to lift up, and in art the lifted parts are exactly what a relief consists of.","whyCN":"拉丁动词 relevare 意为举起，而在艺术中，被举起的部分正是浮雕的构成。"},{"no":"02","title":"The easing of pain","titleCN":"疼痛或不适的减轻","definition":"the lessening of pain, pressure or physical discomfort","definitionCN":"疼痛、压力或身体不适的减轻","example":"The drug brought relief within twenty minutes.","exampleCN":"药物在二十分钟内就带来了缓解。","why":"Relevare also meant to lighten, so the medical sense keeps the image of a weight being taken off a body.","whyCN":"relevare 也有「使变轻」之义，医学义因此保留了从身体上卸下重量的意象。"},{"no":"03","title":"The feeling of a burden lifted","titleCN":"如释重负的宽慰感","definition":"the emotional state that follows the removal of worry or danger","definitionCN":"忧虑或危险解除之后的情感应激状态","example":"She laughed with relief when the results arrived.","exampleCN":"成绩送达时，她宽慰地笑了。","why":"From physical easing the word moves to the feeling, which is why relief can be something a person feels rather than receives.","whyCN":"这个词从身体的舒缓转向内心感受，因此 relief 可以是人自己感到的东西，而不只是被动领受之物。"},{"no":"04","title":"Aid to people in need","titleCN":"对困苦者的救济","definition":"money, food or help given to people affected by war, disaster or poverty","definitionCN":"给予受战争、灾害或贫困影响者的钱款、食物或援助","example":"Volunteers delivered relief to the flooded villages.","exampleCN":"志愿者把救济物资送进被洪水围困的村庄。","why":"French relief also named the help given to someone in difficulty, and English kept that practical sense.","whyCN":"法语 relief 也指给予困境中人的帮助，英语保留了这个实务义。"},{"no":"05","title":"Release from a siege","titleCN":"解围；解除围困","definition":"the lifting of a siege or the freeing of a surrounded place","definitionCN":"解除围困，或使被包围之地脱困","example":"The garrison cheered the relief of the city.","exampleCN":"守军为城市解围而欢呼。","why":"A relieving army lifts the pressure on a besieged town, which is the same lifting-off image in military form.","whyCN":"解围的军队卸去被围城镇的压力，这正是同一「抬起、卸下」意象的军事形态。"},{"no":"06","title":"A legal remedy","titleCN":"法律上的救济；司法补救","definition":"a right or remedy available to a party in a court","definitionCN":"当事人在法庭上可主张的权利或补救措施","example":"The tenant sought relief against eviction.","exampleCN":"房客就驱逐申请了法律救济。","why":"Law borrows the word for the removal of a burden imposed by a rule or a contract.","whyCN":"法律借用这个词，指解除规则或合同加于人的负担。"},{"no":"07","title":"The shape of the land","titleCN":"地势起伏","definition":"the variation in height of a land surface, shown by shading or colour on maps","definitionCN":"地表高低的变化，在地图上以阴影或颜色表示","example":"The map's shading marks the relief of the coastal plain.","exampleCN":"地图上的阴影标出了沿海平原的地势起伏。","why":"On a map the rises and falls are read as a surface standing out, which links terrain back to the carved sense.","whyCN":"在地图上，高低起伏被读作一个凸出的表面，这把地形义接回雕刻义。"},{"no":"08","title":"Standing out from a background","titleCN":"衬托下的突出效果","definition":"the effect of appearing distinct and prominent against what surrounds it","definitionCN":"在周围环境的对照下显得清晰突出的效果","example":"The dark tower stood in sharp relief against the snow.","exampleCN":"深色的塔在雪地衬托下轮廓分明。","why":"The oldest visual idea returns as a general contrast: anything that appears lifted from its ground shows in relief.","whyCN":"最古老的视觉观念以一般性对比回归：凡显得从背景上浮起之物，都以浮雕般的效果显现。"}],"etymology":{"intro":{"en":"Relief reaches English through French from Latin relevare 'to lift up, lighten', formed from re- 'back' and levare 'to raise'. The senses of easing and of raised carving come from the same verb. Dates are approximate.","cn":"relief 经法语进入英语，源自拉丁 relevare「举起、使轻」，由 re-「往回」与 levare「举起」构成；减轻义与浮雕凸起义同出一源。年代均为约数。"},"items":[{"era":"LATIN LEVIS","en":"Levis meant 'light, not heavy'. Source uncertain: its deeper origin is not established, so any root proposed for it is a reconstruction rather than a witnessed form.","cn":"levis 意为「轻的、不重的」。来源不确定：其更深的来源并无定论，凡为其提出的词根均属重构形式，而非实际书证。"},{"era":"LATIN LEVARE","en":"Levare, formed on levis, meant 'to raise, lift, lighten'; raising something and making it lighter were one action in the word.","cn":"levare 由 levis 构成，意为「举起、抬起、使轻」；在这个词里，举起某物与使它变轻是同一个动作。"},{"era":"LATIN RELEVARE","en":"The prefix re- added the idea of lifting back or away, giving relevare 'to lift up, relieve, ease'.","cn":"前缀 re- 加入「往回、移开」之意，构成 relevare「举起、解除、使舒缓」。"},{"era":"FRENCH RELIEF","en":"Old French relief, from relever, carried both the raised form and the sense of help or easing.","cn":"古法语 relief 出自 relever，同时携带「凸起之形」与「援助、舒缓」两义。"},{"era":"ENGLISH RELIEF","en":"English took relief in the fourteenth century through Anglo-Norman, first for aid and easing, then for raised carving.","cn":"英语在十四世纪经盎格鲁-诺曼语借入 relief，先指援助与舒缓，后指凸起的雕刻。"},{"era":"TWO SENSES TOGETHER","en":"The physical and the emotional senses stayed in one word because they descend from one verb; art writing made relief the standard term for raised carving.","cn":"物理义与情感义之所以留在一个词里，是因为它们同出一动词；艺术写作使 relief 成为凸起雕刻的标准术语。"}]},"similar":{"note":{"en":"The first group holds words that look close to relief but belong to other roots or other parts of speech; the second holds words for raised work and for the easing that relief also names.","cn":"第一组是与 relief 形近、却属其他词根或其他词性的词；第二组指凸起的作品，也指 relief 所表示的舒缓。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relieve","ipa":"/rɪˈliːv/","tag":"same family, verb","definition":"To ease or remove a burden; the verb puts the action first, while relief names the state or the aid.","definitionCN":"减轻或卸除负担；动词侧重动作，relief 侧重状态或援助。"},{"word":"relive","ipa":"/ˌriːˈlɪv/","tag":"different root","definition":"To live through an event again in memory; it is re- plus live, not re- plus levare.","definitionCN":"在记忆中重新经历某事；它由表示「重新」的前缀加表示「生活、经历」的词构成，而非「举起」词族。"},{"word":"belief","ipa":"/bɪˈliːf/","tag":"different root","definition":"Acceptance that something is true; it comes from an Old English root meaning 'to believe', not from levare.","definitionCN":"认为某事为真的接受态度；来自古英语中意为「相信」的词根，与 levare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bas-relief","ipa":"/ˌbɑː rɪˈliːf/","tag":"type of relief","definition":"Carving in which the figures project only slightly from the background; it is one degree of relief rather than a synonym.","definitionCN":"人物仅略微凸出背景的雕刻；它是浮雕的一种程度，而非同义词。"},{"word":"emboss","ipa":"/ɪmˈbɒs/","tag":"raising a design","definition":"To raise a design on a surface so that it stands out; the verb describes the making, relief describes the result.","definitionCN":"在表面上把图案顶起使其凸出；动词描述制作，relief 描述结果。"},{"word":"comfort","ipa":"/ˈkʌmfət/","tag":"emotional easing","definition":"Easing of grief or pain, or a thing that gives such ease; it is close to the emotional sense of relief.","definitionCN":"悲伤或痛苦的舒缓，或带来这种舒缓之物；接近 relief 的情感义。"},{"word":"aid","ipa":"/eɪd/","tag":"material help","definition":"Help, especially goods or money given to those in need; it matches the practical sense of relief.","definitionCN":"帮助，尤指给予困苦者的物资或钱款；对应 relief 的实务义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real word family and the situations in which relief actually appears.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及 relief 实际出现的场景。"},"normal":[{"en":"Re- 'back' plus levare 'to lift' gives the sense of lifting a weight off someone.","cn":"re-「往回」加 levare「举起」，就是把人身上的重量抬走。"},{"en":"Relieve, relief and relieved share one stem, so the verb, the state and the feeling travel together.","cn":"「缓解」「宽慰」「感到宽慰的」共享同一词干，动作、状态与感受因此同行。"},{"en":"Raised carving is called relief because the figures are lifted out of the stone.","cn":"凸起的雕刻叫 relief，因为人物是从石头里被举出来的。"},{"en":"A sigh of relief is a weight leaving the chest.","cn":"松一口气，就是重量离开胸口。"},{"en":"Maps show relief by shading, as if the land were carved and lit from one side.","cn":"地图用明暗显示地势，仿佛大地被刻过并从一侧打光。"}],"abstract":[{"en":"Picture a stone that keeps only the parts of a body that would catch the sun.","cn":"想象一块石头只保留身体上会迎到阳光的那些部分。"},{"en":"Picture a breath let out so slowly that it can be seen leaving the room.","cn":"想象一口气缓缓吐出，慢到能看见它离开房间。"},{"en":"Picture a dark shape that becomes visible only because of the snow behind it.","cn":"想象一个深色形体，只因背后的雪才被看见。"}]},"examples":[{"en":"The museum's bronze relief had been polished by generations of hands.","cn":"博物馆里那件青铜浮雕被一代代人的手摩挲得发亮。"},{"en":"News of the safe return brought visible relief to the whole street.","cn":"平安归来的消息让整条街都明显松了口气。"},{"en":"The agency sends relief to regions cut off by landslides.","cn":"该机构向被滑坡切断联系的地区运送救济物资。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"把 relief 听成「累里浮」——累到极点时浮上来一口气，那就是缓解；石头表面浮起来的那一层，就是浮雕。两义都绕着「抬起、卸下」这个动作。","word":"relief"},"root":"拉丁 levare「举起、使轻」（源于 levis「轻的」）加前缀 re-「往回、移开」构成 relevare「举起、解除、使舒缓」；经法语 relief 进入英语，兼有「减轻」与「浮雕凸起」两义。levis 的更深来源无定论，相关词根属重构形式。","sensesIntro":{"en":"Eight senses begin with raised carving, pass through the easing of pain and the feeling of release, then aid, siege, law and terrain, and end with the visual effect of standing out from a ground.","cn":"八个义项从凸起的浮雕出发，经过疼痛减轻与如释重负的感受，再到救济、解围、法律救济与地势起伏，最后收于从背景中突出的视觉效果。"},"semanticMap":{"core":{"en":"CORE IMAGE: something lifted above a flat ground, whether a carved figure or a weight taken off a person.","cn":"核心意象：某物被抬离平面，无论那是雕出的人形，还是从人身上卸下的重量。"},"chain":["RAISED SURFACE","LIFTING A BURDEN","EASING OF PAIN","AID TO THE NEEDY","RELEASE FROM SIEGE","STANDING OUT FROM GROUND"],"branches":[{"senses":"01","en":"THE LIFTED STONE: the first sense is physical, a figure left standing above the flat face of the block.","cn":"被举起的石头：第一个义项是物理性的，人物留在石块平面之上。"},{"senses":"02 · 03","en":"THE LIFTED WEIGHT: pain is lightened, and the mind that felt the weight reports relief as a feeling.","cn":"被卸下的重量：疼痛变轻，感到那份重量的人则把 relief 报告为一种感受。"},{"senses":"04","en":"HELP THAT LIFTS: the same word serves for material aid given to people under disaster or poverty.","cn":"托举式的帮助：同一个词也用于给受灾或贫困者的实物援助。"},{"senses":"05 · 06","en":"RELEASE FROM PRESSURE: a besieging army withdraws, or a rule stops pressing on a party in court.","cn":"压力解除：围城的军队撤走，或规则不再压在某位当事人身上。"},{"senses":"07 · 08","en":"THE SURFACE READS AS RELIEF: terrain on a map and a dark shape against snow both appear raised from their ground.","cn":"表面被读成浮雕：地图上的地形与雪地上的深色形体，都显得从背景上凸起。"}]},"affixes":{"intro":{"en":"Relief is built from a small Latin verb family plus one French reshaping, and English added a matching verb and adjective.","cn":"relief 由一小族拉丁动词加一次法语改造构成，英语又补上对应的动词与形容词。"},"latinIntro":{"en":"Latin levis 'light' gives levare 'to raise'; re- plus levare makes relevare, whose French descendant relief supplies both the easing and the raised-carving senses.","cn":"拉丁 levis「轻的」衍生 levare「举起」；re- 加 levare 构成 relevare，其法语后裔 relief 同时提供「减轻」与「浮雕」两义。"},"items":[{"word":"levis","structure":"levis, leve (Latin adjective, third declension)","meaning":"light, not heavy","meaningCN":"轻的；不重的","example":"The adjective supplies the idea of weight that the whole family carries.","exampleCN":"这个形容词提供了整族词所携带的重量观念。"},{"word":"levare","structure":"levare, levo, levavi (Latin verb, first conjugation)","meaning":"to raise, lift, lighten","meaningCN":"举起；抬起；使轻","example":"The verb joins lifting and lightening in a single action.","exampleCN":"这个动词把举起与使轻合并为同一个动作。"},{"word":"re-","structure":"re- (Latin prefix)","meaning":"back, again, away","meaningCN":"往回；再次；移开","example":"The prefix adds the direction of lifting something away.","exampleCN":"这个前缀加入把某物抬走的方向。"},{"word":"relevare","structure":"re- + levare (Latin verb)","meaning":"to lift up, relieve, ease","meaningCN":"举起；解除；使舒缓","example":"The compound is the single source of every English sense.","exampleCN":"这个复合词是英语各义项的唯一源头。"},{"word":"-atio","structure":"-atio, -ationis (Latin noun-of-action suffix)","meaning":"the act or process","meaningCN":"动作或过程","example":"The suffix turns the verb into a name for the action.","exampleCN":"这个后缀把动词转为动作的名称。"},{"word":"relevatio","structure":"relevare + -atio (Latin noun)","meaning":"a lifting up, an easing","meaningCN":"举起；舒缓","example":"Latin could name the easing as a process in its own right.","exampleCN":"拉丁语能把舒缓本身作为过程来命名。"},{"word":"relief","structure":"Old French relief, from relever (English noun)","meaning":"raised carving; easing; aid","meaningCN":"浮雕；减轻；救济","example":"French passed the whole bundle of senses to English.","exampleCN":"法语把这一整束义项传给了英语。"},{"word":"relieve","structure":"Old French relever, from Latin relevare (English verb)","meaning":"to ease, free from a burden","meaningCN":"减轻；解除负担","example":"English rebuilt the verb beside the noun.","exampleCN":"英语在名词旁重建了动词。"}],"latinEntries":[{"word":"levis","structure":"levis, leve (adj., third declension)","meaning":"light, not heavy","meaningCN":"轻的；不重的"},{"word":"levare","structure":"levare, levo, levavi (v., first conjugation)","meaning":"to raise, lighten","meaningCN":"举起；使轻"},{"word":"relevare","structure":"re- + levare (v., first conjugation)","meaning":"to lift up, ease","meaningCN":"举起；舒缓"}],"derivatives":[{"word":"relieved","structure":"relieve + -ed (English past-participle adjective)","meaning":"freed from worry or pain, describing the person rather than the act","meaningCN":"摆脱忧虑或痛苦的，描述人而非动作"},{"word":"reliever","structure":"relieve + -er (English agent noun suffix)","meaning":"one who or that which gives relief, such as a medicine or a shift worker","meaningCN":"给予缓解的人或物，如药物或换班者"}]}}]);
